-- Research Methodology Orientation: book content (generated by npm run export:content; do not edit by hand).
-- Run in Supabase → SQL Editor AFTER schema.sql. Run it again whenever the chapters are updated.
insert into public.book_content (id, data, updated_at)
values ('book', $book${"version":1,"CORE":[{"id":"m1","no":1,"hours":5,"title":"Foundations of Educational Research","titleKn":"ಶೈಕ್ಷಣಿಕ ಸಂಶೋಧನೆಯ ಅಡಿಪಾಯ","objectives":["Explain what makes an inquiry \"research\" rather than opinion or reporting.","Distinguish basic, applied, evaluation and action research.","Relate research paradigms (positivist, interpretivist, critical, pragmatic) to questions DIETs ask.","Describe the research mandate of DIETs, DSERT and the State research ecosystem."],"lessons":[{"title":"What is educational research?","body":["Educational research is systematic, transparent inquiry into teaching, learning and the systems around them. It starts with a question, gathers evidence in a planned way, analyses it openly, and reports so that others can check and use the findings.","Three tests help separate research from routine reporting: (1) Is there a clear question? (2) Is the method planned before data are collected? (3) Can another person follow the steps and judge the conclusion?"]},{"title":"Types and paradigms","body":["Basic research builds theory (e.g. how children acquire reading in a second script). Applied research solves a known problem (why Grade 6 mathematics scores dip). Evaluation research judges a programme against its goals. Action research is done by practitioners to improve their own practice in cycles.","Paradigms are beliefs about knowledge. Positivist studies measure and test; interpretivist studies seek meanings people give to experience; critical studies examine power and equity; pragmatic studies use whatever method answers the question best. Most DIET studies are pragmatic."]},{"title":"The research cycle","body":["Identify a problem → review literature → frame questions or hypotheses → choose design and sample → build and pilot tools → seek ethical clearance → collect data → analyse → interpret → report and share → use findings.","A study is only as strong as its weakest step. The commonest weakness in district studies is a vague question, which then produces a tool that measures everything and answers nothing."]}],"karnataka":[{"title":"The research mandate in Karnataka","text":["DSERT is the State academic authority for school education in Karnataka. It sets the research agenda, trains DIET faculty and publishes research compendia. Each DIET is expected to carry out district-level studies that inform teacher education and classroom practice, often with CRPs and BRPs as field partners.","Ask: of the studies your DIET completed in the last three years, how many changed a training module, a district plan or a classroom practice? That is the real test of research use."]},{"title":"Classifying real district questions","text":["\"Does Sethubandha (the start-of-year bridge programme) close learning gaps in Grade 4?\" — evaluation research.","\"How do teachers in Lambani tandas in Vijayapura use the home language during Kannada lessons?\" — interpretivist, qualitative.","\"Can I raise my D.El.Ed. trainees' questioning skills through micro-teaching?\" — action research by a DIET lecturer."]}],"activity":{"title":"Sort the studies","prompt":"List three studies done at your DIET. For each, note its type (basic / applied / evaluation / action), its paradigm, and one decision it informed (or could have)."},"tools":["rq"],"quiz":[{"q":"A DIET studies whether Kalika Chetarike learning-recovery materials met their stated goals. This is best called…","options":["Basic research","Evaluation research","Historical research","Action research"],"answer":1,"why":"It judges a programme against its own objectives."},{"q":"Which feature most separates research from a monitoring report?","options":["Use of tables","A planned method to answer a stated question","Length of the report","Signature of an officer"],"answer":1,"why":"Research begins from a question and a method fixed before data collection."},{"q":"A study of the meanings SDMC members give to \"a good school\" sits mainly in which paradigm?","options":["Positivist","Interpretivist","Experimental","Econometric"],"answer":1,"why":"It seeks participants' meanings, not measurement."},{"q":"The pragmatic paradigm means…","options":["Only surveys are allowed","The question decides the method","Qualitative data are ignored","No theory is needed"],"answer":1,"why":"Pragmatists choose methods for fitness to the question."}]},{"id":"m2","no":2,"hours":3,"title":"Research Ethics and Integrity","titleKn":"ಸಂಶೋಧನಾ ನೈತಿಕತೆ ಮತ್ತು ಪ್ರಾಮಾಣಿಕತೆ","objectives":["Apply respect, beneficence and justice to studies with children and teachers.","Obtain informed consent from parents and assent from children.","Protect identity and data, including SATS identifiers.","Recognise plagiarism, fabrication and falsification."],"lessons":[{"title":"Core principles","body":["Respect for persons: people decide freely whether to take part. Beneficence: maximise benefit, minimise harm. Justice: the burden and benefit of research are shared fairly — the same few \"convenient\" schools should not be studied every year.","Children cannot consent on their own. Seek written consent from a parent or guardian and simple oral or pictorial assent from the child, in the language the child speaks at home."]},{"title":"Ethics review","body":["An ethics (institutional review) process checks the protocol before fieldwork: purpose, risks, consent forms, data storage and how findings return to the community. A DIET can form a small ethics committee with a senior lecturer, an external academic and a community member.","Permission from the Block Education Officer to enter schools is administrative permission. It does not replace informed consent from participants."]},{"title":"Integrity","body":["Fabrication (inventing data), falsification (altering data) and plagiarism (using others' words or ideas without credit) are the three serious breaches. Copying a questionnaire from another study is acceptable only with citation and, where required, permission.","Keep raw data, field notes and analysis files so another person can trace any reported figure back to its source."]}],"karnataka":[{"title":"Using SATS data responsibly","text":["The Student Achievement Tracking System (SATS) holds identifiable records of every child in Karnataka's schools. A DIET may use SATS or LBA portal data for research only with departmental permission, and should replace SATS IDs with study codes before analysis. Never publish a child's name, SATS number or school with a small enrolment that makes children identifiable."]},{"title":"Case: photographs in a Nali Kali classroom","text":["A researcher photographs children in a Nali Kali (multigrade, activity-based, Classes 1–3) classroom for a report. Parents were not asked. Is this acceptable? No: images identify children. Seek parental consent, avoid faces where possible, and do not post on social media."]}],"activity":{"title":"Ethics decision tree","prompt":"Run your planned study through the ethics decision tree. Record which safeguards you need and draft a two-line consent statement in Kannada for parents.","tool":"ethics"},"tools":["ethics"],"quiz":[{"q":"A BEO has approved school visits. Do you still need parental consent to test children?","options":["No, BEO approval is enough","Yes, consent is separate from administrative permission","Only for private schools","Only in urban areas"],"answer":1,"why":"Administrative permission does not replace individual consent."},{"q":"Before analysing SATS records you should…","options":["Publish IDs for transparency","Replace SATS IDs with study codes","Share the file on WhatsApp for team access","Delete all records after one day"],"answer":1,"why":"Pseudonymisation protects children."},{"q":"Changing a few post-test scores so a programme looks effective is…","options":["Fabrication","Falsification","Plagiarism","Triangulation"],"answer":1,"why":"Altering real data is falsification."},{"q":"Assent means…","options":["A child's own agreement in age-appropriate form","A teacher's signature","Approval of the ethics committee","Parental consent"],"answer":0,"why":"Assent is the child's agreement alongside parental consent."}]},{"id":"m3","no":3,"hours":4,"title":"Identifying Research Problems","titleKn":"ಸಂಶೋಧನಾ ಸಮಸ್ಯೆಗಳ ಗುರುತಿಸುವಿಕೆ","objectives":["Move from a felt difficulty to a researchable problem.","Use existing evidence (NAS, PARAKH, SATS, LBA, earlier DSERT studies) to justify a problem.","Write focused research questions and testable hypotheses.","Define variables operationally."],"lessons":[{"title":"From concern to problem","body":["A felt difficulty (\"children are weak in English\") is not yet a problem. Narrow it: who (Grade 5 children in bilingual KPS sections), what (oral comprehension), where (Kalaburagi district), compared with what (Kannada-medium sections), and why it matters (equity for first-generation learners).","A good problem is significant, researchable with the time and resources you have, ethical, and new enough to add something."]},{"title":"Reviewing literature","body":["Search earlier DSERT and DIET compendia, NCERT studies, Shodhganga theses, ERIC and Google Scholar. Read for what is known, how it was measured, and what is still missing (the gap). Keep a reference list from the first day."]},{"title":"Questions, hypotheses, variables","body":["Research questions are specific and answerable: \"What is the difference in oral reading fluency between Grade 3 children in Nali Kali and non-Nali Kali classrooms in Mysuru district?\"","A hypothesis predicts an answer that data can contradict: \"Children in classrooms with a functioning library corner will read more words correct per minute than those without.\" Operational definitions say exactly how each variable is measured (e.g. words correct per minute on a graded Kannada passage)."]}],"karnataka":[{"title":"Finding a gap in State evidence","text":["The State's research background notes (in this repository) report that foundational literacy and numeracy gains made by Grade 3 tend to fade by Grades 6 and 9, especially in mathematics and science. The same notes record that no completed study yet evaluates the LBA portal. Both are ready-made gaps for DIET research.","Possible question: \"Do children who received Sethubandha bridge support in Grade 4 retain their gains at the end of Grade 5?\""]},{"title":"Narrowing a broad concern","text":["Broad: \"Library use is poor.\" Focused: \"How often do Grade 6–8 children in government higher primary schools of Chikkamagaluru district borrow library books, and what school factors are associated with borrowing?\""]}],"activity":{"title":"Build your research question","prompt":"Use the question builder to turn one concern from your district into a focused research question and a hypothesis.","tool":"rq"},"tools":["rq","literature"],"quiz":[{"q":"Which is the most researchable question?","options":["Is education improving in Karnataka?","What is the effect of LBA on Grade 7 mathematics scores in two blocks of Raichur district?","Why are teachers not motivated?","Should English be taught?"],"answer":1,"why":"It names the population, variable, place and comparison."},{"q":"\"Reading fluency will be higher where library periods are held weekly\" is a…","options":["Research question","Hypothesis","Objective","Limitation"],"answer":1,"why":"It predicts a testable relationship."},{"q":"An operational definition of \"reading fluency\" would be…","options":["Love of reading","Words correct per minute on a graded passage","Teacher's impression","Number of books in the library"],"answer":1,"why":"It states exactly how the variable is measured."},{"q":"The \"gap\" in a literature review is…","options":["Missing pages","What is not yet known or not studied in your context","Time between surveys","Difference between boys and girls"],"answer":1,"why":"The gap justifies the new study."}]},{"id":"m4","no":4,"hours":6,"title":"Quantitative Research Methods","titleKn":"ಪರಿಮಾಣಾತ್ಮಕ ಸಂಶೋಧನಾ ವಿಧಾನಗಳು","objectives":["Choose among survey, correlational, causal-comparative and experimental designs.","Select a sample and calculate its size.","Build reliable and valid tests and questionnaires.","Pick the right statistical test for a question."],"lessons":[{"title":"Designs","body":["Survey: describes a population (e.g. availability of science labs in high schools). Correlational: examines association (teacher attendance and pupil scores). Causal-comparative: compares existing groups (KPS vs non-KPS schools). Experimental and quasi-experimental: the researcher introduces an intervention and compares with a control or comparison group, ideally with pre- and post-tests.","Correlation is not causation. Schools with libraries may also have better-resourced communities."]},{"title":"Sampling","body":["Probability samples (simple random, stratified, cluster, multistage) allow generalisation. Stratify when sub-groups matter — for example by region (Kalyana Karnataka vs others), medium of instruction, or rural/urban. Cluster sampling (choose clusters, then all or some schools within) suits CRC-based fieldwork.","Sample size depends on the confidence level, the margin of error you can accept, and the variability in the population. Use the sample size calculator."]},{"title":"Tools and analysis","body":["Reliability is consistency (test–retest, Cronbach's alpha ≥ 0.70 for most scales). Validity is whether a tool measures what it claims (content validity through expert review; construct validity through pattern of results). Always pilot.","Choosing a test: compare two group means → t-test; same group before and after → paired t-test; three or more groups → ANOVA; two categorical variables → chi-square; relationship between two scores → correlation."]}],"karnataka":[{"title":"Quasi-experiment: Sethubandha in Yadgir","text":["Illustrative design: 20 government lower primary schools in Yadgir district run the Sethubandha bridge programme with an added daily 20-minute reading period (treatment); 20 matched schools run Sethubandha alone (comparison). Grade 4 children take a Kannada reading test in June and again in September. Analyse gain scores with an independent-samples t-test and report effect size (Cohen's d)."]},{"title":"Stratified sample of high schools","text":["To survey use of science laboratories across a district with 180 government high schools, stratify by Kannada, English and Urdu medium, then sample randomly within each stratum in proportion to its size."]}],"activity":{"title":"Plan a sample and a test","prompt":"For a district survey of your choice, calculate the sample size, then enter the illustrative pre/post data in the statistics tool and interpret the result in two sentences.","tool":"sample"},"tools":["sample","stats","survey"],"quiz":[{"q":"You compare SSLC mathematics scores of the same students in a pre-test and post-test. Use…","options":["Chi-square","Paired t-test","Independent t-test","ANOVA"],"answer":1,"why":"Same students measured twice."},{"q":"Comparing mean scores of Kannada, English and Urdu medium schools needs…","options":["Paired t-test","One-way ANOVA","Correlation","Content analysis"],"answer":1,"why":"Three independent groups."},{"q":"Cronbach's alpha tells you about…","options":["Validity","Internal consistency reliability","Sample size","Effect size"],"answer":1,"why":"Alpha estimates internal consistency."},{"q":"A strong correlation between library periods and reading scores proves…","options":["Libraries cause better reading","An association that may have other explanations","Nothing at all","Reading causes libraries"],"answer":1,"why":"Correlation alone does not establish cause."}]},{"id":"m5","no":5,"hours":6,"title":"Qualitative Research Methods","titleKn":"ಗುಣಾತ್ಮಕ ಸಂಶೋಧನಾ ವಿಧಾನಗಳು","objectives":["Choose among case study, ethnography, phenomenology, narrative and grounded theory.","Conduct semi-structured interviews and focus groups.","Code transcripts and develop themes.","Establish trustworthiness."],"lessons":[{"title":"Approaches","body":["Case study: in-depth study of a bounded case (one KPS campus). Ethnography: extended observation of a culture (life in an ashram school). Phenomenology: shared lived experience (first-year teachers in single-teacher schools). Narrative: life stories (women head teachers). Grounded theory: building a theory from data."]},{"title":"Data collection","body":["Semi-structured interviews use a guide of open questions with probes. Focus groups of 6–8 people suit SDMC members or parents. Observation uses field notes that separate description from interpretation. Record only with consent; transcribe in the original language and translate carefully."]},{"title":"Analysis and trustworthiness","body":["Thematic analysis: familiarise → generate initial codes → search for themes → review → define and name themes → write up with quotations. Trustworthiness rests on credibility (member checks, triangulation), transferability (thick description), dependability (audit trail) and confirmability (reflexive notes)."]}],"karnataka":[{"title":"Case study: a single-teacher school in Uttara Kannada","text":["How does one teacher manage five classes in a hilly-area school? Observe a full week, interview the teacher, SDMC president and three parents, and collect lesson plans. Expect themes such as time-sharing, peer tutoring and use of Nali Kali materials beyond Class 3."]},{"title":"Interviews on bilingual sections","text":["The State's notes record that over 60% of tribal students struggled when the medium of instruction differed from their home language. A DIET in Chamarajanagara could interview Soliga parents and teachers about bilingual KPS sections to learn what bridge support children actually need."]}],"activity":{"title":"Code an interview excerpt","prompt":"Read the teacher interview excerpts in the coding tool, assign codes, and group them into two or three themes.","tool":"coding"},"tools":["coding"],"quiz":[{"q":"Studying one KPS campus in depth over a term is a…","options":["Survey","Case study","Experiment","Meta-analysis"],"answer":1,"why":"A bounded case studied in depth."},{"q":"Member checking means…","options":["Checking attendance","Returning findings to participants to confirm accuracy","Counting codes","Random sampling"],"answer":1,"why":"Participants confirm interpretations."},{"q":"An ideal focus group size is about…","options":["2","6–8","25","50"],"answer":1,"why":"Large enough for range, small enough for everyone to speak."},{"q":"An audit trail supports…","options":["Dependability","Statistical power","Random selection","Generalisation to all States"],"answer":0,"why":"It lets others follow your decisions."}]},{"id":"m6","no":6,"hours":4,"title":"Mixed Methods Research","titleKn":"ಮಿಶ್ರ ವಿಧಾನ ಸಂಶೋಧನೆ","objectives":["Explain convergent, explanatory sequential and exploratory sequential designs.","Plan the point at which quantitative and qualitative strands meet.","Build a joint display that integrates findings."],"lessons":[{"title":"Three core designs","body":["Convergent: collect both strands at the same time and compare. Explanatory sequential: quantitative first, then qualitative to explain surprising results. Exploratory sequential: qualitative first to build a tool or hypotheses, then quantitative to test them."]},{"title":"Integration","body":["Mixing must happen somewhere — in sampling (choosing interviewees from survey results), in analysis (a joint display table that puts numbers and themes side by side), or in interpretation. Two separate reports stapled together are not mixed methods."]}],"karnataka":[{"title":"Explanatory sequential: Grade 6 dip","text":["Phase 1: analyse LBA scores for Grades 5 and 6 in a district to find schools where mathematics scores drop sharply. Phase 2: interview teachers and children in four high-drop and four low-drop schools to learn why. Integrate in a joint display: \"score pattern | teacher explanation | child explanation\"."]},{"title":"Exploratory sequential: SDMC engagement scale","text":["Focus groups with SDMC members in Bidar identify what \"active participation\" means locally; those themes become items in a questionnaire that is then administered to SDMCs across the district."]}],"activity":{"title":"Select your design","prompt":"Answer the design selector questions for your planned study and sketch a joint display with at least three rows.","tool":"mixed"},"tools":["mixed"],"quiz":[{"q":"Interviews are used to explain unexpected survey results. The design is…","options":["Convergent","Explanatory sequential","Exploratory sequential","Embedded experimental"],"answer":1,"why":"Quantitative first, qualitative explains."},{"q":"A joint display is…","options":["A poster","A table placing quantitative and qualitative findings side by side","A bar chart","A consent form"],"answer":1,"why":"It shows integration visibly."},{"q":"Building a questionnaire from focus group themes is…","options":["Exploratory sequential","Explanatory sequential","Convergent","Not mixed methods"],"answer":0,"why":"Qualitative first informs the quantitative tool."},{"q":"Which is NOT genuine mixing?","options":["Joint display","Choosing interviewees from survey results","Two unrelated reports in one cover","Comparing themes with scores"],"answer":2,"why":"Integration must occur."}]},{"id":"m7","no":7,"hours":5,"title":"Action Research for Education","titleKn":"ಶಿಕ್ಷಣದಲ್ಲಿ ಕ್ರಿಯಾ ಸಂಶೋಧನೆ","objectives":["Run plan–act–observe–reflect cycles on one's own practice.","Collect simple, usable evidence in the classroom or training hall.","Mentor teachers and CRPs in action research."],"lessons":[{"title":"The cycle","body":["Plan: name a specific problem in your practice and a change to try. Act: carry out the change for a fixed period. Observe: collect evidence (work samples, short tests, observation notes, reflections). Reflect: what changed, for whom, and why? Then plan the next cycle.","Action research is small, local and practical. Its findings are for improving your own setting first; generalisation is not its aim."]},{"title":"Evidence that teachers can manage","body":["Use what already exists: notebooks, LBA records, attendance registers. Add one simple tool such as a weekly 5-item quiz or an exit slip. Keep a reflective journal with date, what was done, what happened, and what you think it means."]}],"karnataka":[{"title":"A D.El.Ed. lecturer's cycle","text":["Problem: trainees ask only recall questions during practice teaching. Action: model \"why\" and \"what if\" questions and use peer observation with a question-type checklist for four weeks. Evidence: count of higher-order questions per lesson before and after. Reflection: gains were larger for trainees who saw a video of their own lesson — next cycle adds video review."]},{"title":"A teacher in a Kalika Chetarike classroom","text":["A Grade 5 teacher in Koppal notices that children skip the learning-sheet activities in mathematics. She introduces paired work with one stronger and one weaker reader to read the instructions aloud. After three weeks completion rates rise; she records this in her journal and shares it at the cluster meeting."]}],"activity":{"title":"Plan your first cycle","prompt":"Use the action research journal to write a full plan for one cycle and make your first reflective entry.","tool":"journal"},"tools":["journal"],"quiz":[{"q":"The correct order of an action research cycle is…","options":["Act–plan–reflect–observe","Plan–act–observe–reflect","Observe–publish–plan–act","Reflect–act–plan–publish"],"answer":1,"why":"Plan, act, observe, reflect, then repeat."},{"q":"The main aim of action research is…","options":["Generalising to all schools","Improving one's own practice","Testing theories in labs","Ranking schools"],"answer":1,"why":"It is practitioner inquiry for improvement."},{"q":"Which is a suitable low-burden evidence source for a teacher?","options":["A national survey","Exit slips","MRI scans","Census data"],"answer":1,"why":"Simple, quick, and close to practice."},{"q":"After reflection, the researcher should…","options":["Stop","Plan the next cycle","Delete data","Change the topic"],"answer":1,"why":"Action research is cyclical."}]},{"id":"m8","no":8,"hours":4,"title":"Classroom Research","titleKn":"ತರಗತಿ ಸಂಶೋಧನೆ","objectives":["Use structured and unstructured classroom observation.","Analyse children's work and assessment data.","Study multigrade and monograde classrooms fairly."],"lessons":[{"title":"Observation","body":["Structured observation uses a schedule with defined categories (e.g. teacher talk, child talk, group work, silence) recorded at fixed intervals. Unstructured observation uses running notes. Observer presence changes behaviour; visit more than once so the class gets used to you."]},{"title":"Children's work and assessment data","body":["Notebooks, worksheets, drawings and portfolios show how children think. Formative records such as LBA and the Holistic Progress Card (HPC) give longitudinal data. Look for error patterns, not just scores."]}],"karnataka":[{"title":"Observing a Nali Kali classroom","text":["In Nali Kali, children work in groups by milestone using learning cards and track their progress on a ladder. An observation schedule can record every 5 minutes: which groups are teacher-supported, partly supported or self-learning, and what each child is doing. This shows whether self-learning groups are truly engaged."]},{"title":"Error analysis in Grade 7 fractions","text":["A DIET lecturer and four teachers in Hassan collect 120 fraction worksheets. Coding the errors shows that most children add numerators and denominators separately (1/2 + 1/3 = 2/5). The finding feeds a CRC workshop on area models."]}],"activity":{"title":"Run a timed observation","prompt":"Use the observation tool during a 20-minute lesson (real or video) and summarise the pattern of classroom talk.","tool":"observation"},"tools":["observation"],"quiz":[{"q":"Recording a category every 30 seconds is…","options":["Interval-based structured observation","Narrative interview","Document analysis","Survey"],"answer":0,"why":"Fixed-interval category coding."},{"q":"Why visit a classroom several times before recording?","options":["To reduce observer effect","To increase sample size","For payment","It is not needed"],"answer":0,"why":"The class adapts to the observer."},{"q":"Analysing notebook errors is useful because…","options":["It shows thinking patterns","It replaces teaching","It ranks teachers","It is quicker than tests"],"answer":0,"why":"Errors reveal misconceptions."},{"q":"In a Nali Kali class a researcher should observe…","options":["Only the teacher","All groups, including self-learning groups","Only the brightest child","Only the blackboard"],"answer":1,"why":"Multigrade dynamics involve every group."}]},{"id":"m9","no":9,"hours":3,"title":"Community-Based Research","titleKn":"ಸಮುದಾಯ ಆಧಾರಿತ ಸಂಶೋಧನೆ","objectives":["Map stakeholders and their interests.","Engage communities as partners, not only respondents.","Handle ethics in community settings."],"lessons":[{"title":"Principles","body":["Community-based participatory research treats community members as co-researchers: they help decide questions, collect data and interpret findings. It builds trust and makes findings more likely to be used."]},{"title":"Engagement and ethics","body":["Meet in familiar spaces at times that suit farm and work schedules. Use the local language. Be clear about what the study can and cannot offer. Share results back at a Gram Sabha or SDMC meeting."]}],"karnataka":[{"title":"SDMCs as research partners","text":["School Development and Monitoring Committees (SDMCs) bring parents and local leaders into school governance. A DIET in Tumakuru can work with SDMC members to study why girls' attendance drops in Grade 8, with SDMC members conducting door-to-door conversations using a short guide."]},{"title":"Out-of-school children","text":["In a migrant-labour taluk of Kalaburagi, mapping families who leave for seasonal work helps plan Chinnara Angala bridge courses and seasonal hostels. Partners: anganwadi workers, gram panchayat, SDMCs and CRPs."]}],"activity":{"title":"Map your stakeholders","prompt":"Use the stakeholder map to list everyone affected by your planned study and decide how each will be involved.","tool":"stakeholder"},"tools":["stakeholder"],"quiz":[{"q":"In participatory research, community members are…","options":["Only respondents","Co-researchers","Excluded from analysis","Paid enumerators only"],"answer":1,"why":"They share in decisions."},{"q":"A good place to return findings in a village is…","options":["A journal only","An SDMC or Gram Sabha meeting","A private email","Nowhere"],"answer":1,"why":"Findings should return to the community."},{"q":"Which is a stakeholder in a study on girls' attendance?","options":["Parents","SDMC","Anganwadi worker","All of these"],"answer":3,"why":"All have interests and influence."},{"q":"Scheduling meetings during harvest is…","options":["Respectful","Likely to exclude farming families","Required","Irrelevant"],"answer":1,"why":"Timing affects who can take part."}]},{"id":"m10","no":10,"hours":8,"title":"Data Collection and Analysis","titleKn":"ದತ್ತಾಂಶ ಸಂಗ್ರಹ ಮತ್ತು ವಿಶ್ಲೇಷಣೆ","objectives":["Design forms that reduce error.","Train field investigators and monitor quality.","Clean, code and manage data.","Run descriptive and inferential analyses and interpret them."],"lessons":[{"title":"Planning fieldwork","body":["Pilot every tool in 2–3 schools not in the sample. Write an investigator manual. Train CRPs or student-teachers who will collect data, including mock interviews. Plan visits so that schools are not visited on exam days or festival days."]},{"title":"Data management","body":["Create a codebook: variable name, label, values, missing-data codes. Enter data twice or check 10% of forms. Store files with dated versions, keep a master copy read-only, and back up."]},{"title":"Analysis and interpretation","body":["Start with descriptives: n, mean, median, SD, frequencies. Then test hypotheses. Report the test, statistic, degrees of freedom, p-value and effect size: \"t(38) = 2.41, p = .021, d = 0.76\". Statistical significance is not the same as practical importance.","For qualitative data, use the coding and thematic steps from Module 5. Spreadsheet software such as LibreOffice Calc is enough for most DIET studies; JASP and R are free for more advanced work."]}],"karnataka":[{"title":"Worked example: chi-square on library borrowing","text":["Illustrative data from 200 Grade 7 children in Mandya district: of 100 girls, 62 borrowed a library book in the past month; of 100 boys, 45 did. Is borrowing associated with gender? Enter the 2×2 table (62, 38 / 45, 55) in the chi-square tool. The result (χ² ≈ 5.8, p ≈ .016) suggests an association; follow up with interviews to understand why."]},{"title":"Worked example: ANOVA across mediums","text":["Illustrative LBA mathematics scores (out of 20) from three schools each of Kannada, English and Urdu medium. Run one-way ANOVA; if significant, examine which pairs differ and look for explanations beyond medium (teacher vacancies, enrolment size)."]}],"activity":{"title":"Analyse the worked data","prompt":"Run the chi-square example and one ANOVA in the statistics tool. Write a results paragraph in APA style.","tool":"stats"},"tools":["stats","survey","coding"],"quiz":[{"q":"A codebook records…","options":["Passwords","Variable names, labels and value codes","Teacher salaries","Only missing data"],"answer":1,"why":"It documents how data are coded."},{"q":"p = .03 means…","options":["The effect is large","If there were no real effect, a result this extreme would occur about 3% of the time","The hypothesis is 97% true","The data are wrong"],"answer":1,"why":"p is about data under the null hypothesis."},{"q":"Effect size is reported because…","options":["It shows practical size of a difference","Journals need numbers","It replaces the mean","It is the p-value"],"answer":0,"why":"Significance ≠ importance."},{"q":"Tools should be piloted in…","options":["Sample schools","Schools similar to but outside the sample","The DIET office","No schools"],"answer":1,"why":"Avoid contaminating the sample."}]},{"id":"m11","no":11,"hours":6,"title":"Research Communication","titleKn":"ಸಂಶೋಧನಾ ಸಂವಹನ","objectives":["Write a research report with a standard structure.","Cite sources in APA style.","Present findings to teachers, officers and communities.","Prepare a policy brief and a poster."],"lessons":[{"title":"Report structure","body":["Title, abstract (150–250 words), introduction and problem, review of literature, objectives and questions, method (design, sample, tools, procedure, ethics), results, discussion, recommendations, limitations, references, appendices (tools, consent forms)."]},{"title":"Writing for different readers","body":["Officers need a two-page policy brief: the problem, three key findings, three actions, and cost or feasibility. Teachers need practical classroom implications. Communities need a short talk in Kannada with pictures. Academics need the full report or a journal article."]},{"title":"Citing and publishing","body":["Use APA 7th edition: Author, A. A. (Year). Title. Publisher. Check journals against the UGC-CARE list and avoid predatory journals that charge fees without real peer review. Share at DSERT research conferences and district review meetings."]}],"karnataka":[{"title":"From report to decision","text":["A DIET study finds that only a minority of high schools use their science laboratory weekly (illustrative). A good policy brief to the Deputy Director (Administration) and the DIET Principal would recommend: a weekly lab period in the timetable, a short CRC training on low-cost experiments, and a follow-up check in the next academic year."]}],"activity":{"title":"Draft your proposal","prompt":"Use the proposal builder to draft a complete research proposal. Export it and share it with your facilitator.","tool":"proposal"},"tools":["proposal","literature"],"quiz":[{"q":"A policy brief for officers should be…","options":["100 pages","About two pages with clear actions","Only tables","In academic jargon"],"answer":1,"why":"Busy decision-makers need brevity and action."},{"q":"Where should the ethics procedure be described?","options":["Abstract only","Method section","References","Not at all"],"answer":1,"why":"Ethics is part of method."},{"q":"Predatory journals are those that…","options":["Publish quickly after real peer review","Charge fees without genuine peer review","Are in Kannada","Are on UGC-CARE"],"answer":1,"why":"They lack genuine review."},{"q":"APA reference order is…","options":["Title, Year, Author","Author, Year, Title, Source","Year, Publisher, Author","Any order"],"answer":1,"why":"Author–date system."}]},{"id":"m12","no":12,"hours":6,"title":"Quality Assurance in Research","titleKn":"ಸಂಶೋಧನೆಯಲ್ಲಿ ಗುಣಮಟ್ಟ ಭರವಸೆ","objectives":["Review a study against quality criteria at each stage.","Conduct and receive constructive peer review.","Identify common threats to validity in district studies."],"lessons":[{"title":"Quality across the cycle","body":["Question: clear, focused, justified. Design: matches the question. Sample: adequate and well described. Tools: piloted, reliable, valid. Analysis: appropriate tests, effect sizes, honest reporting of non-significant results. Conclusions: follow from evidence; limitations stated."]},{"title":"Threats to validity","body":["Selection bias (only \"good\" schools chosen), history (another programme started at the same time), maturation (children grow anyway), testing effects (same test twice), attrition (children absent at post-test), and Hawthorne effect (people change because they are watched)."]},{"title":"Peer review","body":["Review the work, not the person. Start with strengths, then the most important problems, then minor points. Suggest specific improvements. Every DIET study can be reviewed by one internal and one external colleague before submission."]}],"karnataka":[{"title":"Review practice: a weak design","text":["Proposal: \"Effect of Kalika Chetarike on learning\" using only post-test scores from 5 schools chosen by the BEO. Problems: no baseline, no comparison, selection bias. Improvement: use the Sethubandha baseline as pre-test, add matched comparison schools, select schools randomly within blocks."]},{"title":"A shared State agenda","text":["The State's research notes suggest a yearly State research agenda with a few statewide questions — for example, whether FLN gains last beyond Grade 3 — so that districts can pool samples using common tools. Quality improves when DIETs share designs and tools rather than each starting alone."]}],"activity":{"title":"Peer-review a proposal","prompt":"Apply the quality checklist to your own proposal and to a colleague's. Record three strengths and three specific improvements.","tool":"quality"},"tools":["quality"],"quiz":[{"q":"Schools chosen by an officer because they \"perform well\" introduce…","options":["Maturation","Selection bias","Reliability","Triangulation"],"answer":1,"why":"Non-random choice biases results."},{"q":"Children improving simply because they grew older over the year is…","options":["Maturation","History","Attrition","Instrumentation"],"answer":0,"why":"Natural development over time."},{"q":"A good peer review begins with…","options":["Personal criticism","Strengths of the work","Rejection","Spelling errors only"],"answer":1,"why":"Constructive review acknowledges strengths first."},{"q":"Reporting non-significant results is…","options":["Dishonest","Part of honest research","Forbidden","Unnecessary"],"answer":1,"why":"Hiding them biases the evidence base."}]}],"PRE":[{"q":"A hypothesis is…","options":["A summary of findings","A testable prediction","A list of references","A sampling method"],"answer":1,"why":"It predicts a relationship that data can test."},{"q":"Which design best tests whether a new reading programme causes improvement?","options":["Single survey","Quasi-experiment with comparison group and pre-test","One interview","Document review"],"answer":1,"why":"A comparison group and baseline help rule out other explanations."},{"q":"Triangulation means…","options":["Using three schools","Checking findings with different data sources or methods","A geometry test","Three researchers signing"],"answer":1,"why":"Multiple sources strengthen credibility."},{"q":"Which statistic describes spread?","options":["Mean","Standard deviation","Mode","Median"],"answer":1,"why":"SD measures dispersion."},{"q":"Informed consent requires…","options":["Only the head teacher's signature","Participants understanding the study and agreeing freely","Payment","BEO approval only"],"answer":1,"why":"Understanding and voluntary agreement."}],"KN_CORE":{"m1":{"objectives":["ಅಭಿಪ್ರಾಯ ಅಥವಾ ವರದಿಗಿಂತ \"ಸಂಶೋಧನೆ\" ಹೇಗೆ ಭಿನ್ನ ಎಂಬುದನ್ನು ವಿವರಿಸುವುದು.","ಮೂಲ, ಅನ್ವಯಿಕ, ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ಕ್ರಿಯಾ ಸಂಶೋಧನೆಗಳನ್ನು ಪ್ರತ್ಯೇಕಿಸುವುದು.","ಸಂಶೋಧನಾ ದೃಷ್ಟಿಕೋನಗಳನ್ನು (ಪ್ರತ್ಯಕ್ಷವಾದಿ, ವ್ಯಾಖ್ಯಾನವಾದಿ, ವಿಮರ್ಶಾತ್ಮಕ, ವ್ಯಾವಹಾರಿಕ) ಡಯಟ್‌ಗಳು ಕೇಳುವ ಪ್ರಶ್ನೆಗಳಿಗೆ ಜೋಡಿಸುವುದು.","ಡಯಟ್, ಡಿಎಸ್‌ಇಆರ್‌ಟಿ ಮತ್ತು ರಾಜ್ಯದ ಸಂಶೋಧನಾ ವ್ಯವಸ್ಥೆಯ ಹೊಣೆಗಾರಿಕೆಯನ್ನು ವಿವರಿಸುವುದು."],"lessons":[{"title":"ಶೈಕ್ಷಣಿಕ ಸಂಶೋಧನೆ ಎಂದರೇನು?","body":["ಶೈಕ್ಷಣಿಕ ಸಂಶೋಧನೆ ಎಂದರೆ ಬೋಧನೆ, ಕಲಿಕೆ ಮತ್ತು ಅವುಗಳ ಸುತ್ತಲಿನ ವ್ಯವಸ್ಥೆಗಳ ಬಗ್ಗೆ ಕ್ರಮಬದ್ಧ ಹಾಗೂ ಪಾರದರ್ಶಕ ಅನ್ವೇಷಣೆ. ಅದು ಒಂದು ಪ್ರಶ್ನೆಯಿಂದ ಆರಂಭವಾಗುತ್ತದೆ, ಯೋಜಿತ ರೀತಿಯಲ್ಲಿ ಪುರಾವೆ ಸಂಗ್ರಹಿಸುತ್ತದೆ, ಮುಕ್ತವಾಗಿ ವಿಶ್ಲೇಷಿಸುತ್ತದೆ ಮತ್ತು ಇತರರು ಪರಿಶೀಲಿಸಿ ಬಳಸಲು ಸಾಧ್ಯವಾಗುವಂತೆ ವರದಿ ಮಾಡುತ್ತದೆ.","ಸಂಶೋಧನೆಯನ್ನು ದೈನಂದಿನ ವರದಿಯಿಂದ ಬೇರ್ಪಡಿಸಲು ಮೂರು ಪರೀಕ್ಷೆಗಳು: (1) ಸ್ಪಷ್ಟ ಪ್ರಶ್ನೆ ಇದೆಯೇ? (2) ದತ್ತಾಂಶ ಸಂಗ್ರಹಕ್ಕೆ ಮೊದಲೇ ವಿಧಾನ ಯೋಜಿತವಾಗಿದೆಯೇ? (3) ಮತ್ತೊಬ್ಬರು ಹಂತಗಳನ್ನು ಅನುಸರಿಸಿ ತೀರ್ಮಾನವನ್ನು ಪರಿಶೀಲಿಸಬಹುದೇ?"]},{"title":"ಪ್ರಕಾರಗಳು ಮತ್ತು ದೃಷ್ಟಿಕೋನಗಳು","body":["ಮೂಲ ಸಂಶೋಧನೆ ಸಿದ್ಧಾಂತವನ್ನು ಕಟ್ಟುತ್ತದೆ (ಉದಾ: ಎರಡನೇ ಲಿಪಿಯಲ್ಲಿ ಮಕ್ಕಳು ಓದು ಕಲಿಯುವ ಬಗೆ). ಅನ್ವಯಿಕ ಸಂಶೋಧನೆ ತಿಳಿದ ಸಮಸ್ಯೆಯನ್ನು ಪರಿಹರಿಸುತ್ತದೆ (6ನೇ ತರಗತಿಯಲ್ಲಿ ಗಣಿತ ಅಂಕಗಳು ಏಕೆ ಕುಸಿಯುತ್ತವೆ). ಮೌಲ್ಯಮಾಪನ ಸಂಶೋಧನೆ ಒಂದು ಕಾರ್ಯಕ್ರಮವನ್ನು ಅದರ ಗುರಿಗಳ ಆಧಾರದಲ್ಲಿ ಅಳೆಯುತ್ತದೆ. ಕ್ರಿಯಾ ಸಂಶೋಧನೆಯನ್ನು ವೃತ್ತಿನಿರತರು ತಮ್ಮದೇ ಅಭ್ಯಾಸವನ್ನು ಚಕ್ರಗಳಲ್ಲಿ ಸುಧಾರಿಸಲು ಮಾಡುತ್ತಾರೆ.","ದೃಷ್ಟಿಕೋನಗಳು (paradigms) ಜ್ಞಾನದ ಬಗೆಗಿನ ನಂಬಿಕೆಗಳು. ಪ್ರತ್ಯಕ್ಷವಾದಿ ಅಧ್ಯಯನಗಳು ಅಳೆಯುತ್ತವೆ ಮತ್ತು ಪರೀಕ್ಷಿಸುತ್ತವೆ; ವ್ಯಾಖ್ಯಾನವಾದಿ ಅಧ್ಯಯನಗಳು ಜನರು ತಮ್ಮ ಅನುಭವಕ್ಕೆ ನೀಡುವ ಅರ್ಥಗಳನ್ನು ಹುಡುಕುತ್ತವೆ; ವಿಮರ್ಶಾತ್ಮಕ ಅಧ್ಯಯನಗಳು ಅಧಿಕಾರ ಮತ್ತು ಸಮಾನತೆಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತವೆ; ವ್ಯಾವಹಾರಿಕ ಅಧ್ಯಯನಗಳು ಪ್ರಶ್ನೆಗೆ ಉತ್ತಮವಾಗಿ ಉತ್ತರಿಸುವ ಯಾವುದೇ ವಿಧಾನವನ್ನು ಬಳಸುತ್ತವೆ. ಬಹುತೇಕ ಡಯಟ್ ಅಧ್ಯಯನಗಳು ವ್ಯಾವಹಾರಿಕವಾಗಿವೆ."]},{"title":"ಸಂಶೋಧನಾ ಚಕ್ರ","body":["ಸಮಸ್ಯೆ ಗುರುತಿಸುವಿಕೆ → ಸಾಹಿತ್ಯ ಅವಲೋಕನ → ಪ್ರಶ್ನೆಗಳು ಅಥವಾ ಊಹೆಗಳ ರಚನೆ → ವಿನ್ಯಾಸ ಮತ್ತು ಮಾದರಿ ಆಯ್ಕೆ → ಸಾಧನಗಳ ರಚನೆ ಮತ್ತು ಪ್ರಾಯೋಗಿಕ ಪರೀಕ್ಷೆ → ನೈತಿಕ ಅನುಮತಿ → ದತ್ತಾಂಶ ಸಂಗ್ರಹ → ವಿಶ್ಲೇಷಣೆ → ವ್ಯಾಖ್ಯಾನ → ವರದಿ ಮತ್ತು ಹಂಚಿಕೆ → ಫಲಿತಾಂಶಗಳ ಬಳಕೆ.","ಒಂದು ಅಧ್ಯಯನ ಅದರ ಅತ್ಯಂತ ದುರ್ಬಲ ಹಂತದಷ್ಟೇ ಬಲಿಷ್ಠ. ಜಿಲ್ಲಾ ಅಧ್ಯಯನಗಳಲ್ಲಿ ಸಾಮಾನ್ಯ ದೌರ್ಬಲ್ಯ ಅಸ್ಪಷ್ಟ ಪ್ರಶ್ನೆ; ಅದರಿಂದ ಎಲ್ಲವನ್ನೂ ಅಳೆಯುವ ಆದರೆ ಯಾವುದಕ್ಕೂ ಉತ್ತರಿಸದ ಸಾಧನ ಹುಟ್ಟುತ್ತದೆ."]}],"karnataka":[{"title":"ಕರ್ನಾಟಕದಲ್ಲಿ ಸಂಶೋಧನಾ ಹೊಣೆಗಾರಿಕೆ","text":["ಡಿಎಸ್‌ಇಆರ್‌ಟಿ ಕರ್ನಾಟಕದ ಶಾಲಾ ಶಿಕ್ಷಣದ ರಾಜ್ಯ ಶೈಕ್ಷಣಿಕ ಪ್ರಾಧಿಕಾರ. ಅದು ಸಂಶೋಧನಾ ಕಾರ್ಯಸೂಚಿಯನ್ನು ರೂಪಿಸುತ್ತದೆ, ಡಯಟ್ ಉಪನ್ಯಾಸಕರಿಗೆ ತರಬೇತಿ ನೀಡುತ್ತದೆ ಮತ್ತು ಸಂಶೋಧನಾ ಸಂಗ್ರಹಗಳನ್ನು ಪ್ರಕಟಿಸುತ್ತದೆ. ಪ್ರತಿ ಡಯಟ್ ಶಿಕ್ಷಕ ಶಿಕ್ಷಣ ಮತ್ತು ತರಗತಿ ಅಭ್ಯಾಸಕ್ಕೆ ಮಾರ್ಗದರ್ಶನ ನೀಡುವ ಜಿಲ್ಲಾ ಮಟ್ಟದ ಅಧ್ಯಯನಗಳನ್ನು ನಡೆಸಬೇಕು; ಸಿಆರ್‌ಪಿ ಮತ್ತು ಬಿಆರ್‌ಪಿಗಳು ಸಾಮಾನ್ಯವಾಗಿ ಕ್ಷೇತ್ರ ಪಾಲುದಾರರು.","ಕೇಳಿಕೊಳ್ಳಿ: ಕಳೆದ ಮೂರು ವರ್ಷಗಳಲ್ಲಿ ನಿಮ್ಮ ಡಯಟ್ ಪೂರ್ಣಗೊಳಿಸಿದ ಅಧ್ಯಯನಗಳಲ್ಲಿ ಎಷ್ಟು ತರಬೇತಿ ಘಟಕ, ಜಿಲ್ಲಾ ಯೋಜನೆ ಅಥವಾ ತರಗತಿ ಅಭ್ಯಾಸವನ್ನು ಬದಲಾಯಿಸಿದವು? ಸಂಶೋಧನೆಯ ಬಳಕೆಗೆ ಇದೇ ನಿಜವಾದ ಪರೀಕ್ಷೆ."]},{"title":"ನಿಜವಾದ ಜಿಲ್ಲಾ ಪ್ರಶ್ನೆಗಳ ವರ್ಗೀಕರಣ","text":["\"4ನೇ ತರಗತಿಯಲ್ಲಿ ಸೇತುಬಂಧ (ವರ್ಷಾರಂಭದ ಸೇತುಬಂಧ ಕಾರ್ಯಕ್ರಮ) ಕಲಿಕಾ ಅಂತರವನ್ನು ತುಂಬುತ್ತದೆಯೇ?\" — ಮೌಲ್ಯಮಾಪನ ಸಂಶೋಧನೆ.","\"ವಿಜಯಪುರದ ಲಂಬಾಣಿ ತಾಂಡಾಗಳ ಶಿಕ್ಷಕರು ಕನ್ನಡ ಪಾಠಗಳಲ್ಲಿ ಮನೆಮಾತನ್ನು ಹೇಗೆ ಬಳಸುತ್ತಾರೆ?\" — ವ್ಯಾಖ್ಯಾನವಾದಿ, ಗುಣಾತ್ಮಕ.","\"ಸೂಕ್ಷ್ಮ ಬೋಧನೆಯ (micro-teaching) ಮೂಲಕ ನನ್ನ ಡಿ.ಇಎಲ್.ಇಡಿ. ಪ್ರಶಿಕ್ಷಣಾರ್ಥಿಗಳ ಪ್ರಶ್ನಿಸುವ ಕೌಶಲವನ್ನು ಹೆಚ್ಚಿಸಬಹುದೇ?\" — ಡಯಟ್ ಉಪನ್ಯಾಸಕರ ಕ್ರಿಯಾ ಸಂಶೋಧನೆ."]}],"activity":{"title":"ಅಧ್ಯಯನಗಳನ್ನು ವರ್ಗೀಕರಿಸಿ","prompt":"ನಿಮ್ಮ ಡಯಟ್‌ನಲ್ಲಿ ನಡೆದ ಮೂರು ಅಧ್ಯಯನಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ. ಪ್ರತಿಯೊಂದರ ಪ್ರಕಾರ (ಮೂಲ / ಅನ್ವಯಿಕ / ಮೌಲ್ಯಮಾಪನ / ಕ್ರಿಯಾ), ದೃಷ್ಟಿಕೋನ ಮತ್ತು ಅದು ಪ್ರಭಾವಿಸಿದ (ಅಥವಾ ಪ್ರಭಾವಿಸಬಹುದಾಗಿದ್ದ) ಒಂದು ನಿರ್ಧಾರವನ್ನು ಬರೆಯಿರಿ."},"quiz":[{"q":"ಕಲಿಕಾ ಚೇತರಿಕೆ ಸಾಮಗ್ರಿಗಳು ತಮ್ಮ ಘೋಷಿತ ಗುರಿಗಳನ್ನು ತಲುಪಿದವೇ ಎಂದು ಡಯಟ್ ಅಧ್ಯಯನ ಮಾಡುತ್ತದೆ. ಇದನ್ನು ಹೀಗೆ ಕರೆಯುವುದು ಸೂಕ್ತ…","options":["ಮೂಲ ಸಂಶೋಧನೆ","ಮೌಲ್ಯಮಾಪನ ಸಂಶೋಧನೆ","ಐತಿಹಾಸಿಕ ಸಂಶೋಧನೆ","ಕ್ರಿಯಾ ಸಂಶೋಧನೆ"],"why":"ಇದು ಕಾರ್ಯಕ್ರಮವನ್ನು ಅದರದೇ ಉದ್ದೇಶಗಳ ಆಧಾರದಲ್ಲಿ ಅಳೆಯುತ್ತದೆ."},{"q":"ಸಂಶೋಧನೆಯನ್ನು ಮೇಲ್ವಿಚಾರಣಾ ವರದಿಯಿಂದ ಹೆಚ್ಚು ಬೇರ್ಪಡಿಸುವ ಲಕ್ಷಣ ಯಾವುದು?","options":["ಕೋಷ್ಟಕಗಳ ಬಳಕೆ","ನಿರ್ದಿಷ್ಟ ಪ್ರಶ್ನೆಗೆ ಉತ್ತರಿಸಲು ಯೋಜಿತ ವಿಧಾನ","ವರದಿಯ ಉದ್ದ","ಅಧಿಕಾರಿಯ ಸಹಿ"],"why":"ಸಂಶೋಧನೆ ಪ್ರಶ್ನೆಯಿಂದ ಆರಂಭವಾಗುತ್ತದೆ; ವಿಧಾನವನ್ನು ದತ್ತಾಂಶ ಸಂಗ್ರಹಕ್ಕೆ ಮೊದಲೇ ನಿಗದಿಪಡಿಸಲಾಗುತ್ತದೆ."},{"q":"\"ಉತ್ತಮ ಶಾಲೆ\" ಎಂಬುದಕ್ಕೆ ಎಸ್‌ಡಿಎಂಸಿ ಸದಸ್ಯರು ನೀಡುವ ಅರ್ಥಗಳ ಅಧ್ಯಯನ ಮುಖ್ಯವಾಗಿ ಯಾವ ದೃಷ್ಟಿಕೋನಕ್ಕೆ ಸೇರುತ್ತದೆ?","options":["ಪ್ರತ್ಯಕ್ಷವಾದಿ","ವ್ಯಾಖ್ಯಾನವಾದಿ","ಪ್ರಾಯೋಗಿಕ","ಅರ್ಥಮಾಪನ"],"why":"ಇದು ಅಳತೆಯಲ್ಲ, ಭಾಗವಹಿಸುವವರ ಅರ್ಥಗಳನ್ನು ಹುಡುಕುತ್ತದೆ."},{"q":"ವ್ಯಾವಹಾರಿಕ ದೃಷ್ಟಿಕೋನ ಎಂದರೆ…","options":["ಸಮೀಕ್ಷೆಗಳಿಗೆ ಮಾತ್ರ ಅವಕಾಶ","ಪ್ರಶ್ನೆಯೇ ವಿಧಾನವನ್ನು ನಿರ್ಧರಿಸುತ್ತದೆ","ಗುಣಾತ್ಮಕ ದತ್ತಾಂಶ ನಿರ್ಲಕ್ಷಿತ","ಸಿದ್ಧಾಂತ ಬೇಕಿಲ್ಲ"],"why":"ಪ್ರಶ್ನೆಗೆ ಸೂಕ್ತವಾದ ವಿಧಾನವನ್ನೇ ಆಯ್ಕೆ ಮಾಡಲಾಗುತ್ತದೆ."}]},"m2":{"objectives":["ಮಕ್ಕಳು ಮತ್ತು ಶಿಕ್ಷಕರೊಂದಿಗಿನ ಅಧ್ಯಯನಗಳಲ್ಲಿ ಗೌರವ, ಹಿತಸಾಧನೆ ಮತ್ತು ನ್ಯಾಯದ ತತ್ವಗಳನ್ನು ಅನ್ವಯಿಸುವುದು.","ಪೋಷಕರಿಂದ ತಿಳುವಳಿಕೆಯುಳ್ಳ ಒಪ್ಪಿಗೆ ಮತ್ತು ಮಕ್ಕಳಿಂದ ಸಮ್ಮತಿ ಪಡೆಯುವುದು.","ಗುರುತು ಮತ್ತು ದತ್ತಾಂಶವನ್ನು, SATS ಗುರುತುಸಂಖ್ಯೆಗಳನ್ನೂ ಸೇರಿ, ರಕ್ಷಿಸುವುದು.","ಕೃತಿಚೌರ್ಯ, ಕಟ್ಟುಕಥೆ ಮತ್ತು ತಿರುಚುವಿಕೆಯನ್ನು ಗುರುತಿಸುವುದು."],"lessons":[{"title":"ಮೂಲ ತತ್ವಗಳು","body":["ವ್ಯಕ್ತಿಗಳಿಗೆ ಗೌರವ: ಭಾಗವಹಿಸಬೇಕೇ ಬೇಡವೇ ಎಂಬುದನ್ನು ಜನರು ಸ್ವತಂತ್ರವಾಗಿ ನಿರ್ಧರಿಸುತ್ತಾರೆ. ಹಿತಸಾಧನೆ: ಪ್ರಯೋಜನ ಹೆಚ್ಚಿಸಿ, ಹಾನಿ ಕಡಿಮೆ ಮಾಡಿ. ನ್ಯಾಯ: ಸಂಶೋಧನೆಯ ಹೊರೆ ಮತ್ತು ಲಾಭ ನ್ಯಾಯಯುತವಾಗಿ ಹಂಚಿಕೆಯಾಗಬೇಕು — ಪ್ರತಿವರ್ಷ ಅದೇ ಕೆಲವು \"ಅನುಕೂಲಕರ\" ಶಾಲೆಗಳನ್ನು ಅಧ್ಯಯನ ಮಾಡಬಾರದು.","ಮಕ್ಕಳು ತಾವಾಗಿಯೇ ಒಪ್ಪಿಗೆ ನೀಡಲಾರರು. ಪೋಷಕರು ಅಥವಾ ಪಾಲಕರಿಂದ ಲಿಖಿತ ಒಪ್ಪಿಗೆ ಪಡೆಯಿರಿ; ಮಗುವಿನಿಂದ ಅದರ ಮನೆಮಾತಿನಲ್ಲಿ ಸರಳ ಮೌಖಿಕ ಅಥವಾ ಚಿತ್ರ ರೂಪದ ಸಮ್ಮತಿ ಪಡೆಯಿರಿ."]},{"title":"ನೈತಿಕ ಪರಿಶೀಲನೆ","body":["ನೈತಿಕ ಪರಿಶೀಲನಾ ಪ್ರಕ್ರಿಯೆ ಕ್ಷೇತ್ರಕಾರ್ಯಕ್ಕೆ ಮುನ್ನ ಯೋಜನೆಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ: ಉದ್ದೇಶ, ಅಪಾಯಗಳು, ಒಪ್ಪಿಗೆ ಪತ್ರಗಳು, ದತ್ತಾಂಶ ಸಂಗ್ರಹಣೆ ಮತ್ತು ಫಲಿತಾಂಶಗಳು ಸಮುದಾಯಕ್ಕೆ ಹೇಗೆ ಮರಳುತ್ತವೆ ಎಂಬುದು. ಡಯಟ್ ಒಬ್ಬ ಹಿರಿಯ ಉಪನ್ಯಾಸಕರು, ಒಬ್ಬ ಹೊರಗಿನ ವಿದ್ವಾಂಸರು ಮತ್ತು ಒಬ್ಬ ಸಮುದಾಯ ಸದಸ್ಯರಿರುವ ಸಣ್ಣ ನೈತಿಕ ಸಮಿತಿಯನ್ನು ರಚಿಸಬಹುದು.","ಶಾಲೆಗಳಿಗೆ ಭೇಟಿ ನೀಡಲು ಕ್ಷೇತ್ರ ಶಿಕ್ಷಣಾಧಿಕಾರಿಗಳ ಅನುಮತಿ ಆಡಳಿತಾತ್ಮಕ ಅನುಮತಿ ಮಾತ್ರ. ಅದು ಭಾಗವಹಿಸುವವರ ತಿಳುವಳಿಕೆಯುಳ್ಳ ಒಪ್ಪಿಗೆಗೆ ಬದಲಿಯಲ್ಲ."]},{"title":"ಪ್ರಾಮಾಣಿಕತೆ","body":["ಕಟ್ಟುಕಥೆ (ದತ್ತಾಂಶ ಸೃಷ್ಟಿಸುವುದು), ತಿರುಚುವಿಕೆ (ದತ್ತಾಂಶ ಬದಲಿಸುವುದು) ಮತ್ತು ಕೃತಿಚೌರ್ಯ (ಇತರರ ಪದಗಳು ಅಥವಾ ವಿಚಾರಗಳನ್ನು ಉಲ್ಲೇಖವಿಲ್ಲದೆ ಬಳಸುವುದು) — ಇವು ಮೂರು ಗಂಭೀರ ಉಲ್ಲಂಘನೆಗಳು. ಮತ್ತೊಂದು ಅಧ್ಯಯನದ ಪ್ರಶ್ನಾವಳಿಯನ್ನು ಉಲ್ಲೇಖದೊಂದಿಗೆ ಮತ್ತು ಅಗತ್ಯವಿದ್ದಲ್ಲಿ ಅನುಮತಿಯೊಂದಿಗೆ ಮಾತ್ರ ಬಳಸಬಹುದು.","ಕಚ್ಚಾ ದತ್ತಾಂಶ, ಕ್ಷೇತ್ರ ಟಿಪ್ಪಣಿಗಳು ಮತ್ತು ವಿಶ್ಲೇಷಣಾ ಕಡತಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ; ವರದಿಯ ಯಾವುದೇ ಅಂಕಿಯನ್ನು ಅದರ ಮೂಲದವರೆಗೆ ಮತ್ತೊಬ್ಬರು ಪತ್ತೆಹಚ್ಚುವಂತಿರಬೇಕು."]}],"karnataka":[{"title":"SATS ದತ್ತಾಂಶದ ಜವಾಬ್ದಾರಿಯುತ ಬಳಕೆ","text":["ವಿದ್ಯಾರ್ಥಿ ಸಾಧನಾ ಟ್ರ್ಯಾಕಿಂಗ್ ವ್ಯವಸ್ಥೆ (SATS) ಕರ್ನಾಟಕದ ಶಾಲೆಗಳ ಪ್ರತಿ ಮಗುವಿನ ಗುರುತಿಸಬಹುದಾದ ದಾಖಲೆಗಳನ್ನು ಹೊಂದಿದೆ. ಡಯಟ್ SATS ಅಥವಾ LBA ಪೋರ್ಟಲ್ ದತ್ತಾಂಶವನ್ನು ಇಲಾಖೆಯ ಅನುಮತಿಯೊಂದಿಗೆ ಮಾತ್ರ ಸಂಶೋಧನೆಗೆ ಬಳಸಬೇಕು ಮತ್ತು ವಿಶ್ಲೇಷಣೆಗೆ ಮುನ್ನ SATS ಸಂಖ್ಯೆಗಳ ಬದಲಿಗೆ ಅಧ್ಯಯನ ಸಂಕೇತಗಳನ್ನು ಬಳಸಬೇಕು. ಮಗುವಿನ ಹೆಸರು, SATS ಸಂಖ್ಯೆ ಅಥವಾ ಮಕ್ಕಳನ್ನು ಗುರುತಿಸಬಹುದಾದಷ್ಟು ಕಡಿಮೆ ದಾಖಲಾತಿಯ ಶಾಲೆಯ ಹೆಸರನ್ನು ಎಂದಿಗೂ ಪ್ರಕಟಿಸಬೇಡಿ."]},{"title":"ಪ್ರಕರಣ: ನಲಿ-ಕಲಿ ತರಗತಿಯಲ್ಲಿ ಛಾಯಾಚಿತ್ರಗಳು","text":["ಒಬ್ಬ ಸಂಶೋಧಕರು ವರದಿಗಾಗಿ ನಲಿ-ಕಲಿ (1–3ನೇ ತರಗತಿಯ ಬಹುವರ್ಗ, ಚಟುವಟಿಕೆ ಆಧಾರಿತ) ತರಗತಿಯ ಮಕ್ಕಳ ಫೋಟೋ ತೆಗೆಯುತ್ತಾರೆ. ಪೋಷಕರನ್ನು ಕೇಳಿಲ್ಲ. ಇದು ಸರಿಯೇ? ಇಲ್ಲ: ಚಿತ್ರಗಳು ಮಕ್ಕಳನ್ನು ಗುರುತಿಸುತ್ತವೆ. ಪೋಷಕರ ಒಪ್ಪಿಗೆ ಪಡೆಯಿರಿ, ಸಾಧ್ಯವಾದಲ್ಲಿ ಮುಖಗಳನ್ನು ತಪ್ಪಿಸಿ, ಸಾಮಾಜಿಕ ಜಾಲತಾಣಗಳಲ್ಲಿ ಹಂಚಬೇಡಿ."]}],"activity":{"title":"ನೈತಿಕ ನಿರ್ಧಾರ ವೃಕ್ಷ","prompt":"ನಿಮ್ಮ ಯೋಜಿತ ಅಧ್ಯಯನವನ್ನು ನೈತಿಕ ನಿರ್ಧಾರ ವೃಕ್ಷದ ಮೂಲಕ ಹಾಯಿಸಿ. ಬೇಕಾದ ಸುರಕ್ಷತಾ ಕ್ರಮಗಳನ್ನು ದಾಖಲಿಸಿ ಮತ್ತು ಪೋಷಕರಿಗಾಗಿ ಕನ್ನಡದಲ್ಲಿ ಎರಡು ಸಾಲಿನ ಒಪ್ಪಿಗೆ ಹೇಳಿಕೆ ರಚಿಸಿ."},"quiz":[{"q":"ಶಾಲಾ ಭೇಟಿಗೆ ಬಿಇಒ ಅನುಮತಿ ನೀಡಿದ್ದಾರೆ. ಮಕ್ಕಳಿಗೆ ಪರೀಕ್ಷೆ ನಡೆಸಲು ಪೋಷಕರ ಒಪ್ಪಿಗೆ ಇನ್ನೂ ಬೇಕೇ?","options":["ಬೇಡ, ಬಿಇಒ ಅನುಮತಿ ಸಾಕು","ಬೇಕು, ಒಪ್ಪಿಗೆ ಆಡಳಿತಾತ್ಮಕ ಅನುಮತಿಗಿಂತ ಪ್ರತ್ಯೇಕ","ಖಾಸಗಿ ಶಾಲೆಗಳಿಗೆ ಮಾತ್ರ","ನಗರ ಪ್ರದೇಶಗಳಲ್ಲಿ ಮಾತ್ರ"],"why":"ಆಡಳಿತಾತ್ಮಕ ಅನುಮತಿ ವೈಯಕ್ತಿಕ ಒಪ್ಪಿಗೆಗೆ ಬದಲಿಯಲ್ಲ."},{"q":"SATS ದಾಖಲೆಗಳನ್ನು ವಿಶ್ಲೇಷಿಸುವ ಮೊದಲು ನೀವು…","options":["ಪಾರದರ್ಶಕತೆಗಾಗಿ ಸಂಖ್ಯೆಗಳನ್ನು ಪ್ರಕಟಿಸಬೇಕು","SATS ಸಂಖ್ಯೆಗಳ ಬದಲಿಗೆ ಅಧ್ಯಯನ ಸಂಕೇತಗಳನ್ನು ಬಳಸಬೇಕು","ತಂಡಕ್ಕಾಗಿ ಕಡತವನ್ನು ವಾಟ್ಸಾಪ್‌ನಲ್ಲಿ ಹಂಚಬೇಕು","ಒಂದೇ ದಿನದಲ್ಲಿ ಎಲ್ಲ ದಾಖಲೆ ಅಳಿಸಬೇಕು"],"why":"ಹುಸಿನಾಮೀಕರಣ ಮಕ್ಕಳನ್ನು ರಕ್ಷಿಸುತ್ತದೆ."},{"q":"ಕಾರ್ಯಕ್ರಮ ಪರಿಣಾಮಕಾರಿ ಎಂದು ತೋರಿಸಲು ಕೆಲವು ಉತ್ತರ-ಪರೀಕ್ಷಾ ಅಂಕಗಳನ್ನು ಬದಲಿಸುವುದು…","options":["ಕಟ್ಟುಕಥೆ","ತಿರುಚುವಿಕೆ","ಕೃತಿಚೌರ್ಯ","ತ್ರಿಕೋನೀಕರಣ"],"why":"ನಿಜವಾದ ದತ್ತಾಂಶವನ್ನು ಬದಲಿಸುವುದು ತಿರುಚುವಿಕೆ."},{"q":"ಸಮ್ಮತಿ (assent) ಎಂದರೆ…","options":["ವಯಸ್ಸಿಗೆ ತಕ್ಕ ರೂಪದಲ್ಲಿ ಮಗುವಿನ ಸ್ವಂತ ಒಪ್ಪಿಗೆ","ಶಿಕ್ಷಕರ ಸಹಿ","ನೈತಿಕ ಸಮಿತಿಯ ಅನುಮೋದನೆ","ಪೋಷಕರ ಒಪ್ಪಿಗೆ"],"why":"ಪೋಷಕರ ಒಪ್ಪಿಗೆಯ ಜೊತೆಗೆ ಮಗುವಿನ ಸ್ವಂತ ಒಪ್ಪಿಗೆಯೇ ಸಮ್ಮತಿ."}]},"m3":{"objectives":["ಅನುಭವಿಸಿದ ತೊಂದರೆಯಿಂದ ಸಂಶೋಧಿಸಬಹುದಾದ ಸಮಸ್ಯೆಯತ್ತ ಸಾಗುವುದು.","ಲಭ್ಯ ಪುರಾವೆಗಳನ್ನು (NAS, PARAKH, SATS, LBA, ಹಿಂದಿನ ಡಿಎಸ್‌ಇಆರ್‌ಟಿ ಅಧ್ಯಯನಗಳು) ಬಳಸಿ ಸಮಸ್ಯೆಯನ್ನು ಸಮರ್ಥಿಸುವುದು.","ಕೇಂದ್ರೀಕೃತ ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆಗಳು ಮತ್ತು ಪರೀಕ್ಷಿಸಬಹುದಾದ ಊಹೆಗಳನ್ನು ಬರೆಯುವುದು.","ಚರಾಂಶಗಳನ್ನು ಕಾರ್ಯಾತ್ಮಕವಾಗಿ ವ್ಯಾಖ್ಯಾನಿಸುವುದು."],"lessons":[{"title":"ಕಾಳಜಿಯಿಂದ ಸಮಸ್ಯೆಯವರೆಗೆ","body":["ಅನುಭವಿಸಿದ ತೊಂದರೆ (\"ಮಕ್ಕಳು ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ದುರ್ಬಲ\") ಇನ್ನೂ ಸಮಸ್ಯೆಯಲ್ಲ. ಅದನ್ನು ಸಂಕುಚಿಸಿ: ಯಾರು (ದ್ವಿಭಾಷಾ KPS ವಿಭಾಗಗಳ 5ನೇ ತರಗತಿ ಮಕ್ಕಳು), ಏನು (ಮೌಖಿಕ ಗ್ರಹಿಕೆ), ಎಲ್ಲಿ (ಕಲಬುರಗಿ ಜಿಲ್ಲೆ), ಯಾರೊಂದಿಗೆ ಹೋಲಿಕೆ (ಕನ್ನಡ ಮಾಧ್ಯಮ ವಿಭಾಗಗಳು), ಏಕೆ ಮುಖ್ಯ (ಮೊದಲ ತಲೆಮಾರಿನ ಕಲಿಕಾರ್ಥಿಗಳಿಗೆ ಸಮಾನತೆ).","ಉತ್ತಮ ಸಮಸ್ಯೆ ಮಹತ್ವದ್ದು, ಲಭ್ಯ ಸಮಯ ಮತ್ತು ಸಂಪನ್ಮೂಲಗಳಲ್ಲಿ ಸಂಶೋಧಿಸಬಹುದಾದದ್ದು, ನೈತಿಕವಾದದ್ದು ಮತ್ತು ಹೊಸದನ್ನು ಸೇರಿಸುವಷ್ಟು ನವೀನವಾದದ್ದು."]},{"title":"ಸಾಹಿತ್ಯ ಅವಲೋಕನ","body":["ಹಿಂದಿನ ಡಿಎಸ್‌ಇಆರ್‌ಟಿ ಮತ್ತು ಡಯಟ್ ಸಂಗ್ರಹಗಳು, ಎನ್‌ಸಿಇಆರ್‌ಟಿ ಅಧ್ಯಯನಗಳು, ಶೋಧಗಂಗಾ ಪ್ರಬಂಧಗಳು, ERIC ಮತ್ತು ಗೂಗಲ್ ಸ್ಕಾಲರ್‌ನಲ್ಲಿ ಹುಡುಕಿ. ಏನು ತಿಳಿದಿದೆ, ಅದನ್ನು ಹೇಗೆ ಅಳೆಯಲಾಯಿತು ಮತ್ತು ಇನ್ನೂ ಏನು ಉಳಿದಿದೆ (ಅಂತರ) ಎಂಬುದಕ್ಕಾಗಿ ಓದಿ. ಮೊದಲ ದಿನದಿಂದಲೇ ಉಲ್ಲೇಖ ಪಟ್ಟಿ ಇಟ್ಟುಕೊಳ್ಳಿ."]},{"title":"ಪ್ರಶ್ನೆಗಳು, ಊಹೆಗಳು, ಚರಾಂಶಗಳು","body":["ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆಗಳು ನಿರ್ದಿಷ್ಟ ಮತ್ತು ಉತ್ತರಿಸಬಹುದಾದವು: \"ಮೈಸೂರು ಜಿಲ್ಲೆಯ ನಲಿ-ಕಲಿ ಮತ್ತು ನಲಿ-ಕಲಿಯೇತರ ತರಗತಿಗಳ 3ನೇ ತರಗತಿ ಮಕ್ಕಳ ಮೌಖಿಕ ಓದಿನ ನಿರರ್ಗಳತೆಯಲ್ಲಿ ವ್ಯತ್ಯಾಸವೇನು?\"","ಊಹೆ ದತ್ತಾಂಶ ತಳ್ಳಿಹಾಕಬಹುದಾದ ಉತ್ತರವನ್ನು ಮುನ್ನುಡಿಯುತ್ತದೆ: \"ಕಾರ್ಯನಿರತ ಗ್ರಂಥಾಲಯ ಮೂಲೆ ಇರುವ ತರಗತಿಗಳ ಮಕ್ಕಳು ಇಲ್ಲದವರಿಗಿಂತ ನಿಮಿಷಕ್ಕೆ ಹೆಚ್ಚು ಪದಗಳನ್ನು ಸರಿಯಾಗಿ ಓದುತ್ತಾರೆ.\" ಕಾರ್ಯಾತ್ಮಕ ವ್ಯಾಖ್ಯಾನಗಳು ಪ್ರತಿ ಚರಾಂಶವನ್ನು ನಿಖರವಾಗಿ ಹೇಗೆ ಅಳೆಯಲಾಗುತ್ತದೆ ಎಂದು ತಿಳಿಸುತ್ತವೆ (ಉದಾ: ಶ್ರೇಣೀಕೃತ ಕನ್ನಡ ಗದ್ಯಭಾಗದಲ್ಲಿ ನಿಮಿಷಕ್ಕೆ ಸರಿಯಾಗಿ ಓದಿದ ಪದಗಳು)."]}],"karnataka":[{"title":"ರಾಜ್ಯದ ಪುರಾವೆಗಳಲ್ಲಿ ಅಂತರ ಹುಡುಕುವುದು","text":["3ನೇ ತರಗತಿಯ ವೇಳೆಗೆ ಗಳಿಸಿದ ಮೂಲಭೂತ ಸಾಕ್ಷರತೆ ಮತ್ತು ಸಂಖ್ಯಾಜ್ಞಾನದ ಲಾಭಗಳು 6 ಮತ್ತು 9ನೇ ತರಗತಿಗಳ ವೇಳೆಗೆ, ವಿಶೇಷವಾಗಿ ಗಣಿತ ಮತ್ತು ವಿಜ್ಞಾನದಲ್ಲಿ, ಮಸುಕಾಗುತ್ತವೆ ಎಂದು ರಾಜ್ಯದ ಸಂಶೋಧನಾ ಹಿನ್ನೆಲೆ ಟಿಪ್ಪಣಿಗಳು (ಈ ಭಂಡಾರದಲ್ಲಿ) ವರದಿ ಮಾಡುತ್ತವೆ. LBA ಪೋರ್ಟಲ್ ಅನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡಿದ ಯಾವುದೇ ಪೂರ್ಣ ಅಧ್ಯಯನ ಇನ್ನೂ ಇಲ್ಲ ಎಂದೂ ದಾಖಲಿಸುತ್ತವೆ. ಇವೆರಡೂ ಡಯಟ್ ಸಂಶೋಧನೆಗೆ ಸಿದ್ಧ ಅಂತರಗಳು.","ಸಂಭಾವ್ಯ ಪ್ರಶ್ನೆ: \"4ನೇ ತರಗತಿಯಲ್ಲಿ ಸೇತುಬಂಧ ಬೆಂಬಲ ಪಡೆದ ಮಕ್ಕಳು 5ನೇ ತರಗತಿಯ ಕೊನೆಯವರೆಗೆ ತಮ್ಮ ಲಾಭಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತಾರೆಯೇ?\""]},{"title":"ವಿಶಾಲ ಕಾಳಜಿಯನ್ನು ಸಂಕುಚಿಸುವುದು","text":["ವಿಶಾಲ: \"ಗ್ರಂಥಾಲಯ ಬಳಕೆ ಕಡಿಮೆ.\" ಕೇಂದ್ರೀಕೃತ: \"ಚಿಕ್ಕಮಗಳೂರು ಜಿಲ್ಲೆಯ ಸರ್ಕಾರಿ ಹಿರಿಯ ಪ್ರಾಥಮಿಕ ಶಾಲೆಗಳ 6–8ನೇ ತರಗತಿ ಮಕ್ಕಳು ಎಷ್ಟು ಬಾರಿ ಗ್ರಂಥಾಲಯ ಪುಸ್ತಕ ಪಡೆಯುತ್ತಾರೆ, ಮತ್ತು ಯಾವ ಶಾಲಾ ಅಂಶಗಳು ಇದಕ್ಕೆ ಸಂಬಂಧಿಸಿವೆ?\""]}],"activity":{"title":"ನಿಮ್ಮ ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆ ರಚಿಸಿ","prompt":"ಪ್ರಶ್ನೆ ರಚನಾ ಸಾಧನ ಬಳಸಿ ನಿಮ್ಮ ಜಿಲ್ಲೆಯ ಒಂದು ಕಾಳಜಿಯನ್ನು ಕೇಂದ್ರೀಕೃತ ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆ ಮತ್ತು ಊಹೆಯಾಗಿ ಪರಿವರ್ತಿಸಿ."},"quiz":[{"q":"ಯಾವುದು ಹೆಚ್ಚು ಸಂಶೋಧಿಸಬಹುದಾದ ಪ್ರಶ್ನೆ?","options":["ಕರ್ನಾಟಕದಲ್ಲಿ ಶಿಕ್ಷಣ ಸುಧಾರಿಸುತ್ತಿದೆಯೇ?","ರಾಯಚೂರು ಜಿಲ್ಲೆಯ ಎರಡು ಬ್ಲಾಕ್‌ಗಳಲ್ಲಿ 7ನೇ ತರಗತಿ ಗಣಿತ ಅಂಕಗಳ ಮೇಲೆ LBA ಪರಿಣಾಮವೇನು?","ಶಿಕ್ಷಕರು ಏಕೆ ಪ್ರೇರಿತರಾಗಿಲ್ಲ?","ಇಂಗ್ಲಿಷ್ ಕಲಿಸಬೇಕೇ?"],"why":"ಇದು ಜನಸಂಖ್ಯೆ, ಚರಾಂಶ, ಸ್ಥಳ ಮತ್ತು ಹೋಲಿಕೆಯನ್ನು ಹೆಸರಿಸುತ್ತದೆ."},{"q":"\"ವಾರಕ್ಕೊಮ್ಮೆ ಗ್ರಂಥಾಲಯ ಅವಧಿ ಇರುವಲ್ಲಿ ಓದಿನ ನಿರರ್ಗಳತೆ ಹೆಚ್ಚಿರುತ್ತದೆ\" — ಇದು ಒಂದು…","options":["ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆ","ಊಹೆ","ಉದ್ದೇಶ","ಮಿತಿ"],"why":"ಇದು ಪರೀಕ್ಷಿಸಬಹುದಾದ ಸಂಬಂಧವನ್ನು ಮುನ್ನುಡಿಯುತ್ತದೆ."},{"q":"\"ಓದಿನ ನಿರರ್ಗಳತೆ\"ಯ ಕಾರ್ಯಾತ್ಮಕ ವ್ಯಾಖ್ಯಾನ…","options":["ಓದಿನ ಮೇಲಿನ ಪ್ರೀತಿ","ಶ್ರೇಣೀಕೃತ ಗದ್ಯಭಾಗದಲ್ಲಿ ನಿಮಿಷಕ್ಕೆ ಸರಿಯಾಗಿ ಓದಿದ ಪದಗಳು","ಶಿಕ್ಷಕರ ಅನಿಸಿಕೆ","ಗ್ರಂಥಾಲಯದ ಪುಸ್ತಕಗಳ ಸಂಖ್ಯೆ"],"why":"ಚರಾಂಶವನ್ನು ನಿಖರವಾಗಿ ಹೇಗೆ ಅಳೆಯಲಾಗುತ್ತದೆ ಎಂದು ತಿಳಿಸುತ್ತದೆ."},{"q":"ಸಾಹಿತ್ಯ ಅವಲೋಕನದಲ್ಲಿ \"ಅಂತರ\" ಎಂದರೆ…","options":["ಕಾಣೆಯಾದ ಪುಟಗಳು","ನಿಮ್ಮ ಸಂದರ್ಭದಲ್ಲಿ ಇನ್ನೂ ತಿಳಿಯದ ಅಥವಾ ಅಧ್ಯಯನವಾಗದ ವಿಷಯ","ಸಮೀಕ್ಷೆಗಳ ನಡುವಿನ ಸಮಯ","ಬಾಲಕ-ಬಾಲಕಿಯರ ವ್ಯತ್ಯಾಸ"],"why":"ಅಂತರವೇ ಹೊಸ ಅಧ್ಯಯನವನ್ನು ಸಮರ್ಥಿಸುತ್ತದೆ."}]},"m4":{"objectives":["ಸಮೀಕ್ಷೆ, ಸಹಸಂಬಂಧ, ಕಾರಣ-ತುಲನಾತ್ಮಕ ಮತ್ತು ಪ್ರಾಯೋಗಿಕ ವಿನ್ಯಾಸಗಳಲ್ಲಿ ಆಯ್ಕೆ ಮಾಡುವುದು.","ಮಾದರಿಯನ್ನು ಆಯ್ಕೆ ಮಾಡಿ ಅದರ ಗಾತ್ರವನ್ನು ಲೆಕ್ಕಹಾಕುವುದು.","ವಿಶ್ವಸನೀಯ ಮತ್ತು ಸಿಂಧುವಾದ ಪರೀಕ್ಷೆಗಳು ಹಾಗೂ ಪ್ರಶ್ನಾವಳಿಗಳನ್ನು ರಚಿಸುವುದು.","ಪ್ರಶ್ನೆಗೆ ಸರಿಯಾದ ಸಾಂಖ್ಯಿಕ ಪರೀಕ್ಷೆಯನ್ನು ಆರಿಸುವುದು."],"lessons":[{"title":"ವಿನ್ಯಾಸಗಳು","body":["ಸಮೀಕ್ಷೆ: ಜನಸಂಖ್ಯೆಯನ್ನು ವರ್ಣಿಸುತ್ತದೆ (ಉದಾ: ಪ್ರೌಢಶಾಲೆಗಳಲ್ಲಿ ವಿಜ್ಞಾನ ಪ್ರಯೋಗಾಲಯಗಳ ಲಭ್ಯತೆ). ಸಹಸಂಬಂಧ: ಸಂಬಂಧವನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ (ಶಿಕ್ಷಕರ ಹಾಜರಾತಿ ಮತ್ತು ವಿದ್ಯಾರ್ಥಿ ಅಂಕಗಳು). ಕಾರಣ-ತುಲನಾತ್ಮಕ: ಈಗಿರುವ ಗುಂಪುಗಳನ್ನು ಹೋಲಿಸುತ್ತದೆ (KPS ಮತ್ತು KPS ಅಲ್ಲದ ಶಾಲೆಗಳು). ಪ್ರಾಯೋಗಿಕ ಮತ್ತು ಅರೆ-ಪ್ರಾಯೋಗಿಕ: ಸಂಶೋಧಕರು ಮಧ್ಯಪ್ರವೇಶವನ್ನು ಪರಿಚಯಿಸಿ, ನಿಯಂತ್ರಣ ಅಥವಾ ಹೋಲಿಕೆ ಗುಂಪಿನೊಂದಿಗೆ, ಸಾಧ್ಯವಾದರೆ ಪೂರ್ವ ಮತ್ತು ಉತ್ತರ ಪರೀಕ್ಷೆಗಳೊಂದಿಗೆ ಹೋಲಿಸುತ್ತಾರೆ.","ಸಹಸಂಬಂಧ ಕಾರಣವಲ್ಲ. ಗ್ರಂಥಾಲಯವಿರುವ ಶಾಲೆಗಳ ಸಮುದಾಯಗಳೂ ಹೆಚ್ಚು ಸಂಪನ್ಮೂಲ ಹೊಂದಿರಬಹುದು."]},{"title":"ಮಾದರಿ ಆಯ್ಕೆ","body":["ಸಂಭವನೀಯತಾ ಮಾದರಿಗಳು (ಸರಳ ಯಾದೃಚ್ಛಿಕ, ಸ್ತರೀಕೃತ, ಗುಚ್ಛ, ಬಹುಹಂತ) ಸಾಮಾನ್ಯೀಕರಣಕ್ಕೆ ಅವಕಾಶ ನೀಡುತ್ತವೆ. ಉಪಗುಂಪುಗಳು ಮುಖ್ಯವಾದಾಗ ಸ್ತರೀಕರಿಸಿ — ಉದಾ: ಪ್ರದೇಶ (ಕಲ್ಯಾಣ ಕರ್ನಾಟಕ ಮತ್ತು ಇತರೆ), ಬೋಧನಾ ಮಾಧ್ಯಮ ಅಥವಾ ಗ್ರಾಮೀಣ/ನಗರ. ಗುಚ್ಛ ಮಾದರಿ (ಕ್ಲಸ್ಟರ್‌ಗಳನ್ನು ಆರಿಸಿ ನಂತರ ಅವುಗಳೊಳಗಿನ ಶಾಲೆಗಳು) ಸಿಆರ್‌ಸಿ ಆಧಾರಿತ ಕ್ಷೇತ್ರಕಾರ್ಯಕ್ಕೆ ಸೂಕ್ತ.","ಮಾದರಿ ಗಾತ್ರ ವಿಶ್ವಾಸ ಮಟ್ಟ, ನೀವು ಒಪ್ಪಬಹುದಾದ ದೋಷದ ಅಂಚು ಮತ್ತು ಜನಸಂಖ್ಯೆಯ ವ್ಯತ್ಯಾಸವನ್ನು ಅವಲಂಬಿಸಿದೆ. ಮಾದರಿ ಗಾತ್ರ ಗಣಕವನ್ನು ಬಳಸಿ."]},{"title":"ಸಾಧನಗಳು ಮತ್ತು ವಿಶ್ಲೇಷಣೆ","body":["ವಿಶ್ವಸನೀಯತೆ ಎಂದರೆ ಸ್ಥಿರತೆ (ಪರೀಕ್ಷೆ–ಮರುಪರೀಕ್ಷೆ; ಬಹುತೇಕ ಮಾಪಕಗಳಿಗೆ ಕ್ರಾನ್‌ಬ್ಯಾಕ್ ಆಲ್ಫಾ ≥ 0.70). ಸಿಂಧುತ್ವ ಎಂದರೆ ಸಾಧನವು ಹೇಳಿಕೊಂಡದ್ದನ್ನೇ ಅಳೆಯುತ್ತದೆಯೇ (ತಜ್ಞರ ಪರಿಶೀಲನೆಯ ಮೂಲಕ ವಿಷಯ ಸಿಂಧುತ್ವ; ಫಲಿತಾಂಶಗಳ ಮಾದರಿಯ ಮೂಲಕ ರಚನಾ ಸಿಂಧುತ್ವ). ಯಾವಾಗಲೂ ಪ್ರಾಯೋಗಿಕ ಪರೀಕ್ಷೆ (pilot) ಮಾಡಿ.","ಪರೀಕ್ಷೆ ಆಯ್ಕೆ: ಎರಡು ಗುಂಪುಗಳ ಸರಾಸರಿ ಹೋಲಿಕೆ → t-ಪರೀಕ್ಷೆ; ಅದೇ ಗುಂಪು ಮೊದಲು ಮತ್ತು ನಂತರ → ಜೋಡಿ t-ಪರೀಕ್ಷೆ; ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಗುಂಪುಗಳು → ANOVA; ಎರಡು ವರ್ಗೀಯ ಚರಾಂಶಗಳು → ಕೈ-ವರ್ಗ; ಎರಡು ಅಂಕಗಳ ನಡುವಿನ ಸಂಬಂಧ → ಸಹಸಂಬಂಧ."]}],"karnataka":[{"title":"ಅರೆ-ಪ್ರಯೋಗ: ಯಾದಗಿರಿಯಲ್ಲಿ ಸೇತುಬಂಧ","text":["ಉದಾಹರಣಾ ವಿನ್ಯಾಸ: ಯಾದಗಿರಿ ಜಿಲ್ಲೆಯ 20 ಸರ್ಕಾರಿ ಕಿರಿಯ ಪ್ರಾಥಮಿಕ ಶಾಲೆಗಳು ದಿನಕ್ಕೆ 20 ನಿಮಿಷಗಳ ಹೆಚ್ಚುವರಿ ಓದಿನ ಅವಧಿಯೊಂದಿಗೆ ಸೇತುಬಂಧ ನಡೆಸುತ್ತವೆ (ಚಿಕಿತ್ಸಾ ಗುಂಪು); 20 ಹೊಂದಾಣಿಕೆಯ ಶಾಲೆಗಳು ಸೇತುಬಂಧ ಮಾತ್ರ ನಡೆಸುತ್ತವೆ (ಹೋಲಿಕೆ ಗುಂಪು). 4ನೇ ತರಗತಿ ಮಕ್ಕಳು ಜೂನ್ ಮತ್ತು ಸೆಪ್ಟೆಂಬರ್‌ನಲ್ಲಿ ಕನ್ನಡ ಓದಿನ ಪರೀಕ್ಷೆ ತೆಗೆದುಕೊಳ್ಳುತ್ತಾರೆ. ಗಳಿಕೆ ಅಂಕಗಳನ್ನು ಸ್ವತಂತ್ರ ಮಾದರಿ t-ಪರೀಕ್ಷೆಯಿಂದ ವಿಶ್ಲೇಷಿಸಿ, ಪರಿಣಾಮ ಗಾತ್ರವನ್ನು (Cohen's d) ವರದಿ ಮಾಡಿ."]},{"title":"ಪ್ರೌಢಶಾಲೆಗಳ ಸ್ತರೀಕೃತ ಮಾದರಿ","text":["180 ಸರ್ಕಾರಿ ಪ್ರೌಢಶಾಲೆಗಳಿರುವ ಜಿಲ್ಲೆಯಲ್ಲಿ ವಿಜ್ಞಾನ ಪ್ರಯೋಗಾಲಯ ಬಳಕೆಯನ್ನು ಸಮೀಕ್ಷಿಸಲು, ಕನ್ನಡ, ಇಂಗ್ಲಿಷ್ ಮತ್ತು ಉರ್ದು ಮಾಧ್ಯಮಗಳ ಆಧಾರದಲ್ಲಿ ಸ್ತರೀಕರಿಸಿ, ಪ್ರತಿ ಸ್ತರದ ಗಾತ್ರಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಯಾದೃಚ್ಛಿಕವಾಗಿ ಆಯ್ಕೆ ಮಾಡಿ."]}],"activity":{"title":"ಮಾದರಿ ಮತ್ತು ಪರೀಕ್ಷೆಯನ್ನು ಯೋಜಿಸಿ","prompt":"ನಿಮ್ಮ ಆಯ್ಕೆಯ ಜಿಲ್ಲಾ ಸಮೀಕ್ಷೆಗೆ ಮಾದರಿ ಗಾತ್ರವನ್ನು ಲೆಕ್ಕಹಾಕಿ, ನಂತರ ಉದಾಹರಣಾ ಪೂರ್ವ/ಉತ್ತರ ದತ್ತಾಂಶವನ್ನು ಸಾಂಖ್ಯಿಕ ಸಾಧನದಲ್ಲಿ ನಮೂದಿಸಿ ಫಲಿತಾಂಶವನ್ನು ಎರಡು ವಾಕ್ಯಗಳಲ್ಲಿ ವ್ಯಾಖ್ಯಾನಿಸಿ."},"quiz":[{"q":"ಅದೇ ವಿದ್ಯಾರ್ಥಿಗಳ SSLC ಗಣಿತ ಅಂಕಗಳನ್ನು ಪೂರ್ವ ಮತ್ತು ಉತ್ತರ ಪರೀಕ್ಷೆಗಳಲ್ಲಿ ಹೋಲಿಸುತ್ತೀರಿ. ಬಳಸಬೇಕಾದದ್ದು…","options":["ಕೈ-ವರ್ಗ","ಜೋಡಿ t-ಪರೀಕ್ಷೆ","ಸ್ವತಂತ್ರ t-ಪರೀಕ್ಷೆ","ANOVA"],"why":"ಅದೇ ವಿದ್ಯಾರ್ಥಿಗಳನ್ನು ಎರಡು ಬಾರಿ ಅಳೆಯಲಾಗಿದೆ."},{"q":"ಕನ್ನಡ, ಇಂಗ್ಲಿಷ್ ಮತ್ತು ಉರ್ದು ಮಾಧ್ಯಮ ಶಾಲೆಗಳ ಸರಾಸರಿ ಅಂಕಗಳ ಹೋಲಿಕೆಗೆ ಬೇಕಾದದ್ದು…","options":["ಜೋಡಿ t-ಪರೀಕ್ಷೆ","ಏಕಮುಖ ANOVA","ಸಹಸಂಬಂಧ","ವಿಷಯ ವಿಶ್ಲೇಷಣೆ"],"why":"ಮೂರು ಸ್ವತಂತ್ರ ಗುಂಪುಗಳು."},{"q":"ಕ್ರಾನ್‌ಬ್ಯಾಕ್ ಆಲ್ಫಾ ತಿಳಿಸುವುದು…","options":["ಸಿಂಧುತ್ವ","ಆಂತರಿಕ ಸ್ಥಿರತೆಯ ವಿಶ್ವಸನೀಯತೆ","ಮಾದರಿ ಗಾತ್ರ","ಪರಿಣಾಮ ಗಾತ್ರ"],"why":"ಆಲ್ಫಾ ಆಂತರಿಕ ಸ್ಥಿರತೆಯನ್ನು ಅಂದಾಜಿಸುತ್ತದೆ."},{"q":"ಗ್ರಂಥಾಲಯ ಅವಧಿ ಮತ್ತು ಓದಿನ ಅಂಕಗಳ ನಡುವಿನ ಬಲವಾದ ಸಹಸಂಬಂಧ ಸಾಬೀತುಪಡಿಸುವುದು…","options":["ಗ್ರಂಥಾಲಯಗಳೇ ಉತ್ತಮ ಓದಿಗೆ ಕಾರಣ","ಬೇರೆ ವಿವರಣೆಗಳೂ ಇರಬಹುದಾದ ಒಂದು ಸಂಬಂಧ","ಏನನ್ನೂ ಇಲ್ಲ","ಓದು ಗ್ರಂಥಾಲಯಗಳಿಗೆ ಕಾರಣ"],"why":"ಸಹಸಂಬಂಧ ಮಾತ್ರ ಕಾರಣವನ್ನು ಸ್ಥಾಪಿಸುವುದಿಲ್ಲ."}]},"m5":{"objectives":["ಪ್ರಕರಣ ಅಧ್ಯಯನ, ಜನಾಂಗ ವರ್ಣನೆ, ಅನುಭವ ವಿಜ್ಞಾನ, ನಿರೂಪಣೆ ಮತ್ತು ಆಧಾರಿತ ಸಿದ್ಧಾಂತಗಳಲ್ಲಿ ಆಯ್ಕೆ ಮಾಡುವುದು.","ಅರೆ-ರಚಿತ ಸಂದರ್ಶನಗಳು ಮತ್ತು ಕೇಂದ್ರೀಕೃತ ಗುಂಪು ಚರ್ಚೆಗಳನ್ನು ನಡೆಸುವುದು.","ಪ್ರತಿಲಿಪಿಗಳಿಗೆ ಸಂಕೇತ ನೀಡಿ ವಿಷಯವಸ್ತುಗಳನ್ನು ರೂಪಿಸುವುದು.","ವಿಶ್ವಾಸಾರ್ಹತೆಯನ್ನು ಸ್ಥಾಪಿಸುವುದು."],"lessons":[{"title":"ಮಾರ್ಗಗಳು","body":["ಪ್ರಕರಣ ಅಧ್ಯಯನ: ಸೀಮಿತ ಪ್ರಕರಣದ ಆಳವಾದ ಅಧ್ಯಯನ (ಒಂದು KPS ಆವರಣ). ಜನಾಂಗ ವರ್ಣನೆ: ಒಂದು ಸಂಸ್ಕೃತಿಯ ದೀರ್ಘಕಾಲದ ವೀಕ್ಷಣೆ (ಆಶ್ರಮ ಶಾಲೆಯ ಜೀವನ). ಅನುಭವ ವಿಜ್ಞಾನ (phenomenology): ಹಂಚಿಕೊಂಡ ಜೀವನಾನುಭವ (ಏಕೋಪಾಧ್ಯಾಯ ಶಾಲೆಗಳ ಮೊದಲ ವರ್ಷದ ಶಿಕ್ಷಕರು). ನಿರೂಪಣೆ: ಜೀವನ ಕಥೆಗಳು (ಮಹಿಳಾ ಮುಖ್ಯ ಶಿಕ್ಷಕರು). ಆಧಾರಿತ ಸಿದ್ಧಾಂತ (grounded theory): ದತ್ತಾಂಶದಿಂದ ಸಿದ್ಧಾಂತ ಕಟ್ಟುವುದು."]},{"title":"ದತ್ತಾಂಶ ಸಂಗ್ರಹ","body":["ಅರೆ-ರಚಿತ ಸಂದರ್ಶನಗಳು ಮುಕ್ತ ಪ್ರಶ್ನೆಗಳು ಮತ್ತು ಉಪಪ್ರಶ್ನೆಗಳಿರುವ ಮಾರ್ಗದರ್ಶಿಯನ್ನು ಬಳಸುತ್ತವೆ. 6–8 ಜನರ ಕೇಂದ್ರೀಕೃತ ಗುಂಪುಗಳು ಎಸ್‌ಡಿಎಂಸಿ ಸದಸ್ಯರು ಅಥವಾ ಪೋಷಕರಿಗೆ ಸೂಕ್ತ. ವೀಕ್ಷಣೆಯಲ್ಲಿ ವರ್ಣನೆ ಮತ್ತು ವ್ಯಾಖ್ಯಾನವನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿಡುವ ಕ್ಷೇತ್ರ ಟಿಪ್ಪಣಿಗಳನ್ನು ಬರೆಯಿರಿ. ಒಪ್ಪಿಗೆಯೊಂದಿಗೆ ಮಾತ್ರ ಧ್ವನಿಮುದ್ರಿಸಿ; ಮೂಲ ಭಾಷೆಯಲ್ಲಿ ಪ್ರತಿಲಿಪಿ ಮಾಡಿ ಎಚ್ಚರಿಕೆಯಿಂದ ಅನುವಾದಿಸಿ."]},{"title":"ವಿಶ್ಲೇಷಣೆ ಮತ್ತು ವಿಶ್ವಾಸಾರ್ಹತೆ","body":["ವಿಷಯವಸ್ತು ವಿಶ್ಲೇಷಣೆ: ಪರಿಚಯ ಮಾಡಿಕೊಳ್ಳಿ → ಆರಂಭಿಕ ಸಂಕೇತಗಳನ್ನು ರಚಿಸಿ → ವಿಷಯವಸ್ತುಗಳನ್ನು ಹುಡುಕಿ → ಪರಿಶೀಲಿಸಿ → ವ್ಯಾಖ್ಯಾನಿಸಿ ಹೆಸರಿಸಿ → ಉಲ್ಲೇಖಗಳೊಂದಿಗೆ ಬರೆಯಿರಿ. ವಿಶ್ವಾಸಾರ್ಹತೆ ನಂಬಲರ್ಹತೆ (ಸದಸ್ಯ ಪರಿಶೀಲನೆ, ತ್ರಿಕೋನೀಕರಣ), ವರ್ಗಾವಣೀಯತೆ (ಸಮೃದ್ಧ ವರ್ಣನೆ), ಅವಲಂಬನೀಯತೆ (ಲೆಕ್ಕಪರಿಶೋಧನಾ ಜಾಡು) ಮತ್ತು ದೃಢೀಕರಣೀಯತೆ (ಆತ್ಮಾವಲೋಕನ ಟಿಪ್ಪಣಿಗಳು) ಮೇಲೆ ನಿಂತಿದೆ."]}],"karnataka":[{"title":"ಪ್ರಕರಣ ಅಧ್ಯಯನ: ಉತ್ತರ ಕನ್ನಡದ ಏಕೋಪಾಧ್ಯಾಯ ಶಾಲೆ","text":["ಗುಡ್ಡಗಾಡು ಪ್ರದೇಶದ ಶಾಲೆಯಲ್ಲಿ ಒಬ್ಬ ಶಿಕ್ಷಕರು ಐದು ತರಗತಿಗಳನ್ನು ಹೇಗೆ ನಿರ್ವಹಿಸುತ್ತಾರೆ? ಒಂದು ವಾರ ಪೂರ್ತಿ ವೀಕ್ಷಿಸಿ, ಶಿಕ್ಷಕರು, ಎಸ್‌ಡಿಎಂಸಿ ಅಧ್ಯಕ್ಷರು ಮತ್ತು ಮೂವರು ಪೋಷಕರನ್ನು ಸಂದರ್ಶಿಸಿ, ಪಾಠ ಯೋಜನೆಗಳನ್ನು ಸಂಗ್ರಹಿಸಿ. ಸಮಯ ಹಂಚಿಕೆ, ಸಹಪಾಠಿ ಬೋಧನೆ ಮತ್ತು 3ನೇ ತರಗತಿಯ ಆಚೆಗೂ ನಲಿ-ಕಲಿ ಸಾಮಗ್ರಿಗಳ ಬಳಕೆಯಂತಹ ವಿಷಯವಸ್ತುಗಳನ್ನು ನಿರೀಕ್ಷಿಸಿ."]},{"title":"ದ್ವಿಭಾಷಾ ವಿಭಾಗಗಳ ಬಗ್ಗೆ ಸಂದರ್ಶನಗಳು","text":["ಬೋಧನಾ ಮಾಧ್ಯಮ ಮನೆಮಾತಿಗಿಂತ ಭಿನ್ನವಾದಾಗ ಶೇ. 60ಕ್ಕೂ ಹೆಚ್ಚು ಬುಡಕಟ್ಟು ವಿದ್ಯಾರ್ಥಿಗಳು ಕಷ್ಟಪಟ್ಟರು ಎಂದು ರಾಜ್ಯದ ಟಿಪ್ಪಣಿಗಳು ದಾಖಲಿಸುತ್ತವೆ. ಚಾಮರಾಜನಗರದ ಡಯಟ್ ದ್ವಿಭಾಷಾ KPS ವಿಭಾಗಗಳ ಬಗ್ಗೆ ಸೋಲಿಗ ಪೋಷಕರು ಮತ್ತು ಶಿಕ್ಷಕರನ್ನು ಸಂದರ್ಶಿಸಿ ಮಕ್ಕಳಿಗೆ ನಿಜವಾಗಿ ಯಾವ ಸೇತು ಬೆಂಬಲ ಬೇಕು ಎಂದು ತಿಳಿಯಬಹುದು."]}],"activity":{"title":"ಸಂದರ್ಶನ ಭಾಗಕ್ಕೆ ಸಂಕೇತ ನೀಡಿ","prompt":"ಸಂಕೇತೀಕರಣ ಸಾಧನದಲ್ಲಿನ ಶಿಕ್ಷಕರ ಸಂದರ್ಶನ ಭಾಗಗಳನ್ನು ಓದಿ, ಸಂಕೇತಗಳನ್ನು ನೀಡಿ, ಅವುಗಳನ್ನು ಎರಡು ಅಥವಾ ಮೂರು ವಿಷಯವಸ್ತುಗಳಾಗಿ ಗುಂಪು ಮಾಡಿ."},"quiz":[{"q":"ಒಂದು KPS ಆವರಣವನ್ನು ಒಂದು ಅವಧಿಯಲ್ಲಿ ಆಳವಾಗಿ ಅಧ್ಯಯನ ಮಾಡುವುದು…","options":["ಸಮೀಕ್ಷೆ","ಪ್ರಕರಣ ಅಧ್ಯಯನ","ಪ್ರಯೋಗ","ಮೆಟಾ-ವಿಶ್ಲೇಷಣೆ"],"why":"ಸೀಮಿತ ಪ್ರಕರಣದ ಆಳವಾದ ಅಧ್ಯಯನ."},{"q":"ಸದಸ್ಯ ಪರಿಶೀಲನೆ (member checking) ಎಂದರೆ…","options":["ಹಾಜರಾತಿ ಪರಿಶೀಲನೆ","ನಿಖರತೆ ದೃಢಪಡಿಸಲು ಫಲಿತಾಂಶಗಳನ್ನು ಭಾಗವಹಿಸಿದವರಿಗೆ ಮರಳಿಸುವುದು","ಸಂಕೇತಗಳನ್ನು ಎಣಿಸುವುದು","ಯಾದೃಚ್ಛಿಕ ಮಾದರಿ"],"why":"ಭಾಗವಹಿಸಿದವರು ವ್ಯಾಖ್ಯಾನಗಳನ್ನು ದೃಢಪಡಿಸುತ್ತಾರೆ."},{"q":"ಕೇಂದ್ರೀಕೃತ ಗುಂಪಿನ ಆದರ್ಶ ಗಾತ್ರ ಸುಮಾರು…","options":["2","6–8","25","50"],"why":"ವೈವಿಧ್ಯಕ್ಕೆ ಸಾಕಷ್ಟು ದೊಡ್ಡದು, ಎಲ್ಲರೂ ಮಾತನಾಡುವಷ್ಟು ಚಿಕ್ಕದು."},{"q":"ಲೆಕ್ಕಪರಿಶೋಧನಾ ಜಾಡು (audit trail) ಬೆಂಬಲಿಸುವುದು…","options":["ಅವಲಂಬನೀಯತೆ","ಸಾಂಖ್ಯಿಕ ಶಕ್ತಿ","ಯಾದೃಚ್ಛಿಕ ಆಯ್ಕೆ","ಎಲ್ಲ ರಾಜ್ಯಗಳಿಗೆ ಸಾಮಾನ್ಯೀಕರಣ"],"why":"ನಿಮ್ಮ ನಿರ್ಧಾರಗಳನ್ನು ಇತರರು ಅನುಸರಿಸಲು ಸಾಧ್ಯವಾಗುತ್ತದೆ."}]},"m6":{"objectives":["ಸಮಕೇಂದ್ರಿತ, ವಿವರಣಾತ್ಮಕ ಅನುಕ್ರಮ ಮತ್ತು ಅನ್ವೇಷಣಾತ್ಮಕ ಅನುಕ್ರಮ ವಿನ್ಯಾಸಗಳನ್ನು ವಿವರಿಸುವುದು.","ಪರಿಮಾಣಾತ್ಮಕ ಮತ್ತು ಗುಣಾತ್ಮಕ ಎಳೆಗಳು ಸೇರುವ ಹಂತವನ್ನು ಯೋಜಿಸುವುದು.","ಫಲಿತಾಂಶಗಳನ್ನು ಏಕೀಕರಿಸುವ ಜಂಟಿ ಪ್ರದರ್ಶನ ಕೋಷ್ಟಕ ರಚಿಸುವುದು."],"lessons":[{"title":"ಮೂರು ಮುಖ್ಯ ವಿನ್ಯಾಸಗಳು","body":["ಸಮಕೇಂದ್ರಿತ: ಎರಡೂ ಎಳೆಗಳನ್ನು ಒಂದೇ ಸಮಯದಲ್ಲಿ ಸಂಗ್ರಹಿಸಿ ಹೋಲಿಸಿ. ವಿವರಣಾತ್ಮಕ ಅನುಕ್ರಮ: ಮೊದಲು ಪರಿಮಾಣಾತ್ಮಕ, ನಂತರ ಅನಿರೀಕ್ಷಿತ ಫಲಿತಾಂಶಗಳನ್ನು ವಿವರಿಸಲು ಗುಣಾತ್ಮಕ. ಅನ್ವೇಷಣಾತ್ಮಕ ಅನುಕ್ರಮ: ಸಾಧನ ಅಥವಾ ಊಹೆಗಳನ್ನು ರೂಪಿಸಲು ಮೊದಲು ಗುಣಾತ್ಮಕ, ನಂತರ ಪರೀಕ್ಷಿಸಲು ಪರಿಮಾಣಾತ್ಮಕ."]},{"title":"ಏಕೀಕರಣ","body":["ಮಿಶ್ರಣ ಎಲ್ಲಾದರೂ ನಡೆಯಲೇಬೇಕು — ಮಾದರಿ ಆಯ್ಕೆಯಲ್ಲಿ (ಸಮೀಕ್ಷಾ ಫಲಿತಾಂಶಗಳಿಂದ ಸಂದರ್ಶಿತರನ್ನು ಆರಿಸುವುದು), ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ (ಅಂಕಿಗಳು ಮತ್ತು ವಿಷಯವಸ್ತುಗಳನ್ನು ಅಕ್ಕಪಕ್ಕ ಇಡುವ ಜಂಟಿ ಪ್ರದರ್ಶನ ಕೋಷ್ಟಕ) ಅಥವಾ ವ್ಯಾಖ್ಯಾನದಲ್ಲಿ. ಎರಡು ಪ್ರತ್ಯೇಕ ವರದಿಗಳನ್ನು ಒಟ್ಟಿಗೆ ಹೊಲಿದರೆ ಅದು ಮಿಶ್ರ ವಿಧಾನವಲ್ಲ."]}],"karnataka":[{"title":"ವಿವರಣಾತ್ಮಕ ಅನುಕ್ರಮ: 6ನೇ ತರಗತಿಯ ಕುಸಿತ","text":["ಹಂತ 1: ಗಣಿತ ಅಂಕಗಳು ತೀವ್ರವಾಗಿ ಕುಸಿಯುವ ಶಾಲೆಗಳನ್ನು ಕಂಡುಹಿಡಿಯಲು ಜಿಲ್ಲೆಯ 5 ಮತ್ತು 6ನೇ ತರಗತಿಗಳ LBA ಅಂಕಗಳನ್ನು ವಿಶ್ಲೇಷಿಸಿ. ಹಂತ 2: ಕಾರಣ ತಿಳಿಯಲು ತೀವ್ರ ಕುಸಿತದ ನಾಲ್ಕು ಮತ್ತು ಕಡಿಮೆ ಕುಸಿತದ ನಾಲ್ಕು ಶಾಲೆಗಳ ಶಿಕ್ಷಕರು ಮತ್ತು ಮಕ್ಕಳನ್ನು ಸಂದರ್ಶಿಸಿ. ಜಂಟಿ ಪ್ರದರ್ಶನದಲ್ಲಿ ಏಕೀಕರಿಸಿ: \"ಅಂಕ ಮಾದರಿ | ಶಿಕ್ಷಕರ ವಿವರಣೆ | ಮಕ್ಕಳ ವಿವರಣೆ\"."]},{"title":"ಅನ್ವೇಷಣಾತ್ಮಕ ಅನುಕ್ರಮ: ಎಸ್‌ಡಿಎಂಸಿ ತೊಡಗಿಸಿಕೊಳ್ಳುವಿಕೆ ಮಾಪಕ","text":["ಬೀದರ್‌ನ ಎಸ್‌ಡಿಎಂಸಿ ಸದಸ್ಯರೊಂದಿಗಿನ ಕೇಂದ್ರೀಕೃತ ಗುಂಪುಗಳು ಸ್ಥಳೀಯವಾಗಿ \"ಸಕ್ರಿಯ ಭಾಗವಹಿಸುವಿಕೆ\" ಎಂದರೇನು ಎಂದು ಗುರುತಿಸುತ್ತವೆ; ಆ ವಿಷಯವಸ್ತುಗಳು ಪ್ರಶ್ನಾವಳಿಯ ಅಂಶಗಳಾಗಿ ಜಿಲ್ಲೆಯಾದ್ಯಂತ ಎಸ್‌ಡಿಎಂಸಿಗಳಿಗೆ ನೀಡಲ್ಪಡುತ್ತವೆ."]}],"activity":{"title":"ನಿಮ್ಮ ವಿನ್ಯಾಸ ಆರಿಸಿ","prompt":"ನಿಮ್ಮ ಯೋಜಿತ ಅಧ್ಯಯನಕ್ಕಾಗಿ ವಿನ್ಯಾಸ ಆಯ್ಕೆ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಿಸಿ ಮತ್ತು ಕನಿಷ್ಠ ಮೂರು ಸಾಲುಗಳ ಜಂಟಿ ಪ್ರದರ್ಶನ ಕೋಷ್ಟಕ ರಚಿಸಿ."},"quiz":[{"q":"ಅನಿರೀಕ್ಷಿತ ಸಮೀಕ್ಷಾ ಫಲಿತಾಂಶಗಳನ್ನು ವಿವರಿಸಲು ಸಂದರ್ಶನಗಳನ್ನು ಬಳಸಲಾಗಿದೆ. ವಿನ್ಯಾಸ…","options":["ಸಮಕೇಂದ್ರಿತ","ವಿವರಣಾತ್ಮಕ ಅನುಕ್ರಮ","ಅನ್ವೇಷಣಾತ್ಮಕ ಅನುಕ್ರಮ","ಅಂತರ್ಗತ ಪ್ರಾಯೋಗಿಕ"],"why":"ಮೊದಲು ಪರಿಮಾಣಾತ್ಮಕ, ನಂತರ ಗುಣಾತ್ಮಕ ವಿವರಿಸುತ್ತದೆ."},{"q":"ಜಂಟಿ ಪ್ರದರ್ಶನ (joint display) ಎಂದರೆ…","options":["ಒಂದು ಭಿತ್ತಿಪತ್ರ","ಪರಿಮಾಣಾತ್ಮಕ ಮತ್ತು ಗುಣಾತ್ಮಕ ಫಲಿತಾಂಶಗಳನ್ನು ಅಕ್ಕಪಕ್ಕ ಇಡುವ ಕೋಷ್ಟಕ","ಸ್ತಂಭ ನಕ್ಷೆ","ಒಪ್ಪಿಗೆ ಪತ್ರ"],"why":"ಇದು ಏಕೀಕರಣವನ್ನು ಕಣ್ಣಿಗೆ ಕಾಣುವಂತೆ ತೋರಿಸುತ್ತದೆ."},{"q":"ಕೇಂದ್ರೀಕೃತ ಗುಂಪಿನ ವಿಷಯವಸ್ತುಗಳಿಂದ ಪ್ರಶ್ನಾವಳಿ ರಚಿಸುವುದು…","options":["ಅನ್ವೇಷಣಾತ್ಮಕ ಅನುಕ್ರಮ","ವಿವರಣಾತ್ಮಕ ಅನುಕ್ರಮ","ಸಮಕೇಂದ್ರಿತ","ಮಿಶ್ರ ವಿಧಾನವಲ್ಲ"],"why":"ಮೊದಲ ಗುಣಾತ್ಮಕ ಹಂತ ಪರಿಮಾಣಾತ್ಮಕ ಸಾಧನಕ್ಕೆ ಆಧಾರ."},{"q":"ಯಾವುದು ನಿಜವಾದ ಮಿಶ್ರಣವಲ್ಲ?","options":["ಜಂಟಿ ಪ್ರದರ್ಶನ","ಸಮೀಕ್ಷಾ ಫಲಿತಾಂಶಗಳಿಂದ ಸಂದರ್ಶಿತರ ಆಯ್ಕೆ","ಒಂದೇ ಹೊದಿಕೆಯಲ್ಲಿ ಸಂಬಂಧವಿಲ್ಲದ ಎರಡು ವರದಿಗಳು","ವಿಷಯವಸ್ತುಗಳನ್ನು ಅಂಕಗಳೊಂದಿಗೆ ಹೋಲಿಸುವುದು"],"why":"ಏಕೀಕರಣ ನಡೆಯಲೇಬೇಕು."}]},"m7":{"objectives":["ತಮ್ಮದೇ ಅಭ್ಯಾಸದ ಮೇಲೆ ಯೋಜನೆ–ಕ್ರಿಯೆ–ವೀಕ್ಷಣೆ–ಚಿಂತನೆ ಚಕ್ರಗಳನ್ನು ನಡೆಸುವುದು.","ತರಗತಿ ಅಥವಾ ತರಬೇತಿ ಸಭಾಂಗಣದಲ್ಲಿ ಸರಳ, ಬಳಸಬಹುದಾದ ಪುರಾವೆ ಸಂಗ್ರಹಿಸುವುದು.","ಕ್ರಿಯಾ ಸಂಶೋಧನೆಯಲ್ಲಿ ಶಿಕ್ಷಕರು ಮತ್ತು ಸಿಆರ್‌ಪಿಗಳಿಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡುವುದು."],"lessons":[{"title":"ಚಕ್ರ","body":["ಯೋಜನೆ: ನಿಮ್ಮ ಅಭ್ಯಾಸದ ನಿರ್ದಿಷ್ಟ ಸಮಸ್ಯೆ ಮತ್ತು ಪ್ರಯತ್ನಿಸಬೇಕಾದ ಬದಲಾವಣೆಯನ್ನು ಹೆಸರಿಸಿ. ಕ್ರಿಯೆ: ನಿಗದಿತ ಅವಧಿಗೆ ಬದಲಾವಣೆಯನ್ನು ಜಾರಿಗೊಳಿಸಿ. ವೀಕ್ಷಣೆ: ಪುರಾವೆ ಸಂಗ್ರಹಿಸಿ (ಕಲಿಕಾ ಮಾದರಿಗಳು, ಕಿರು ಪರೀಕ್ಷೆಗಳು, ವೀಕ್ಷಣಾ ಟಿಪ್ಪಣಿಗಳು, ಚಿಂತನೆಗಳು). ಚಿಂತನೆ: ಏನು ಬದಲಾಯಿತು, ಯಾರಿಗೆ, ಏಕೆ? ನಂತರ ಮುಂದಿನ ಚಕ್ರವನ್ನು ಯೋಜಿಸಿ.","ಕ್ರಿಯಾ ಸಂಶೋಧನೆ ಸಣ್ಣ, ಸ್ಥಳೀಯ ಮತ್ತು ವ್ಯಾವಹಾರಿಕ. ಅದರ ಫಲಿತಾಂಶಗಳು ಮೊದಲು ನಿಮ್ಮದೇ ಪರಿಸರವನ್ನು ಸುಧಾರಿಸಲು; ಸಾಮಾನ್ಯೀಕರಣ ಅದರ ಗುರಿಯಲ್ಲ."]},{"title":"ಶಿಕ್ಷಕರು ನಿರ್ವಹಿಸಬಹುದಾದ ಪುರಾವೆ","body":["ಈಗಾಗಲೇ ಇರುವುದನ್ನು ಬಳಸಿ: ನೋಟ್‌ಪುಸ್ತಕಗಳು, LBA ದಾಖಲೆಗಳು, ಹಾಜರಾತಿ ವಹಿಗಳು. ವಾರದ 5-ಅಂಶದ ಕಿರುಪರೀಕ್ಷೆ ಅಥವಾ ನಿರ್ಗಮನ ಚೀಟಿಯಂತಹ ಒಂದು ಸರಳ ಸಾಧನ ಸೇರಿಸಿ. ದಿನಾಂಕ, ಏನು ಮಾಡಲಾಯಿತು, ಏನಾಯಿತು ಮತ್ತು ಅದರ ಅರ್ಥವೇನು ಎಂದು ಬರೆಯುವ ಚಿಂತನಾ ದಿನಚರಿ ಇಟ್ಟುಕೊಳ್ಳಿ."]}],"karnataka":[{"title":"ಡಿ.ಇಎಲ್.ಇಡಿ. ಉಪನ್ಯಾಸಕರ ಚಕ್ರ","text":["ಸಮಸ್ಯೆ: ಅಭ್ಯಾಸ ಬೋಧನೆಯ ವೇಳೆ ಪ್ರಶಿಕ್ಷಣಾರ್ಥಿಗಳು ಸ್ಮರಣೆಯ ಪ್ರಶ್ನೆಗಳನ್ನು ಮಾತ್ರ ಕೇಳುತ್ತಾರೆ. ಕ್ರಿಯೆ: ನಾಲ್ಕು ವಾರಗಳ ಕಾಲ \"ಏಕೆ\" ಮತ್ತು \"ಹಾಗಾದರೆ ಏನು\" ಪ್ರಶ್ನೆಗಳನ್ನು ಮಾದರಿಯಾಗಿ ತೋರಿಸಿ, ಪ್ರಶ್ನಾ-ಪ್ರಕಾರದ ಪರಿಶೀಲನಾ ಪಟ್ಟಿಯೊಂದಿಗೆ ಸಹಪಾಠಿ ವೀಕ್ಷಣೆ ಬಳಸಿ. ಪುರಾವೆ: ಮೊದಲು ಮತ್ತು ನಂತರ ಪ್ರತಿ ಪಾಠದಲ್ಲಿನ ಉನ್ನತ ಹಂತದ ಪ್ರಶ್ನೆಗಳ ಎಣಿಕೆ. ಚಿಂತನೆ: ತಮ್ಮ ಪಾಠದ ವಿಡಿಯೋ ನೋಡಿದ ಪ್ರಶಿಕ್ಷಣಾರ್ಥಿಗಳಲ್ಲಿ ಲಾಭ ಹೆಚ್ಚು — ಮುಂದಿನ ಚಕ್ರದಲ್ಲಿ ವಿಡಿಯೋ ಪರಿಶೀಲನೆ ಸೇರುತ್ತದೆ."]},{"title":"ಕಲಿಕಾ ಚೇತರಿಕೆ ತರಗತಿಯಲ್ಲಿ ಒಬ್ಬ ಶಿಕ್ಷಕಿ","text":["ಕೊಪ್ಪಳದ 5ನೇ ತರಗತಿ ಶಿಕ್ಷಕಿಯೊಬ್ಬರು ಮಕ್ಕಳು ಗಣಿತದ ಕಲಿಕಾ ಹಾಳೆ ಚಟುವಟಿಕೆಗಳನ್ನು ಬಿಟ್ಟುಬಿಡುತ್ತಿರುವುದನ್ನು ಗಮನಿಸುತ್ತಾರೆ. ಸೂಚನೆಗಳನ್ನು ಗಟ್ಟಿಯಾಗಿ ಓದಲು ಒಬ್ಬ ಉತ್ತಮ ಮತ್ತು ಒಬ್ಬ ದುರ್ಬಲ ಓದುಗರ ಜೋಡಿ ಕೆಲಸ ಪರಿಚಯಿಸುತ್ತಾರೆ. ಮೂರು ವಾರಗಳಲ್ಲಿ ಪೂರ್ಣಗೊಳಿಸುವಿಕೆ ಹೆಚ್ಚುತ್ತದೆ; ಅವರು ಇದನ್ನು ದಿನಚರಿಯಲ್ಲಿ ದಾಖಲಿಸಿ ಕ್ಲಸ್ಟರ್ ಸಭೆಯಲ್ಲಿ ಹಂಚಿಕೊಳ್ಳುತ್ತಾರೆ."]}],"activity":{"title":"ನಿಮ್ಮ ಮೊದಲ ಚಕ್ರ ಯೋಜಿಸಿ","prompt":"ಕ್ರಿಯಾ ಸಂಶೋಧನಾ ದಿನಚರಿ ಬಳಸಿ ಒಂದು ಚಕ್ರದ ಪೂರ್ಣ ಯೋಜನೆ ಬರೆಯಿರಿ ಮತ್ತು ಮೊದಲ ಚಿಂತನಾ ನಮೂದನ್ನು ಮಾಡಿ."},"quiz":[{"q":"ಕ್ರಿಯಾ ಸಂಶೋಧನಾ ಚಕ್ರದ ಸರಿಯಾದ ಕ್ರಮ…","options":["ಕ್ರಿಯೆ–ಯೋಜನೆ–ಚಿಂತನೆ–ವೀಕ್ಷಣೆ","ಯೋಜನೆ–ಕ್ರಿಯೆ–ವೀಕ್ಷಣೆ–ಚಿಂತನೆ","ವೀಕ್ಷಣೆ–ಪ್ರಕಟಣೆ–ಯೋಜನೆ–ಕ್ರಿಯೆ","ಚಿಂತನೆ–ಕ್ರಿಯೆ–ಯೋಜನೆ–ಪ್ರಕಟಣೆ"],"why":"ಯೋಜನೆ, ಕ್ರಿಯೆ, ವೀಕ್ಷಣೆ, ಚಿಂತನೆ, ನಂತರ ಪುನರಾವರ್ತನೆ."},{"q":"ಕ್ರಿಯಾ ಸಂಶೋಧನೆಯ ಮುಖ್ಯ ಗುರಿ…","options":["ಎಲ್ಲ ಶಾಲೆಗಳಿಗೆ ಸಾಮಾನ್ಯೀಕರಣ","ತಮ್ಮದೇ ಅಭ್ಯಾಸದ ಸುಧಾರಣೆ","ಪ್ರಯೋಗಾಲಯದಲ್ಲಿ ಸಿದ್ಧಾಂತ ಪರೀಕ್ಷೆ","ಶಾಲೆಗಳಿಗೆ ಶ್ರೇಣಿ ನೀಡುವುದು"],"why":"ಇದು ಸುಧಾರಣೆಗಾಗಿ ವೃತ್ತಿನಿರತರ ಅನ್ವೇಷಣೆ."},{"q":"ಶಿಕ್ಷಕರಿಗೆ ಸೂಕ್ತವಾದ ಕಡಿಮೆ ಹೊರೆಯ ಪುರಾವೆ ಮೂಲ ಯಾವುದು?","options":["ರಾಷ್ಟ್ರೀಯ ಸಮೀಕ್ಷೆ","ನಿರ್ಗಮನ ಚೀಟಿಗಳು","ಎಂಆರ್‌ಐ ಸ್ಕ್ಯಾನ್","ಜನಗಣತಿ ದತ್ತಾಂಶ"],"why":"ಸರಳ, ತ್ವರಿತ ಮತ್ತು ಅಭ್ಯಾಸಕ್ಕೆ ಹತ್ತಿರ."},{"q":"ಚಿಂತನೆಯ ನಂತರ ಸಂಶೋಧಕರು…","options":["ನಿಲ್ಲಿಸಬೇಕು","ಮುಂದಿನ ಚಕ್ರ ಯೋಜಿಸಬೇಕು","ದತ್ತಾಂಶ ಅಳಿಸಬೇಕು","ವಿಷಯ ಬದಲಿಸಬೇಕು"],"why":"ಕ್ರಿಯಾ ಸಂಶೋಧನೆ ಚಕ್ರೀಯ."}]},"m8":{"objectives":["ರಚಿತ ಮತ್ತು ಅರಚಿತ ತರಗತಿ ವೀಕ್ಷಣೆಯನ್ನು ಬಳಸುವುದು.","ಮಕ್ಕಳ ಕೆಲಸ ಮತ್ತು ಮೌಲ್ಯಮಾಪನ ದತ್ತಾಂಶವನ್ನು ವಿಶ್ಲೇಷಿಸುವುದು.","ಬಹುವರ್ಗ ಮತ್ತು ಏಕವರ್ಗ ತರಗತಿಗಳನ್ನು ನ್ಯಾಯಯುತವಾಗಿ ಅಧ್ಯಯನ ಮಾಡುವುದು."],"lessons":[{"title":"ವೀಕ್ಷಣೆ","body":["ರಚಿತ ವೀಕ್ಷಣೆ ನಿಗದಿತ ವರ್ಗಗಳಿರುವ ವೇಳಾಪಟ್ಟಿಯನ್ನು ಬಳಸುತ್ತದೆ (ಉದಾ: ಶಿಕ್ಷಕರ ಮಾತು, ಮಕ್ಕಳ ಮಾತು, ಗುಂಪು ಕೆಲಸ, ಮೌನ), ನಿಗದಿತ ಅಂತರಗಳಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ. ಅರಚಿತ ವೀಕ್ಷಣೆ ನಿರಂತರ ಟಿಪ್ಪಣಿಗಳನ್ನು ಬಳಸುತ್ತದೆ. ವೀಕ್ಷಕರ ಉಪಸ್ಥಿತಿ ವರ್ತನೆಯನ್ನು ಬದಲಿಸುತ್ತದೆ; ತರಗತಿ ನಿಮಗೆ ಒಗ್ಗಿಕೊಳ್ಳುವಂತೆ ಒಂದಕ್ಕಿಂತ ಹೆಚ್ಚು ಬಾರಿ ಭೇಟಿ ನೀಡಿ."]},{"title":"ಮಕ್ಕಳ ಕೆಲಸ ಮತ್ತು ಮೌಲ್ಯಮಾಪನ ದತ್ತಾಂಶ","body":["ನೋಟ್‌ಪುಸ್ತಕಗಳು, ಕಾರ್ಯಹಾಳೆಗಳು, ಚಿತ್ರಗಳು ಮತ್ತು ಕಲಿಕಾ ಕಡತಗಳು ಮಕ್ಕಳು ಹೇಗೆ ಯೋಚಿಸುತ್ತಾರೆ ಎಂದು ತೋರಿಸುತ್ತವೆ. LBA ಮತ್ತು ಸಮಗ್ರ ಪ್ರಗತಿ ಪತ್ರ (HPC) ನಂತಹ ರಚನಾತ್ಮಕ ದಾಖಲೆಗಳು ದೀರ್ಘಾವಧಿಯ ದತ್ತಾಂಶ ನೀಡುತ್ತವೆ. ಅಂಕಗಳನ್ನು ಮಾತ್ರವಲ್ಲ, ದೋಷ ಮಾದರಿಗಳನ್ನು ಹುಡುಕಿ."]}],"karnataka":[{"title":"ನಲಿ-ಕಲಿ ತರಗತಿಯ ವೀಕ್ಷಣೆ","text":["ನಲಿ-ಕಲಿಯಲ್ಲಿ ಮಕ್ಕಳು ಮೈಲಿಗಲ್ಲಿನ ಆಧಾರದಲ್ಲಿ ಗುಂಪುಗಳಲ್ಲಿ ಕಲಿಕಾ ಕಾರ್ಡ್‌ಗಳನ್ನು ಬಳಸಿ ಕೆಲಸ ಮಾಡುತ್ತಾರೆ ಮತ್ತು ಏಣಿಯ ಮೇಲೆ ತಮ್ಮ ಪ್ರಗತಿಯನ್ನು ಗುರುತಿಸುತ್ತಾರೆ. ವೀಕ್ಷಣಾ ವೇಳಾಪಟ್ಟಿ ಪ್ರತಿ 5 ನಿಮಿಷಕ್ಕೆ ದಾಖಲಿಸಬಹುದು: ಯಾವ ಗುಂಪುಗಳು ಶಿಕ್ಷಕ ಬೆಂಬಲಿತ, ಭಾಗಶಃ ಬೆಂಬಲಿತ ಅಥವಾ ಸ್ವಕಲಿಕೆಯಲ್ಲಿವೆ, ಮತ್ತು ಪ್ರತಿ ಮಗು ಏನು ಮಾಡುತ್ತಿದೆ. ಸ್ವಕಲಿಕಾ ಗುಂಪುಗಳು ನಿಜವಾಗಿ ತೊಡಗಿವೆಯೇ ಎಂಬುದನ್ನು ಇದು ತೋರಿಸುತ್ತದೆ."]},{"title":"7ನೇ ತರಗತಿ ಭಿನ್ನರಾಶಿಗಳಲ್ಲಿ ದೋಷ ವಿಶ್ಲೇಷಣೆ","text":["ಹಾಸನದ ಒಬ್ಬ ಡಯಟ್ ಉಪನ್ಯಾಸಕರು ಮತ್ತು ನಾಲ್ವರು ಶಿಕ್ಷಕರು 120 ಭಿನ್ನರಾಶಿ ಕಾರ್ಯಹಾಳೆಗಳನ್ನು ಸಂಗ್ರಹಿಸುತ್ತಾರೆ. ದೋಷಗಳಿಗೆ ಸಂಕೇತ ನೀಡಿದಾಗ ಬಹುತೇಕ ಮಕ್ಕಳು ಅಂಶ ಮತ್ತು ಛೇದಗಳನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಕೂಡಿಸುತ್ತಾರೆ (1/2 + 1/3 = 2/5) ಎಂದು ತಿಳಿಯುತ್ತದೆ. ಈ ಫಲಿತಾಂಶ ವಿಸ್ತೀರ್ಣ ಮಾದರಿಗಳ ಕುರಿತ ಸಿಆರ್‌ಸಿ ಕಾರ್ಯಾಗಾರಕ್ಕೆ ಆಧಾರವಾಗುತ್ತದೆ."]}],"activity":{"title":"ಸಮಯಬದ್ಧ ವೀಕ್ಷಣೆ ನಡೆಸಿ","prompt":"20 ನಿಮಿಷಗಳ ಪಾಠದ (ನೇರ ಅಥವಾ ವಿಡಿಯೋ) ವೇಳೆ ವೀಕ್ಷಣಾ ಸಾಧನ ಬಳಸಿ ತರಗತಿ ಮಾತುಕತೆಯ ಮಾದರಿಯನ್ನು ಸಂಕ್ಷೇಪಿಸಿ."},"quiz":[{"q":"ಪ್ರತಿ 30 ಸೆಕೆಂಡಿಗೆ ಒಂದು ವರ್ಗವನ್ನು ದಾಖಲಿಸುವುದು…","options":["ಅಂತರ ಆಧಾರಿತ ರಚಿತ ವೀಕ್ಷಣೆ","ನಿರೂಪಣಾ ಸಂದರ್ಶನ","ದಾಖಲೆ ವಿಶ್ಲೇಷಣೆ","ಸಮೀಕ್ಷೆ"],"why":"ನಿಗದಿತ ಅಂತರದ ವರ್ಗ ಸಂಕೇತೀಕರಣ."},{"q":"ದಾಖಲಿಸುವ ಮೊದಲು ತರಗತಿಗೆ ಹಲವು ಬಾರಿ ಏಕೆ ಭೇಟಿ ನೀಡಬೇಕು?","options":["ವೀಕ್ಷಕ ಪರಿಣಾಮ ಕಡಿಮೆ ಮಾಡಲು","ಮಾದರಿ ಗಾತ್ರ ಹೆಚ್ಚಿಸಲು","ಸಂಭಾವನೆಗಾಗಿ","ಅಗತ್ಯವಿಲ್ಲ"],"why":"ತರಗತಿ ವೀಕ್ಷಕರಿಗೆ ಒಗ್ಗಿಕೊಳ್ಳುತ್ತದೆ."},{"q":"ನೋಟ್‌ಪುಸ್ತಕದ ದೋಷಗಳ ವಿಶ್ಲೇಷಣೆ ಉಪಯುಕ್ತ ಏಕೆಂದರೆ…","options":["ಅದು ಚಿಂತನಾ ಮಾದರಿಗಳನ್ನು ತೋರಿಸುತ್ತದೆ","ಅದು ಬೋಧನೆಗೆ ಬದಲಿ","ಅದು ಶಿಕ್ಷಕರಿಗೆ ಶ್ರೇಣಿ ನೀಡುತ್ತದೆ","ಅದು ಪರೀಕ್ಷೆಗಿಂತ ವೇಗ"],"why":"ದೋಷಗಳು ತಪ್ಪುಗ್ರಹಿಕೆಗಳನ್ನು ಬಹಿರಂಗಪಡಿಸುತ್ತವೆ."},{"q":"ನಲಿ-ಕಲಿ ತರಗತಿಯಲ್ಲಿ ಸಂಶೋಧಕರು ವೀಕ್ಷಿಸಬೇಕಾದದ್ದು…","options":["ಶಿಕ್ಷಕರನ್ನು ಮಾತ್ರ","ಸ್ವಕಲಿಕಾ ಗುಂಪುಗಳೂ ಸೇರಿ ಎಲ್ಲ ಗುಂಪುಗಳನ್ನು","ಅತ್ಯಂತ ಜಾಣ ಮಗುವನ್ನು ಮಾತ್ರ","ಕಪ್ಪುಹಲಗೆಯನ್ನು ಮಾತ್ರ"],"why":"ಬಹುವರ್ಗ ಚಲನಶೀಲತೆ ಎಲ್ಲ ಗುಂಪುಗಳನ್ನು ಒಳಗೊಳ್ಳುತ್ತದೆ."}]},"m9":{"objectives":["ಪಾಲುದಾರರನ್ನು ಮತ್ತು ಅವರ ಆಸಕ್ತಿಗಳನ್ನು ನಕ್ಷೆ ಮಾಡುವುದು.","ಸಮುದಾಯಗಳನ್ನು ಕೇವಲ ಉತ್ತರದಾತರಾಗಿ ಅಲ್ಲ, ಪಾಲುದಾರರಾಗಿ ತೊಡಗಿಸುವುದು.","ಸಮುದಾಯ ಪರಿಸರದಲ್ಲಿ ನೈತಿಕತೆಯನ್ನು ನಿರ್ವಹಿಸುವುದು."],"lessons":[{"title":"ತತ್ವಗಳು","body":["ಸಮುದಾಯ ಆಧಾರಿತ ಸಹಭಾಗಿತ್ವ ಸಂಶೋಧನೆ ಸಮುದಾಯದ ಸದಸ್ಯರನ್ನು ಸಹ-ಸಂಶೋಧಕರಾಗಿ ಕಾಣುತ್ತದೆ: ಅವರು ಪ್ರಶ್ನೆಗಳನ್ನು ನಿರ್ಧರಿಸಲು, ದತ್ತಾಂಶ ಸಂಗ್ರಹಿಸಲು ಮತ್ತು ಫಲಿತಾಂಶಗಳನ್ನು ವ್ಯಾಖ್ಯಾನಿಸಲು ನೆರವಾಗುತ್ತಾರೆ. ಇದು ನಂಬಿಕೆ ಬೆಳೆಸುತ್ತದೆ ಮತ್ತು ಫಲಿತಾಂಶಗಳ ಬಳಕೆಯ ಸಾಧ್ಯತೆ ಹೆಚ್ಚಿಸುತ್ತದೆ."]},{"title":"ತೊಡಗಿಸಿಕೊಳ್ಳುವಿಕೆ ಮತ್ತು ನೈತಿಕತೆ","body":["ಪರಿಚಿತ ಸ್ಥಳಗಳಲ್ಲಿ, ಕೃಷಿ ಮತ್ತು ಕೆಲಸದ ವೇಳಾಪಟ್ಟಿಗೆ ಹೊಂದುವ ಸಮಯದಲ್ಲಿ ಭೇಟಿಯಾಗಿ. ಸ್ಥಳೀಯ ಭಾಷೆ ಬಳಸಿ. ಅಧ್ಯಯನ ಏನು ನೀಡಬಹುದು ಮತ್ತು ಏನು ನೀಡಲಾರದು ಎಂಬುದನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಿ. ಫಲಿತಾಂಶಗಳನ್ನು ಗ್ರಾಮಸಭೆ ಅಥವಾ ಎಸ್‌ಡಿಎಂಸಿ ಸಭೆಯಲ್ಲಿ ಹಂಚಿಕೊಳ್ಳಿ."]}],"karnataka":[{"title":"ಸಂಶೋಧನಾ ಪಾಲುದಾರರಾಗಿ ಎಸ್‌ಡಿಎಂಸಿಗಳು","text":["ಶಾಲಾಭಿವೃದ್ಧಿ ಮತ್ತು ಮೇಲುಸ್ತುವಾರಿ ಸಮಿತಿಗಳು (ಎಸ್‌ಡಿಎಂಸಿ) ಪೋಷಕರು ಮತ್ತು ಸ್ಥಳೀಯ ನಾಯಕರನ್ನು ಶಾಲಾ ಆಡಳಿತಕ್ಕೆ ತರುತ್ತವೆ. 8ನೇ ತರಗತಿಯಲ್ಲಿ ಬಾಲಕಿಯರ ಹಾಜರಾತಿ ಏಕೆ ಕುಸಿಯುತ್ತದೆ ಎಂಬುದನ್ನು ಅಧ್ಯಯನ ಮಾಡಲು ತುಮಕೂರಿನ ಡಯಟ್ ಎಸ್‌ಡಿಎಂಸಿ ಸದಸ್ಯರೊಂದಿಗೆ ಕೆಲಸ ಮಾಡಬಹುದು; ಎಸ್‌ಡಿಎಂಸಿ ಸದಸ್ಯರು ಒಂದು ಕಿರು ಮಾರ್ಗದರ್ಶಿ ಬಳಸಿ ಮನೆ-ಮನೆ ಮಾತುಕತೆ ನಡೆಸುತ್ತಾರೆ."]},{"title":"ಶಾಲೆಯಿಂದ ಹೊರಗುಳಿದ ಮಕ್ಕಳು","text":["ಕಲಬುರಗಿಯ ವಲಸೆ ಕಾರ್ಮಿಕರ ತಾಲ್ಲೂಕಿನಲ್ಲಿ, ಋತುಮಾನದ ಕೆಲಸಕ್ಕೆ ಹೊರಡುವ ಕುಟುಂಬಗಳನ್ನು ನಕ್ಷೆ ಮಾಡುವುದರಿಂದ ಚಿಣ್ಣರ ಅಂಗಳ ಸೇತುಬಂಧ ತರಗತಿಗಳು ಮತ್ತು ಋತುಮಾನದ ವಸತಿನಿಲಯಗಳನ್ನು ಯೋಜಿಸಲು ನೆರವಾಗುತ್ತದೆ. ಪಾಲುದಾರರು: ಅಂಗನವಾಡಿ ಕಾರ್ಯಕರ್ತೆಯರು, ಗ್ರಾಮ ಪಂಚಾಯಿತಿ, ಎಸ್‌ಡಿಎಂಸಿಗಳು ಮತ್ತು ಸಿಆರ್‌ಪಿಗಳು."]}],"activity":{"title":"ನಿಮ್ಮ ಪಾಲುದಾರರ ನಕ್ಷೆ ಮಾಡಿ","prompt":"ಪಾಲುದಾರ ನಕ್ಷೆ ಬಳಸಿ ನಿಮ್ಮ ಯೋಜಿತ ಅಧ್ಯಯನದಿಂದ ಪ್ರಭಾವಿತರಾಗುವ ಎಲ್ಲರನ್ನೂ ಪಟ್ಟಿ ಮಾಡಿ ಮತ್ತು ಪ್ರತಿಯೊಬ್ಬರನ್ನು ಹೇಗೆ ತೊಡಗಿಸಬೇಕು ಎಂದು ನಿರ್ಧರಿಸಿ."},"quiz":[{"q":"ಸಹಭಾಗಿತ್ವ ಸಂಶೋಧನೆಯಲ್ಲಿ ಸಮುದಾಯ ಸದಸ್ಯರು…","options":["ಕೇವಲ ಉತ್ತರದಾತರು","ಸಹ-ಸಂಶೋಧಕರು","ವಿಶ್ಲೇಷಣೆಯಿಂದ ಹೊರಗು","ಕೇವಲ ಸಂಭಾವನೆ ಪಡೆಯುವ ಗಣತಿದಾರರು"],"why":"ಅವರು ನಿರ್ಧಾರಗಳಲ್ಲಿ ಪಾಲು ಪಡೆಯುತ್ತಾರೆ."},{"q":"ಹಳ್ಳಿಯಲ್ಲಿ ಫಲಿತಾಂಶಗಳನ್ನು ಮರಳಿಸಲು ಸೂಕ್ತ ಸ್ಥಳ…","options":["ಕೇವಲ ನಿಯತಕಾಲಿಕ","ಎಸ್‌ಡಿಎಂಸಿ ಅಥವಾ ಗ್ರಾಮಸಭೆ","ಖಾಸಗಿ ಇಮೇಲ್","ಎಲ್ಲಿಯೂ ಇಲ್ಲ"],"why":"ಫಲಿತಾಂಶಗಳು ಸಮುದಾಯಕ್ಕೆ ಮರಳಬೇಕು."},{"q":"ಬಾಲಕಿಯರ ಹಾಜರಾತಿ ಕುರಿತ ಅಧ್ಯಯನದಲ್ಲಿ ಪಾಲುದಾರರು ಯಾರು?","options":["ಪೋಷಕರು","ಎಸ್‌ಡಿಎಂಸಿ","ಅಂಗನವಾಡಿ ಕಾರ್ಯಕರ್ತೆ","ಇವರೆಲ್ಲರೂ"],"why":"ಎಲ್ಲರಿಗೂ ಆಸಕ್ತಿ ಮತ್ತು ಪ್ರಭಾವವಿದೆ."},{"q":"ಸುಗ್ಗಿಯ ಸಮಯದಲ್ಲಿ ಸಭೆ ನಿಗದಿಪಡಿಸುವುದು…","options":["ಗೌರವಪೂರ್ಣ","ಕೃಷಿಕ ಕುಟುಂಬಗಳನ್ನು ಹೊರಗಿಡುವ ಸಾಧ್ಯತೆ","ಕಡ್ಡಾಯ","ಅಪ್ರಸ್ತುತ"],"why":"ಸಮಯ ಯಾರು ಭಾಗವಹಿಸಬಹುದು ಎಂಬುದನ್ನು ನಿರ್ಧರಿಸುತ್ತದೆ."}]},"m10":{"objectives":["ದೋಷ ಕಡಿಮೆ ಮಾಡುವ ನಮೂನೆಗಳನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸುವುದು.","ಕ್ಷೇತ್ರ ತನಿಖಾಧಿಕಾರಿಗಳಿಗೆ ತರಬೇತಿ ನೀಡಿ ಗುಣಮಟ್ಟದ ಮೇಲುಸ್ತುವಾರಿ ಮಾಡುವುದು.","ದತ್ತಾಂಶವನ್ನು ಶುದ್ಧೀಕರಿಸಿ, ಸಂಕೇತಿಸಿ, ನಿರ್ವಹಿಸುವುದು.","ವರ್ಣನಾತ್ಮಕ ಮತ್ತು ಅನುಮಾನಾತ್ಮಕ ವಿಶ್ಲೇಷಣೆ ನಡೆಸಿ ವ್ಯಾಖ್ಯಾನಿಸುವುದು."],"lessons":[{"title":"ಕ್ಷೇತ್ರಕಾರ್ಯ ಯೋಜನೆ","body":["ಪ್ರತಿ ಸಾಧನವನ್ನು ಮಾದರಿಯಲ್ಲಿಲ್ಲದ 2–3 ಶಾಲೆಗಳಲ್ಲಿ ಪ್ರಾಯೋಗಿಕವಾಗಿ ಪರೀಕ್ಷಿಸಿ. ತನಿಖಾಧಿಕಾರಿ ಕೈಪಿಡಿ ಬರೆಯಿರಿ. ದತ್ತಾಂಶ ಸಂಗ್ರಹಿಸುವ ಸಿಆರ್‌ಪಿ ಅಥವಾ ಪ್ರಶಿಕ್ಷಣಾರ್ಥಿಗಳಿಗೆ ಅಣಕು ಸಂದರ್ಶನಗಳೊಂದಿಗೆ ತರಬೇತಿ ನೀಡಿ. ಪರೀಕ್ಷೆ ಅಥವಾ ಹಬ್ಬದ ದಿನಗಳಲ್ಲಿ ಶಾಲಾ ಭೇಟಿ ಆಗದಂತೆ ಯೋಜಿಸಿ."]},{"title":"ದತ್ತಾಂಶ ನಿರ್ವಹಣೆ","body":["ಸಂಕೇತ ಪುಸ್ತಕ (codebook) ರಚಿಸಿ: ಚರಾಂಶದ ಹೆಸರು, ಶೀರ್ಷಿಕೆ, ಮೌಲ್ಯಗಳು, ಕಾಣೆಯಾದ ದತ್ತಾಂಶದ ಸಂಕೇತಗಳು. ದತ್ತಾಂಶವನ್ನು ಎರಡು ಬಾರಿ ನಮೂದಿಸಿ ಅಥವಾ ಶೇ. 10 ನಮೂನೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ. ದಿನಾಂಕಿತ ಆವೃತ್ತಿಗಳೊಂದಿಗೆ ಕಡತಗಳನ್ನು ಉಳಿಸಿ, ಮುಖ್ಯ ಪ್ರತಿಯನ್ನು ಓದಲು-ಮಾತ್ರ ಇಡಿ ಮತ್ತು ಬ್ಯಾಕಪ್ ಮಾಡಿ."]},{"title":"ವಿಶ್ಲೇಷಣೆ ಮತ್ತು ವ್ಯಾಖ್ಯಾನ","body":["ವರ್ಣನಾತ್ಮಕ ಅಂಕಿಅಂಶಗಳಿಂದ ಆರಂಭಿಸಿ: n, ಸರಾಸರಿ, ಮಧ್ಯಾಂಕ, ಪ್ರಮಾಣಿತ ವಿಚಲನೆ, ಆವರ್ತನಗಳು. ನಂತರ ಊಹೆಗಳನ್ನು ಪರೀಕ್ಷಿಸಿ. ಪರೀಕ್ಷೆ, ಅಂಕಿಅಂಶ, ಸ್ವಾತಂತ್ರ್ಯ ಮಟ್ಟ, p-ಮೌಲ್ಯ ಮತ್ತು ಪರಿಣಾಮ ಗಾತ್ರವನ್ನು ವರದಿ ಮಾಡಿ: \"t(38) = 2.41, p = .021, d = 0.76\". ಸಾಂಖ್ಯಿಕ ಮಹತ್ವ ಪ್ರಾಯೋಗಿಕ ಮಹತ್ವಕ್ಕೆ ಸಮವಲ್ಲ.","ಗುಣಾತ್ಮಕ ದತ್ತಾಂಶಕ್ಕೆ ಘಟಕ 5ರ ಸಂಕೇತೀಕರಣ ಮತ್ತು ವಿಷಯವಸ್ತು ಹಂತಗಳನ್ನು ಬಳಸಿ. ಬಹುತೇಕ ಡಯಟ್ ಅಧ್ಯಯನಗಳಿಗೆ ಲಿಬ್ರೆಆಫೀಸ್ ಕ್ಯಾಲ್ಕ್‌ನಂತಹ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ತಂತ್ರಾಂಶ ಸಾಕು; ಮುಂದುವರಿದ ಕೆಲಸಕ್ಕೆ JASP ಮತ್ತು R ಉಚಿತವಾಗಿ ಲಭ್ಯ."]}],"karnataka":[{"title":"ಉದಾಹರಣೆ: ಗ್ರಂಥಾಲಯ ಪುಸ್ತಕ ಪಡೆಯುವಿಕೆಯ ಮೇಲೆ ಕೈ-ವರ್ಗ","text":["ಮಂಡ್ಯ ಜಿಲ್ಲೆಯ 200 ಮಂದಿ 7ನೇ ತರಗತಿ ಮಕ್ಕಳ ಉದಾಹರಣಾ ದತ್ತಾಂಶ: 100 ಬಾಲಕಿಯರಲ್ಲಿ 62 ಮಂದಿ ಕಳೆದ ತಿಂಗಳು ಗ್ರಂಥಾಲಯ ಪುಸ್ತಕ ಪಡೆದರು; 100 ಬಾಲಕರಲ್ಲಿ 45 ಮಂದಿ. ಪುಸ್ತಕ ಪಡೆಯುವಿಕೆ ಲಿಂಗದೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದೆಯೇ? 2×2 ಕೋಷ್ಟಕವನ್ನು (62, 38 / 45, 55) ಕೈ-ವರ್ಗ ಸಾಧನದಲ್ಲಿ ನಮೂದಿಸಿ. ಫಲಿತಾಂಶ (χ² ≈ 5.8, p ≈ .016) ಸಂಬಂಧವನ್ನು ಸೂಚಿಸುತ್ತದೆ; ಕಾರಣ ತಿಳಿಯಲು ಸಂದರ್ಶನಗಳನ್ನು ನಡೆಸಿ."]},{"title":"ಉದಾಹರಣೆ: ಮಾಧ್ಯಮಗಳ ನಡುವೆ ANOVA","text":["ಕನ್ನಡ, ಇಂಗ್ಲಿಷ್ ಮತ್ತು ಉರ್ದು ಮಾಧ್ಯಮದ ತಲಾ ಮೂರು ಶಾಲೆಗಳ ಉದಾಹರಣಾ LBA ಗಣಿತ ಅಂಕಗಳು (20ಕ್ಕೆ). ಏಕಮುಖ ANOVA ನಡೆಸಿ; ಮಹತ್ವದ್ದಾಗಿದ್ದರೆ ಯಾವ ಜೋಡಿಗಳು ಭಿನ್ನ ಎಂದು ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಮಾಧ್ಯಮದ ಆಚೆಗಿನ ವಿವರಣೆಗಳನ್ನು (ಶಿಕ್ಷಕರ ಖಾಲಿ ಹುದ್ದೆಗಳು, ದಾಖಲಾತಿ ಗಾತ್ರ) ಹುಡುಕಿ."]}],"activity":{"title":"ಉದಾಹರಣಾ ದತ್ತಾಂಶ ವಿಶ್ಲೇಷಿಸಿ","prompt":"ಸಾಂಖ್ಯಿಕ ಸಾಧನದಲ್ಲಿ ಕೈ-ವರ್ಗ ಉದಾಹರಣೆ ಮತ್ತು ಒಂದು ANOVA ನಡೆಸಿ. APA ಶೈಲಿಯಲ್ಲಿ ಫಲಿತಾಂಶ ಪರಿಚ್ಛೇದ ಬರೆಯಿರಿ."},"quiz":[{"q":"ಸಂಕೇತ ಪುಸ್ತಕ ದಾಖಲಿಸುವುದು…","options":["ಪಾಸ್‌ವರ್ಡ್‌ಗಳು","ಚರಾಂಶಗಳ ಹೆಸರು, ಶೀರ್ಷಿಕೆ ಮತ್ತು ಮೌಲ್ಯ ಸಂಕೇತಗಳು","ಶಿಕ್ಷಕರ ವೇತನ","ಕಾಣೆಯಾದ ದತ್ತಾಂಶ ಮಾತ್ರ"],"why":"ದತ್ತಾಂಶವನ್ನು ಹೇಗೆ ಸಂಕೇತಿಸಲಾಗಿದೆ ಎಂದು ದಾಖಲಿಸುತ್ತದೆ."},{"q":"p = .03 ಎಂದರೆ…","options":["ಪರಿಣಾಮ ದೊಡ್ಡದು","ನಿಜವಾದ ಪರಿಣಾಮ ಇಲ್ಲದಿದ್ದರೆ, ಇಷ್ಟು ತೀವ್ರ ಫಲಿತಾಂಶ ಸುಮಾರು ಶೇ. 3 ಬಾರಿ ಬರುತ್ತದೆ","ಊಹೆ ಶೇ. 97 ಸತ್ಯ","ದತ್ತಾಂಶ ತಪ್ಪು"],"why":"p ಶೂನ್ಯ ಊಹೆಯ ಅಡಿಯಲ್ಲಿ ದತ್ತಾಂಶದ ಬಗ್ಗೆ ಹೇಳುತ್ತದೆ."},{"q":"ಪರಿಣಾಮ ಗಾತ್ರವನ್ನು ವರದಿ ಮಾಡುವುದು ಏಕೆಂದರೆ…","options":["ಅದು ವ್ಯತ್ಯಾಸದ ಪ್ರಾಯೋಗಿಕ ಗಾತ್ರ ತೋರಿಸುತ್ತದೆ","ನಿಯತಕಾಲಿಕಗಳಿಗೆ ಅಂಕಿ ಬೇಕು","ಅದು ಸರಾಸರಿಗೆ ಬದಲಿ","ಅದೇ p-ಮೌಲ್ಯ"],"why":"ಮಹತ್ವ ≠ ಪ್ರಾಮುಖ್ಯತೆ."},{"q":"ಸಾಧನಗಳನ್ನು ಪ್ರಾಯೋಗಿಕವಾಗಿ ಪರೀಕ್ಷಿಸಬೇಕಾದದ್ದು…","options":["ಮಾದರಿ ಶಾಲೆಗಳಲ್ಲಿ","ಮಾದರಿಯ ಹೊರಗಿನ ಆದರೆ ಹೋಲುವ ಶಾಲೆಗಳಲ್ಲಿ","ಡಯಟ್ ಕಚೇರಿಯಲ್ಲಿ","ಯಾವ ಶಾಲೆಯಲ್ಲೂ ಇಲ್ಲ"],"why":"ಮಾದರಿ ಕಲುಷಿತವಾಗದಂತೆ."}]},"m11":{"objectives":["ಪ್ರಮಾಣಿತ ರಚನೆಯೊಂದಿಗೆ ಸಂಶೋಧನಾ ವರದಿ ಬರೆಯುವುದು.","APA ಶೈಲಿಯಲ್ಲಿ ಮೂಲಗಳನ್ನು ಉಲ್ಲೇಖಿಸುವುದು.","ಶಿಕ್ಷಕರು, ಅಧಿಕಾರಿಗಳು ಮತ್ತು ಸಮುದಾಯಗಳಿಗೆ ಫಲಿತಾಂಶಗಳನ್ನು ಪ್ರಸ್ತುತಪಡಿಸುವುದು.","ನೀತಿ ಸಂಕ್ಷೇಪ ಮತ್ತು ಭಿತ್ತಿಪತ್ರ ಸಿದ್ಧಪಡಿಸುವುದು."],"lessons":[{"title":"ವರದಿಯ ರಚನೆ","body":["ಶೀರ್ಷಿಕೆ, ಸಾರಾಂಶ (150–250 ಪದಗಳು), ಪೀಠಿಕೆ ಮತ್ತು ಸಮಸ್ಯೆ, ಸಂಬಂಧಿತ ಸಾಹಿತ್ಯ ಅವಲೋಕನ, ಉದ್ದೇಶಗಳು ಮತ್ತು ಪ್ರಶ್ನೆಗಳು, ವಿಧಾನ (ವಿನ್ಯಾಸ, ಮಾದರಿ, ಸಾಧನಗಳು, ಕಾರ್ಯವಿಧಾನ, ನೈತಿಕತೆ), ಫಲಿತಾಂಶಗಳು, ಚರ್ಚೆ, ಶಿಫಾರಸುಗಳು, ಮಿತಿಗಳು, ಉಲ್ಲೇಖಗಳು, ಅನುಬಂಧಗಳು (ಸಾಧನಗಳು, ಒಪ್ಪಿಗೆ ಪತ್ರಗಳು)."]},{"title":"ವಿವಿಧ ಓದುಗರಿಗಾಗಿ ಬರವಣಿಗೆ","body":["ಅಧಿಕಾರಿಗಳಿಗೆ ಎರಡು ಪುಟಗಳ ನೀತಿ ಸಂಕ್ಷೇಪ ಬೇಕು: ಸಮಸ್ಯೆ, ಮೂರು ಮುಖ್ಯ ಫಲಿತಾಂಶಗಳು, ಮೂರು ಕ್ರಮಗಳು ಮತ್ತು ವೆಚ್ಚ ಅಥವಾ ಕಾರ್ಯಸಾಧ್ಯತೆ. ಶಿಕ್ಷಕರಿಗೆ ವ್ಯಾವಹಾರಿಕ ತರಗತಿ ಸೂಚನೆಗಳು ಬೇಕು. ಸಮುದಾಯಗಳಿಗೆ ಚಿತ್ರಗಳೊಂದಿಗೆ ಕನ್ನಡದಲ್ಲಿ ಕಿರು ಮಾತು ಬೇಕು. ವಿದ್ವಾಂಸರಿಗೆ ಪೂರ್ಣ ವರದಿ ಅಥವಾ ನಿಯತಕಾಲಿಕ ಲೇಖನ ಬೇಕು."]},{"title":"ಉಲ್ಲೇಖ ಮತ್ತು ಪ್ರಕಟಣೆ","body":["APA 7ನೇ ಆವೃತ್ತಿ ಬಳಸಿ: ಲೇಖಕ, ಅ. ಅ. (ವರ್ಷ). ಶೀರ್ಷಿಕೆ. ಪ್ರಕಾಶಕ. ನಿಯತಕಾಲಿಕಗಳನ್ನು UGC-CARE ಪಟ್ಟಿಯೊಂದಿಗೆ ಪರಿಶೀಲಿಸಿ; ನಿಜವಾದ ಸಹವರ್ತಿ ಪರಿಶೀಲನೆಯಿಲ್ಲದೆ ಶುಲ್ಕ ವಿಧಿಸುವ ಶೋಷಕ ನಿಯತಕಾಲಿಕಗಳನ್ನು ತಪ್ಪಿಸಿ. ಡಿಎಸ್‌ಇಆರ್‌ಟಿ ಸಂಶೋಧನಾ ಸಮ್ಮೇಳನಗಳು ಮತ್ತು ಜಿಲ್ಲಾ ಪ್ರಗತಿ ಪರಿಶೀಲನಾ ಸಭೆಗಳಲ್ಲಿ ಹಂಚಿಕೊಳ್ಳಿ."]}],"karnataka":[{"title":"ವರದಿಯಿಂದ ನಿರ್ಧಾರದವರೆಗೆ","text":["ಕೆಲವೇ ಪ್ರೌಢಶಾಲೆಗಳು ತಮ್ಮ ವಿಜ್ಞಾನ ಪ್ರಯೋಗಾಲಯವನ್ನು ವಾರಕ್ಕೊಮ್ಮೆ ಬಳಸುತ್ತವೆ ಎಂದು ಡಯಟ್ ಅಧ್ಯಯನ ಕಂಡುಕೊಳ್ಳುತ್ತದೆ (ಉದಾಹರಣೆ). ಉಪನಿರ್ದೇಶಕರು (ಆಡಳಿತ) ಮತ್ತು ಡಯಟ್ ಪ್ರಾಂಶುಪಾಲರಿಗೆ ಉತ್ತಮ ನೀತಿ ಸಂಕ್ಷೇಪ ಹೀಗೆ ಶಿಫಾರಸು ಮಾಡುತ್ತದೆ: ವೇಳಾಪಟ್ಟಿಯಲ್ಲಿ ವಾರದ ಪ್ರಯೋಗಾಲಯ ಅವಧಿ, ಕಡಿಮೆ ವೆಚ್ಚದ ಪ್ರಯೋಗಗಳ ಕುರಿತು ಸಿಆರ್‌ಸಿ ಕಿರು ತರಬೇತಿ, ಮತ್ತು ಮುಂದಿನ ಶೈಕ್ಷಣಿಕ ವರ್ಷದಲ್ಲಿ ಅನುಸರಣಾ ಪರಿಶೀಲನೆ."]}],"activity":{"title":"ನಿಮ್ಮ ಪ್ರಸ್ತಾವನೆ ರಚಿಸಿ","prompt":"ಪ್ರಸ್ತಾವನಾ ರಚನಾ ಸಾಧನ ಬಳಸಿ ಸಂಪೂರ್ಣ ಸಂಶೋಧನಾ ಪ್ರಸ್ತಾವನೆಯ ಕರಡು ಸಿದ್ಧಪಡಿಸಿ. ರಫ್ತು ಮಾಡಿ ಸಂಪನ್ಮೂಲ ವ್ಯಕ್ತಿಯೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಿ."},"quiz":[{"q":"ಅಧಿಕಾರಿಗಳಿಗಾಗಿ ನೀತಿ ಸಂಕ್ಷೇಪ ಹೀಗಿರಬೇಕು…","options":["100 ಪುಟಗಳು","ಸ್ಪಷ್ಟ ಕ್ರಮಗಳಿರುವ ಸುಮಾರು ಎರಡು ಪುಟಗಳು","ಕೋಷ್ಟಕಗಳು ಮಾತ್ರ","ಶೈಕ್ಷಣಿಕ ಪರಿಭಾಷೆಯಲ್ಲಿ"],"why":"ಕಾರ್ಯನಿರತ ನಿರ್ಧಾರಕರಿಗೆ ಸಂಕ್ಷಿಪ್ತತೆ ಮತ್ತು ಕ್ರಮ ಬೇಕು."},{"q":"ನೈತಿಕ ಕಾರ್ಯವಿಧಾನವನ್ನು ಎಲ್ಲಿ ವಿವರಿಸಬೇಕು?","options":["ಸಾರಾಂಶದಲ್ಲಿ ಮಾತ್ರ","ವಿಧಾನ ವಿಭಾಗದಲ್ಲಿ","ಉಲ್ಲೇಖಗಳಲ್ಲಿ","ಎಲ್ಲಿಯೂ ಇಲ್ಲ"],"why":"ನೈತಿಕತೆ ವಿಧಾನದ ಭಾಗ."},{"q":"ಶೋಷಕ ನಿಯತಕಾಲಿಕಗಳು ಎಂದರೆ…","options":["ನಿಜವಾದ ಪರಿಶೀಲನೆಯ ನಂತರ ಬೇಗ ಪ್ರಕಟಿಸುವವು","ನಿಜವಾದ ಸಹವರ್ತಿ ಪರಿಶೀಲನೆಯಿಲ್ಲದೆ ಶುಲ್ಕ ವಿಧಿಸುವವು","ಕನ್ನಡದಲ್ಲಿರುವವು","UGC-CARE ಪಟ್ಟಿಯಲ್ಲಿರುವವು"],"why":"ಅವುಗಳಲ್ಲಿ ನಿಜವಾದ ಪರಿಶೀಲನೆ ಇಲ್ಲ."},{"q":"APA ಉಲ್ಲೇಖದ ಕ್ರಮ…","options":["ಶೀರ್ಷಿಕೆ, ವರ್ಷ, ಲೇಖಕ","ಲೇಖಕ, ವರ್ಷ, ಶೀರ್ಷಿಕೆ, ಮೂಲ","ವರ್ಷ, ಪ್ರಕಾಶಕ, ಲೇಖಕ","ಯಾವುದೇ ಕ್ರಮ"],"why":"ಲೇಖಕ–ದಿನಾಂಕ ಪದ್ಧತಿ."}]},"m12":{"objectives":["ಪ್ರತಿ ಹಂತದಲ್ಲಿ ಗುಣಮಟ್ಟದ ಮಾನದಂಡಗಳ ಆಧಾರದಲ್ಲಿ ಅಧ್ಯಯನವನ್ನು ಪರಿಶೀಲಿಸುವುದು.","ರಚನಾತ್ಮಕ ಸಹವರ್ತಿ ಪರಿಶೀಲನೆ ನಡೆಸುವುದು ಮತ್ತು ಸ್ವೀಕರಿಸುವುದು.","ಜಿಲ್ಲಾ ಅಧ್ಯಯನಗಳಲ್ಲಿ ಸಿಂಧುತ್ವಕ್ಕೆ ಸಾಮಾನ್ಯ ಅಪಾಯಗಳನ್ನು ಗುರುತಿಸುವುದು."],"lessons":[{"title":"ಚಕ್ರದುದ್ದಕ್ಕೂ ಗುಣಮಟ್ಟ","body":["ಪ್ರಶ್ನೆ: ಸ್ಪಷ್ಟ, ಕೇಂದ್ರೀಕೃತ, ಸಮರ್ಥಿತ. ವಿನ್ಯಾಸ: ಪ್ರಶ್ನೆಗೆ ಹೊಂದುತ್ತದೆ. ಮಾದರಿ: ಸಾಕಷ್ಟು ಮತ್ತು ಚೆನ್ನಾಗಿ ವಿವರಿಸಲಾಗಿದೆ. ಸಾಧನಗಳು: ಪ್ರಾಯೋಗಿಕವಾಗಿ ಪರೀಕ್ಷಿತ, ವಿಶ್ವಸನೀಯ, ಸಿಂಧು. ವಿಶ್ಲೇಷಣೆ: ಸೂಕ್ತ ಪರೀಕ್ಷೆಗಳು, ಪರಿಣಾಮ ಗಾತ್ರಗಳು, ಮಹತ್ವವಿಲ್ಲದ ಫಲಿತಾಂಶಗಳ ಪ್ರಾಮಾಣಿಕ ವರದಿ. ತೀರ್ಮಾನಗಳು: ಪುರಾವೆಯಿಂದ ಹೊರಹೊಮ್ಮುತ್ತವೆ; ಮಿತಿಗಳನ್ನು ಹೇಳಲಾಗಿದೆ."]},{"title":"ಸಿಂಧುತ್ವಕ್ಕೆ ಅಪಾಯಗಳು","body":["ಆಯ್ಕೆ ಪಕ್ಷಪಾತ (\"ಉತ್ತಮ\" ಶಾಲೆಗಳನ್ನು ಮಾತ್ರ ಆರಿಸುವುದು), ಇತಿಹಾಸ (ಅದೇ ಸಮಯದಲ್ಲಿ ಬೇರೆ ಕಾರ್ಯಕ್ರಮ ಆರಂಭವಾದುದು), ಪಕ್ವತೆ (ಮಕ್ಕಳು ಹೇಗಿದ್ದರೂ ಬೆಳೆಯುತ್ತಾರೆ), ಪರೀಕ್ಷಾ ಪರಿಣಾಮ (ಅದೇ ಪರೀಕ್ಷೆ ಎರಡು ಬಾರಿ), ಕ್ಷಯ (ಉತ್ತರ ಪರೀಕ್ಷೆಯ ದಿನ ಮಕ್ಕಳ ಗೈರು), ಮತ್ತು ಹಾಥಾರ್ನ್ ಪರಿಣಾಮ (ಗಮನಿಸಲಾಗುತ್ತಿದೆ ಎಂದು ಜನರು ಬದಲಾಗುವುದು)."]},{"title":"ಸಹವರ್ತಿ ಪರಿಶೀಲನೆ","body":["ವ್ಯಕ್ತಿಯನ್ನಲ್ಲ, ಕೆಲಸವನ್ನು ಪರಿಶೀಲಿಸಿ. ಸಾಮರ್ಥ್ಯಗಳಿಂದ ಆರಂಭಿಸಿ, ನಂತರ ಮುಖ್ಯ ಸಮಸ್ಯೆಗಳು, ನಂತರ ಸಣ್ಣ ಅಂಶಗಳು. ನಿರ್ದಿಷ್ಟ ಸುಧಾರಣೆಗಳನ್ನು ಸೂಚಿಸಿ. ಪ್ರತಿ ಡಯಟ್ ಅಧ್ಯಯನವನ್ನು ಸಲ್ಲಿಕೆಗೆ ಮುನ್ನ ಒಬ್ಬ ಆಂತರಿಕ ಮತ್ತು ಒಬ್ಬ ಹೊರಗಿನ ಸಹೋದ್ಯೋಗಿ ಪರಿಶೀಲಿಸಬಹುದು."]}],"karnataka":[{"title":"ಪರಿಶೀಲನಾ ಅಭ್ಯಾಸ: ದುರ್ಬಲ ವಿನ್ಯಾಸ","text":["ಪ್ರಸ್ತಾವನೆ: ಬಿಇಒ ಆರಿಸಿದ 5 ಶಾಲೆಗಳ ಉತ್ತರ-ಪರೀಕ್ಷಾ ಅಂಕಗಳನ್ನು ಮಾತ್ರ ಬಳಸಿ \"ಕಲಿಕಾ ಚೇತರಿಕೆಯ ಪರಿಣಾಮ\". ಸಮಸ್ಯೆಗಳು: ಮೂಲರೇಖೆ ಇಲ್ಲ, ಹೋಲಿಕೆ ಇಲ್ಲ, ಆಯ್ಕೆ ಪಕ್ಷಪಾತ. ಸುಧಾರಣೆ: ಸೇತುಬಂಧ ಮೂಲರೇಖೆಯನ್ನು ಪೂರ್ವ-ಪರೀಕ್ಷೆಯಾಗಿ ಬಳಸಿ, ಹೊಂದಾಣಿಕೆಯ ಹೋಲಿಕೆ ಶಾಲೆಗಳನ್ನು ಸೇರಿಸಿ, ಬ್ಲಾಕ್‌ಗಳೊಳಗೆ ಯಾದೃಚ್ಛಿಕವಾಗಿ ಶಾಲೆಗಳನ್ನು ಆರಿಸಿ."]},{"title":"ಹಂಚಿಕೊಂಡ ರಾಜ್ಯ ಕಾರ್ಯಸೂಚಿ","text":["ಕೆಲವು ರಾಜ್ಯವ್ಯಾಪಿ ಪ್ರಶ್ನೆಗಳಿರುವ ವಾರ್ಷಿಕ ರಾಜ್ಯ ಸಂಶೋಧನಾ ಕಾರ್ಯಸೂಚಿಯನ್ನು ರಾಜ್ಯದ ಸಂಶೋಧನಾ ಟಿಪ್ಪಣಿಗಳು ಸೂಚಿಸುತ್ತವೆ — ಉದಾ: FLN ಲಾಭಗಳು 3ನೇ ತರಗತಿಯ ಆಚೆಗೂ ಉಳಿಯುತ್ತವೆಯೇ — ಇದರಿಂದ ಜಿಲ್ಲೆಗಳು ಸಾಮಾನ್ಯ ಸಾಧನಗಳೊಂದಿಗೆ ಮಾದರಿಗಳನ್ನು ಒಗ್ಗೂಡಿಸಬಹುದು. ಡಯಟ್‌ಗಳು ಒಂಟಿಯಾಗಿ ಆರಂಭಿಸುವ ಬದಲು ವಿನ್ಯಾಸ ಮತ್ತು ಸಾಧನಗಳನ್ನು ಹಂಚಿಕೊಂಡಾಗ ಗುಣಮಟ್ಟ ಸುಧಾರಿಸುತ್ತದೆ."]}],"activity":{"title":"ಪ್ರಸ್ತಾವನೆಯ ಸಹವರ್ತಿ ಪರಿಶೀಲನೆ","prompt":"ಗುಣಮಟ್ಟ ಪರಿಶೀಲನಾ ಪಟ್ಟಿಯನ್ನು ನಿಮ್ಮ ಮತ್ತು ಸಹೋದ್ಯೋಗಿಯ ಪ್ರಸ್ತಾವನೆಗೆ ಅನ್ವಯಿಸಿ. ಮೂರು ಸಾಮರ್ಥ್ಯಗಳು ಮತ್ತು ಮೂರು ನಿರ್ದಿಷ್ಟ ಸುಧಾರಣೆಗಳನ್ನು ದಾಖಲಿಸಿ."},"quiz":[{"q":"\"ಉತ್ತಮ ಸಾಧನೆ\" ಎಂಬ ಕಾರಣಕ್ಕೆ ಅಧಿಕಾರಿ ಆರಿಸಿದ ಶಾಲೆಗಳು ಪರಿಚಯಿಸುವುದು…","options":["ಪಕ್ವತೆ","ಆಯ್ಕೆ ಪಕ್ಷಪಾತ","ವಿಶ್ವಸನೀಯತೆ","ತ್ರಿಕೋನೀಕರಣ"],"why":"ಯಾದೃಚ್ಛಿಕವಲ್ಲದ ಆಯ್ಕೆ ಫಲಿತಾಂಶಗಳನ್ನು ಪಕ್ಷಪಾತಗೊಳಿಸುತ್ತದೆ."},{"q":"ವರ್ಷದಲ್ಲಿ ವಯಸ್ಸು ಹೆಚ್ಚಿದ ಕಾರಣ ಮಾತ್ರ ಮಕ್ಕಳು ಸುಧಾರಿಸುವುದು…","options":["ಪಕ್ವತೆ","ಇತಿಹಾಸ","ಕ್ಷಯ","ಸಾಧನ ಬದಲಾವಣೆ"],"why":"ಕಾಲಾನಂತರದ ಸಹಜ ಬೆಳವಣಿಗೆ."},{"q":"ಉತ್ತಮ ಸಹವರ್ತಿ ಪರಿಶೀಲನೆ ಆರಂಭವಾಗುವುದು…","options":["ವೈಯಕ್ತಿಕ ಟೀಕೆಯಿಂದ","ಕೆಲಸದ ಸಾಮರ್ಥ್ಯಗಳಿಂದ","ತಿರಸ್ಕಾರದಿಂದ","ಕಾಗುಣಿತ ದೋಷಗಳಿಂದ ಮಾತ್ರ"],"why":"ರಚನಾತ್ಮಕ ಪರಿಶೀಲನೆ ಮೊದಲು ಸಾಮರ್ಥ್ಯಗಳನ್ನು ಗುರುತಿಸುತ್ತದೆ."},{"q":"ಮಹತ್ವವಿಲ್ಲದ ಫಲಿತಾಂಶಗಳನ್ನು ವರದಿ ಮಾಡುವುದು…","options":["ಅಪ್ರಾಮಾಣಿಕ","ಪ್ರಾಮಾಣಿಕ ಸಂಶೋಧನೆಯ ಭಾಗ","ನಿಷಿದ್ಧ","ಅನಗತ್ಯ"],"why":"ಅವುಗಳನ್ನು ಮರೆಮಾಚಿದರೆ ಪುರಾವೆ ಪಕ್ಷಪಾತಗೊಳ್ಳುತ್ತದೆ."}]}},"PRE_KN_DATA":[{"q":"ಊಹೆ (hypothesis) ಎಂದರೆ…","options":["ಫಲಿತಾಂಶಗಳ ಸಾರಾಂಶ","ಪರೀಕ್ಷಿಸಬಹುದಾದ ಮುನ್ನುಡಿ","ಉಲ್ಲೇಖಗಳ ಪಟ್ಟಿ","ಮಾದರಿ ಆಯ್ಕೆ ವಿಧಾನ"],"why":"ದತ್ತಾಂಶ ಪರೀಕ್ಷಿಸಬಹುದಾದ ಸಂಬಂಧವನ್ನು ಅದು ಮುನ್ನುಡಿಯುತ್ತದೆ."},{"q":"ಹೊಸ ಓದು ಕಾರ್ಯಕ್ರಮ ಸುಧಾರಣೆಗೆ ಕಾರಣವೇ ಎಂದು ಪರೀಕ್ಷಿಸಲು ಉತ್ತಮ ವಿನ್ಯಾಸ ಯಾವುದು?","options":["ಒಂದೇ ಸಮೀಕ್ಷೆ","ಹೋಲಿಕೆ ಗುಂಪು ಮತ್ತು ಪೂರ್ವ-ಪರೀಕ್ಷೆಯಿರುವ ಅರೆ-ಪ್ರಯೋಗ","ಒಂದು ಸಂದರ್ಶನ","ದಾಖಲೆ ಪರಿಶೀಲನೆ"],"why":"ಹೋಲಿಕೆ ಗುಂಪು ಮತ್ತು ಮೂಲರೇಖೆ ಇತರ ವಿವರಣೆಗಳನ್ನು ತಳ್ಳಿಹಾಕಲು ನೆರವಾಗುತ್ತವೆ."},{"q":"ತ್ರಿಕೋನೀಕರಣ (triangulation) ಎಂದರೆ…","options":["ಮೂರು ಶಾಲೆಗಳ ಬಳಕೆ","ಬೇರೆ ಬೇರೆ ದತ್ತಾಂಶ ಮೂಲಗಳು ಅಥವಾ ವಿಧಾನಗಳಿಂದ ಫಲಿತಾಂಶ ಪರಿಶೀಲನೆ","ರೇಖಾಗಣಿತ ಪರೀಕ್ಷೆ","ಮೂವರು ಸಂಶೋಧಕರ ಸಹಿ"],"why":"ಹಲವು ಮೂಲಗಳು ನಂಬಲರ್ಹತೆಯನ್ನು ಬಲಪಡಿಸುತ್ತವೆ."},{"q":"ಹರಡುವಿಕೆಯನ್ನು ವರ್ಣಿಸುವ ಅಂಕಿಅಂಶ ಯಾವುದು?","options":["ಸರಾಸರಿ","ಪ್ರಮಾಣಿತ ವಿಚಲನೆ","ಬಹುಲಕ","ಮಧ್ಯಾಂಕ"],"why":"ಪ್ರಮಾಣಿತ ವಿಚಲನೆ ಚದುರುವಿಕೆಯನ್ನು ಅಳೆಯುತ್ತದೆ."},{"q":"ತಿಳುವಳಿಕೆಯುಳ್ಳ ಒಪ್ಪಿಗೆಗೆ ಬೇಕಾದದ್ದು…","options":["ಮುಖ್ಯ ಶಿಕ್ಷಕರ ಸಹಿ ಮಾತ್ರ","ಭಾಗವಹಿಸುವವರು ಅಧ್ಯಯನವನ್ನು ಅರ್ಥಮಾಡಿಕೊಂಡು ಸ್ವತಂತ್ರವಾಗಿ ಒಪ್ಪುವುದು","ಹಣ ಪಾವತಿ","ಬಿಇಒ ಅನುಮತಿ ಮಾತ್ರ"],"why":"ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವಿಕೆ ಮತ್ತು ಸ್ವಯಂಪ್ರೇರಿತ ಒಪ್ಪಿಗೆ."}],"ADVANCED":[{"id":"m13","no":13,"hours":4,"part":2,"title":"Research Design, Proposal Development and AI Assistance","titleKn":"ಸಂಶೋಧನಾ ವಿನ್ಯಾಸ, ಪ್ರಸ್ತಾವನೆ ರಚನೆ ಮತ್ತು ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆಯ ನೆರವು","objectives":["Identify and state a research gap precisely.","Align problem, questions, objectives, hypotheses, design and analysis in one matrix.","Structure a fundable, reviewable research proposal with a conceptual framework.","Use AI tools to assist proposal development while protecting integrity and data."],"lessons":[{"title":"From research gap to research questions","body":["A gap is what the existing evidence does not yet tell us. Six common kinds: an evidence gap (findings disagree), a knowledge gap (the topic is unstudied), a practical gap (what works in practice is not documented), a methodological gap (earlier studies used weak designs or tools), a population gap (the topic is unstudied for a group or place), and a theoretical gap (no framework explains the pattern).","Write the gap in one sentence: \"Although [what is known], [what is not known] for [population, place], because [reason earlier studies fall short].\" Test the question with FINER: Feasible, Interesting, Novel, Ethical, Relevant.","Alignment is the backbone of a strong proposal. Each research question needs a matching objective, a hypothesis where relevant, a named data source or tool, and an analysis. If a question has no analysis, or an analysis answers no question, the proposal is misaligned."]},{"title":"Choosing a design and structuring the proposal","body":["Choose the design from the question, not from habit: describe → survey; relate → correlational or SEM; compare existing groups → causal-comparative; test an intervention → experimental or quasi-experimental; understand meanings → qualitative; explain numbers → explanatory sequential mixed methods.","A conceptual framework is a diagram of the constructs and the relationships the study will test, each arrow backed by theory or earlier evidence. It becomes the measurement model (constructs and items) and the structural model (paths) in Chapters 15 and 16.","Reviewers most often reject proposals for a vague problem, an unjustified sample size, tools with no evidence of reliability or validity, analysis that does not match the questions, missing ethics, and an unrealistic timeline."]},{"title":"AI-assisted proposal development","body":["AI tools can help at several stages: literature discovery (Semantic Scholar, Elicit, Consensus, Research Rabbit, Connected Papers), reference management (Zotero), brainstorming research questions, outlining a review, improving clarity of language, and explaining statistical procedures or code.","AI tools can also invent references, misquote findings and state errors with confidence. Every citation an AI suggests must be opened and checked at the source. Never paste identifiable data — SATS records, names, phone numbers, unpublished interview transcripts — into a public AI tool.","Integrity rules: an AI tool cannot be an author, because it cannot take responsibility for the work (COPE position statement, 2023). Disclose the tool, version and purpose in the methods or acknowledgements, as most journals now require. The researcher remains responsible for every sentence and number."]}],"karnataka":[{"title":"An alignment matrix for a Sethubandha study","text":["Gap: \"Although Sethubandha is run at the start of every year, no district study has followed whether Grade 4 gains last until the end of Grade 5 in Kalyana Karnataka.\" RQ1: What is the change in Kannada reading scores from June (Grade 4) to March (Grade 5)? → Objective: to estimate retention of gains → H1: scores at the end of Grade 5 remain above the June baseline → Data: LBA reading scores and a graded reading test → Analysis: paired t-test and effect size.","RQ2: Which school factors are associated with retention? → Data: head-teacher survey on library periods, teacher vacancies and attendance → Analysis: multiple regression (or SEM in Chapter 16)."]},{"title":"Using an AI assistant safely for a review outline","text":["A DIET lecturer asks an AI assistant: \"Suggest an outline for a literature review on multigrade teaching in Indian government primary schools, with headings and the kinds of studies to look for. Do not invent citations.\" She then searches Shodhganga, ERIC and the DSERT compendia herself for each heading, keeps only studies she has opened, and records in her methods note which tool she used and for what."]}],"activity":{"title":"Build your alignment matrix","prompt":"Use the alignment matrix to link each research question to an objective, hypothesis, data source and analysis. Then use the AI prompt planner to draft one safe prompt for your literature search and write your AI-use disclosure statement.","tool":"align"},"tools":["align","aiprompt","proposal"],"quiz":[{"q":"\"Earlier studies of LBA used only post-tests without a baseline.\" This is mainly a…","options":["Population gap","Methodological gap","Theoretical gap","Practical gap"],"answer":1,"why":"The weakness lies in how earlier studies were designed."},{"q":"An AI assistant gives you five references. What must you do?","options":["Cite them as given","Open and verify each one at the source before citing","List the AI as co-author","Cite only the first one"],"answer":1,"why":"AI tools can fabricate or misreport references."},{"q":"Which may be pasted into a public AI tool?","options":["A spreadsheet of SATS numbers and marks","Unpublished interview transcripts with names","Your own draft paragraph with no personal data","Parents' phone numbers"],"answer":2,"why":"Identifiable or confidential data must never be shared."},{"q":"In an alignment matrix, an analysis that answers no research question shows…","options":["Thoroughness","Misalignment to be removed or justified","Strong design","Mixed methods"],"answer":1,"why":"Every analysis should answer a stated question."}]},{"id":"m14","no":14,"hours":4,"part":2,"title":"Measurement, Scales and Data Preparation","titleKn":"ಮಾಪನ, ಮಾಪಕಗಳು ಮತ್ತು ದತ್ತಾಂಶ ಸಿದ್ಧತೆ","objectives":["Distinguish levels of measurement and reflective from formative constructs.","Develop and translate a Likert scale using sound psychometric steps.","Choose the right statistical technique for a question and data type.","Screen, clean and prepare data in R or Python."],"lessons":[{"title":"Constructs, scales and instrument development","body":["Levels of measurement decide which statistics are allowed: nominal (medium of instruction), ordinal (ranks, single Likert items), interval (summed scale scores, treated as interval in practice) and ratio (words correct per minute, attendance days).","A construct is an unobserved quality such as \"research self-efficacy\". Reflective constructs cause their items, so items should correlate highly and are interchangeable (most attitude scales). Formative constructs are formed by their indicators, like a school facilities index built from library, laboratory and toilets; their indicators need not correlate.","Scale development steps: define the construct and its dimensions → write an item pool (3–4 times the final number) → expert review for content validity (item-level CVI ≥ .78) → cognitive interviews with a few teachers → pilot (n ≥ 100) → item analysis (corrected item–total r ≥ .30) → factor analysis (Chapter 15). Write short, single-idea items; avoid double-barrelled and leading items; add a few reverse-worded items and recode them before analysis.","For Kannada versions use forward translation by two translators, reconciliation, back-translation by an independent translator, and review by a committee; then pilot both language versions."]},{"title":"Choosing the statistical technique","body":["Decide from four questions: What is the aim (compare, relate, predict, explore structure, confirm structure, test a model)? What level is the outcome? How many groups, and are they independent or paired? Are parametric assumptions reasonable?","Common pairs (parametric → non-parametric): independent t-test → Mann–Whitney U; paired t-test → Wilcoxon signed-rank; one-way ANOVA → Kruskal–Wallis; Pearson r → Spearman ρ. For prediction use multiple regression (logistic regression for a yes/no outcome). For the structure of a scale use EFA, then CFA; for relationships among constructs use SEM."]},{"title":"Data screening, cleaning and preparation","body":["Screen in this order: (1) out-of-range values and entry errors; (2) missing data — describe the amount and pattern; under 5% scattered missingness is usually harmless, otherwise use multiple imputation or full-information maximum likelihood rather than deleting cases; (3) careless responding such as straight-lining (the same answer to every item); (4) outliers — univariate |z| > 3.29, multivariate by Mahalanobis distance (p < .001); (5) normality — skewness within ±2 and excess kurtosis within ±7 is usually acceptable for SEM with maximum likelihood; (6) multicollinearity — VIF below 5.","With a single self-report questionnaire, check common method bias: if one unrotated factor explains more than 50% of the variance (Harman's single-factor test), interpret relationships with caution. Better still, design it out: separate sections, assure anonymity, mix item order.","Keep a cleaning log: what was changed, why, and how many cases were affected. Never overwrite the raw file; save a cleaned copy with a new name."],"code":[{"label":"Screening in R","lang":"R","src":"library(psych)\nd <- read.csv(\"trse.csv\")\nd[d < 1 | d > 5] <- NA                      # out-of-range values become missing\ncolMeans(is.na(d)) * 100                    # % missing per item\nd$sd_row <- apply(d[, 1:12], 1, sd, na.rm = TRUE)\nd <- subset(d, sd_row > 0)                  # drop straight-liners\ndescribe(d[, 1:12])                         # mean, sd, skew, kurtosis\nz <- scale(d[, 1:12]); which(abs(z) > 3.29, arr.ind = TRUE)\nmd <- mahalanobis(na.omit(d[, 1:12]), colMeans(na.omit(d[, 1:12])), cov(na.omit(d[, 1:12])))\nwhich(md > qchisq(.999, df = 12))           # multivariate outliers\nalpha(d[, c(\"PF1\",\"PF2\",\"PF3\",\"PF4\")])      # Cronbach's alpha"},{"label":"Screening in Python","lang":"Python","src":"import pandas as pd, numpy as np\nfrom scipy import stats\nd = pd.read_csv(\"trse.csv\")\nitems = d.columns[:12]\nd[items] = d[items].where(d[items].between(1, 5))   # out-of-range -> NaN\nprint(d[items].isna().mean() * 100)                  # % missing per item\nd = d[d[items].std(axis=1) > 0]                       # drop straight-liners\nprint(d[items].agg([\"mean\", \"std\", \"skew\", \"kurt\"]).T)\nz = np.abs(stats.zscore(d[items], nan_policy=\"omit\"))\nprint((z > 3.29).sum())                               # univariate outliers per item"}]}],"karnataka":[{"title":"A bilingual research self-efficacy scale for DIET faculty","text":["A DSERT working group drafts 36 items on three dimensions — problem framing, data analysis and research communication — for DIET lecturers and CRPs. Six experts rate relevance; items with I-CVI below .78 are dropped. The remaining 18 items are translated into Kannada and back-translated; a cognitive interview reveals that \"hypothesis\" needs the Kannada term ಊಹೆ with the English word in brackets. After piloting with 120 lecturers, 12 items are kept for factor analysis."]},{"title":"Cleaning an SDMC survey","text":["In an illustrative survey of 400 SDMC members in Bidar district, 6% of answers to an income question are missing, while other items have under 2% missing. The researcher reports the pattern, keeps all cases, and uses multiple imputation rather than deleting 24 respondents — most of whom were women members, whose views would otherwise be under-represented."]}],"activity":{"title":"Screen a dataset and choose a technique","prompt":"Load the sample data in the screening tool. Identify the missing values, out-of-range entry, straight-liners and outliers, and note what you would do with each. Then use the technique chooser for your own research question.","tool":"screen"},"tools":["screen","chooser","survey","stats"],"quiz":[{"q":"A school facilities index built from library, laboratory and toilets is best treated as…","options":["A reflective construct","A formative construct","A nominal variable","An outlier"],"answer":1,"why":"The indicators form the index; they need not correlate."},{"q":"The non-parametric alternative to a paired t-test is…","options":["Mann–Whitney U","Wilcoxon signed-rank","Kruskal–Wallis","Chi-square"],"answer":1,"why":"Wilcoxon signed-rank compares paired observations."},{"q":"A respondent answers \"5\" to all 40 items. This is…","options":["Excellent data","Possible straight-lining (careless responding)","A formative indicator","A missing value"],"answer":1,"why":"Identical answers throughout suggest careless responding."},{"q":"Back-translation is used to…","options":["Increase sample size","Check that a translated instrument keeps the original meaning","Remove outliers","Test hypotheses"],"answer":1,"why":"An independent translator reverses the translation to reveal drift in meaning."}]},{"id":"m15","no":15,"hours":4,"part":2,"title":"Construct Exploration and Validation: EFA and CFA","titleKn":"ರಚನೆಗಳ ಅನ್ವೇಷಣೆ ಮತ್ತು ದೃಢೀಕರಣ: EFA ಮತ್ತು CFA","objectives":["Check whether data are suitable for factor analysis (KMO, Bartlett).","Run and interpret an exploratory factor analysis in SPSS, R or Python.","Specify and assess a measurement model with confirmatory factor analysis in AMOS or lavaan.","Establish reliability, convergent validity and discriminant validity."],"lessons":[{"title":"Exploratory factor analysis (EFA)","body":["EFA asks: how many underlying factors explain the correlations among items, and which items belong to which factor? Use it when a scale is new or used in a new population.","Suitability: at least 5–10 respondents per item and preferably 200 or more; KMO ≥ .60 (≥ .80 is good) and each item's KMO ≥ .50; Bartlett's test of sphericity significant (p < .05).","Extraction: principal axis factoring or maximum likelihood estimate common factors; principal components analysis summarises total variance and is not strictly factor analysis. How many factors: eigenvalues > 1 (Kaiser), the elbow of the scree plot, and — most reliable — parallel analysis; the solution must also make theoretical sense.","Rotation: varimax (orthogonal) when factors are expected to be unrelated; promax or oblimin (oblique) when they are expected to correlate, which is usual in education. Keep items with loadings ≥ .50 on their own factor and cross-loadings below .30 (or at least .20 lower); communalities ideally ≥ .40. Remove weak items one at a time and re-run.","SPSS: Analyze → Dimension Reduction → Factor → Descriptives: KMO and Bartlett's test; Extraction: Principal axis factoring, Scree plot; Rotation: Promax (or Varimax); Options: Sorted by size, suppress small coefficients below .30."],"code":[{"label":"EFA in R (psych)","lang":"R","src":"library(psych)\nitems <- d[, 1:12]\nKMO(items); cortest.bartlett(cor(items), n = nrow(items))\nfa.parallel(items, fa = \"fa\")                 # how many factors?\nefa <- fa(items, nfactors = 3, fm = \"pa\", rotate = \"promax\")\nprint(efa$loadings, cutoff = .30, sort = TRUE)"},{"label":"EFA in Python (factor_analyzer)","lang":"Python","src":"from factor_analyzer import FactorAnalyzer, calculate_kmo, calculate_bartlett_sphericity\nitems = d.iloc[:, :12].dropna()\nprint(calculate_kmo(items)[1], calculate_bartlett_sphericity(items))\nfa = FactorAnalyzer(n_factors=3, method=\"principal\", rotation=\"promax\")\nfa.fit(items)\nprint(pd.DataFrame(fa.loadings_, index=items.columns).round(2))"}]},{"title":"Confirmatory factor analysis (CFA)","body":["CFA tests a measurement model specified in advance: which items load on which factor, with no cross-loadings. Use a different sample from the EFA (split the data randomly, or collect a second sample).","In AMOS: draw each latent factor as an ellipse, its items as rectangles, add an error term to every item, fix the first loading of each factor to 1 (or the factor variance to 1), connect factors with two-headed arrows (covariances), choose Maximum likelihood, and tick Standardized estimates and Modification indices in Analysis Properties. Report model fit (Chapter 16) before interpreting loadings.","Assessment: standardised loadings ≥ .70 are ideal (≥ .50 acceptable if reliability holds); composite reliability (CR) ≥ .70; average variance extracted (AVE) ≥ .50 for convergent validity. Discriminant validity: the square root of each factor's AVE should exceed its correlations with other factors (Fornell & Larcker, 1981), and the heterotrait–monotrait ratio (HTMT) should be below .85 (or .90 for similar concepts; Henseler et al., 2015)."],"code":[{"label":"CFA in R (lavaan)","lang":"R","src":"library(lavaan); library(semTools)\nmodel <- '\n  ProblemFraming =~ PF1 + PF2 + PF3 + PF4\n  DataAnalysis   =~ DA1 + DA2 + DA3 + DA4\n  Communication  =~ RC1 + RC2 + RC3 + RC4\n'\nfit <- cfa(model, data = d, estimator = \"MLR\")\nsummary(fit, fit.measures = TRUE, standardized = TRUE)\nreliability(fit)          # composite reliability (omega) and AVE\nhtmt(model, data = d)     # discriminant validity"},{"label":"CFA in Python (semopy)","lang":"Python","src":"import semopy\ndesc = \"\"\"\nProblemFraming =~ PF1 + PF2 + PF3 + PF4\nDataAnalysis   =~ DA1 + DA2 + DA3 + DA4\nCommunication  =~ RC1 + RC2 + RC3 + RC4\n\"\"\"\nm = semopy.Model(desc); m.fit(d)\nprint(m.inspect(std_est=True))\nprint(semopy.calc_stats(m).T)   # chi2, CFI, TLI, RMSEA"}]},{"title":"Reliability and validity: putting it together","body":["Report Cronbach's alpha and composite reliability for each factor, loadings with their significance, CR and AVE in one table, and a Fornell–Larcker or HTMT table for discriminant validity.","If AVE is below .50 but CR is above .60, convergent validity can still be considered adequate (Fornell & Larcker, 1981) — state this explicitly. Never delete items only to improve fit without considering what the item measures; content validity matters as much as numbers."]}],"karnataka":[{"title":"EFA of the research self-efficacy scale","text":["Illustrative results from 220 DIET lecturers and CRPs on the 12-item scale: KMO = .85, Bartlett's χ²(66) = 1121, p < .001. Three factors have eigenvalues above 1 (4.47, 1.99, 1.72) and together account for about 68% of the total variance (initial eigenvalues; about 58% after principal axis extraction). After rotation, the four problem-framing, four data-analysis and four communication items each load on their own factor. Run this yourself in the EFA tool."]},{"title":"CFA on a second sample","text":["A second, independent sample of 240 teachers from Kalaburagi and Raichur is used for CFA. Illustrative standardised loadings range from .68 to .86. CR is above .80 and AVE above .55 for all three factors, and each √AVE exceeds the correlations between factors, supporting discriminant validity. The scale can now be used in the SEM in Chapter 16."]}],"activity":{"title":"Run an EFA and assess the measurement model","prompt":"Run the EFA tool on the sample data with three factors. Name each factor and decide whether any item should be dropped. Then enter loadings and factor correlations in the CFA calculator and judge reliability and validity.","tool":"efa"},"tools":["efa","cfa","screen"],"quiz":[{"q":"KMO = .52 for your data means…","options":["Excellent suitability","Barely suitable; consider more data or removing weak items","The model fits","Reliability is high"],"answer":1,"why":"Values below .60 indicate poor sampling adequacy."},{"q":"When factors are expected to correlate, use…","options":["Varimax","An oblique rotation such as promax or oblimin","No rotation","Bartlett's test"],"answer":1,"why":"Oblique rotations allow factors to correlate."},{"q":"AVE = .58 and CR = .84 indicate…","options":["Poor reliability","Adequate convergent validity and reliability","Discriminant validity failure","Overfitting"],"answer":1,"why":"AVE ≥ .50 and CR ≥ .70 are the usual thresholds."},{"q":"Why run CFA on a different sample from the EFA?","options":["To save time","To confirm the structure rather than re-describe the same data","Because AMOS needs it","To increase alpha"],"answer":1,"why":"Using the same data capitalises on chance."}]},{"id":"m16","no":16,"hours":4,"part":2,"title":"Structural Equation Modelling (SEM)","titleKn":"ರಚನಾತ್ಮಕ ಸಮೀಕರಣ ಮಾದರೀಕರಣ (SEM)","objectives":["Explain latent and observed variables, measurement and structural models.","Draw and estimate a structural path model in AMOS or lavaan.","Assess model fit and validate the model responsibly.","Test mediation, moderation and group differences (multi-group SEM)."],"lessons":[{"title":"Understanding SEM and building path models","body":["SEM tests a network of relationships among constructs while accounting for measurement error. It combines a measurement model (CFA: constructs and their items) and a structural model (paths between constructs). Exogenous constructs have no arrows pointing to them; endogenous constructs are predicted by others.","Use the two-step approach (Anderson & Gerbing, 1988): first establish a good measurement model (Chapter 15), then add the structural paths. Every path needs a theoretical reason. Sample size: 200 or more is a common minimum, more for complex models; aim for at least 10 cases per estimated parameter where possible.","Covariance-based SEM (AMOS, lavaan) tests theory and gives fit indices. Partial least squares SEM (for example SmartPLS) suits prediction, small samples and formative constructs, but does not test overall model fit in the same way. Choose by aim, not by convenience.","In AMOS: start from the validated CFA diagram, replace covariances between constructs with single-headed arrows where the theory predicts an effect, add a residual (disturbance) to every endogenous construct, and estimate with maximum likelihood. Report standardised path coefficients (β), their significance, and R² for each endogenous construct."],"code":[{"label":"Structural model in R (lavaan)","lang":"R","src":"model <- '\n  # measurement model\n  Support     =~ S1 + S2 + S3\n  Efficacy    =~ PF1 + PF2 + DA1 + DA2\n  Engagement  =~ E1 + E2 + E3\n  # structural model\n  Efficacy   ~ a * Support\n  Engagement ~ b * Efficacy + c * Support\n  indirect := a * b\n  total    := c + a * b\n'\nfit <- sem(model, data = d, estimator = \"ML\", se = \"bootstrap\", bootstrap = 5000)\nsummary(fit, fit.measures = TRUE, standardized = TRUE, rsquare = TRUE)\nparameterEstimates(fit, boot.ci.type = \"perc\", standardized = TRUE)"}]},{"title":"Model fit, assessment and validation","body":["Report several fit indices together: χ² with df and p (sensitive to large samples, so not used alone), χ²/df (≤ 3 good), CFI and TLI (≥ .95 good, ≥ .90 acceptable), RMSEA with its 90% confidence interval (≤ .06 good, ≤ .08 acceptable) and SRMR (≤ .08). These are guidelines (Hu & Bentler, 1999), not laws.","Modification indices suggest changes that would improve fit. Accept only changes with a clear theoretical reason (for example, correlated errors between two items with near-identical wording), make them one at a time, and report every change. A model modified to fit one sample must be cross-validated on another.","Validate by comparing the model with plausible alternatives (for example, with and without a direct path), checking that estimates are sensible (no negative error variances, standardised values within ±1), and testing on a hold-out sample."]},{"title":"Advanced applications","body":["Mediation: an indirect effect (a × b) shows that X affects Y through M. Test it with bootstrapped confidence intervals (5,000 resamples); if the 95% interval excludes zero, the indirect effect is significant. Report the direct, indirect and total effects. In AMOS: Analysis Properties → Bootstrap → Perform bootstrap (5000), Bias-corrected confidence intervals; request Indirect, direct and total effects.","Moderation: the effect of X on Y depends on W. With observed variables, add an X × W interaction (mean-centred); with latent variables use latent interaction methods or multi-group analysis.","Multi-group SEM: compare groups such as Kalyana Karnataka and other districts, or men and women teachers. First test measurement invariance in steps — configural (same structure), metric (equal loadings), scalar (equal intercepts) — accepting each step if CFI drops by no more than .01. Only then compare paths or means across groups.","Higher-order models represent a general factor above first-order factors (for example, overall research self-efficacy above its three dimensions)."]}],"karnataka":[{"title":"Does DIET support build research engagement?","text":["Illustrative model with 260 teachers: DIET support (mentoring, workshops, feedback) → research self-efficacy → research engagement (action research projects, presentations at cluster meetings). Fit: χ²(87) = 141.6, χ²/df = 1.63, CFI = .97, TLI = .96, RMSEA = .049, SRMR = .046. Support → self-efficacy β = .48; self-efficacy → engagement β = .44; the direct path from support to engagement is small (β = .12). The bootstrapped indirect effect is significant, suggesting that DIET support works mainly by building teachers' confidence."]},{"title":"Comparing regions with multi-group SEM","text":["The same model is tested separately for Kalyana Karnataka districts and other districts. Configural and metric invariance hold (ΔCFI < .01), so the paths can be compared. If the support → self-efficacy path is stronger in Kalyana Karnataka, the DIET can argue for prioritising mentoring there."]}],"activity":{"title":"Assess fit and test mediation","prompt":"Enter the fit indices from the worked example (or your own output) in the fit checker and copy the generated sentence. Then run the mediation tool on the sample data and report the indirect effect with its confidence interval.","tool":"fit"},"tools":["fit","mediation","cfa"],"quiz":[{"q":"In the two-step approach you first…","options":["Add all structural paths","Validate the measurement model","Run multi-group analysis","Delete items with low loadings"],"answer":1,"why":"A sound measurement model comes before structural paths."},{"q":"CFI = .96, RMSEA = .05, SRMR = .04 indicate…","options":["Poor fit","Good fit","Overfitting only","Nothing without χ²"],"answer":1,"why":"All three meet commonly used good-fit guidelines."},{"q":"A mediation effect is supported when…","options":["The direct path is zero","The bootstrapped 95% CI of a × b excludes zero","R² is above .50","χ² is non-significant"],"answer":1,"why":"The indirect effect is tested with bootstrapped intervals."},{"q":"Before comparing paths across two groups you must establish…","options":["Equal sample sizes","Measurement invariance (at least metric)","Identical means","A higher-order factor"],"answer":1,"why":"Constructs must be measured the same way in both groups."}]},{"id":"m17","no":17,"hours":4,"part":2,"title":"Academic Writing, Publication and AI-Enabled Research","titleKn":"ಶೈಕ್ಷಣಿಕ ಬರವಣಿಗೆ, ಪ್ರಕಟಣೆ ಮತ್ತು ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಆಧಾರಿತ ಸಂಶೋಧನೆ","objectives":["Report EFA, CFA and SEM results to journal standard.","Choose a suitable journal, respond to reviewers and avoid predatory outlets.","Use generative and agentic AI tools responsibly across the research process.","Recognise opportunities and risks of big data and interdisciplinary research in education."],"lessons":[{"title":"From findings to a publishable manuscript","body":["Most empirical articles follow IMRaD: Introduction (problem, gap, aim), Method (participants, instruments, procedure, ethics, analysis), Results, and Discussion (meaning, comparison with earlier studies, implications, limitations, future research). Write the methods so another researcher could repeat the study.","What to report for multivariate analysis: software and version; estimator; how missing data were handled; KMO, Bartlett, extraction, rotation and loadings for EFA; a CFA table with loadings, CR, AVE and discriminant validity; fit indices with RMSEA confidence interval; standardised path coefficients with standard errors, p-values and confidence intervals; R²; and indirect effects with bootstrapped intervals. A clear path diagram with standardised estimates helps readers.","In the discussion, interpret effect sizes in practical terms (\"a one standard deviation increase in DIET support is associated with…\"), separate association from causation in cross-sectional data, and link recommendations to specific findings."]},{"title":"Publishing: choosing journals and working with reviewers","body":["Choose a journal by fit of scope, audience, indexing (Scopus, Web of Science, UGC-CARE list), review time and cost. Read recent issues and author guidelines. Check for cloned or predatory journals: verify the journal's website from the indexing database itself, be wary of guaranteed acceptance or very fast review, and do not pay fees before a genuine peer review.","Write a short cover letter stating the contribution and why it suits the journal. Treat reviewer comments as free expert advice: reply point by point in a table, say what you changed and where, and explain politely when you disagree with evidence.","Strengthen visibility and integrity with an ORCID iD, sharing data and code where ethics allow, preprints where the journal permits, and open-access options such as institutional repositories."]},{"title":"AI-enabled research: from generative to agentic AI","body":["Generative AI (chat assistants such as ChatGPT, Claude or Gemini) can draft text, summarise papers you supply, suggest code for R or Python, explain statistical output, and support first-pass coding of qualitative data. Agentic AI goes further: agents plan multi-step tasks, search sources, run code and revise their own work, with the researcher supervising.","Opportunities: faster literature mapping, reproducible analysis scripts, translation support for bilingual instruments, accessibility. Risks: fabricated facts and citations, hidden bias, loss of the researcher's own judgement, privacy breaches, and over-reliance on outputs nobody has checked. Agents that act on their own need clear limits, logs and human approval of every important step.","A responsible-use routine: decide what the tool may and may not do; never upload personal data; verify every fact, citation and number at the source; keep prompts and outputs as part of the audit trail; disclose use in the paper; and keep the interpretation and conclusions your own.","Big data and interdisciplinary research: large administrative datasets (UDISE+, SATS aggregates, assessment portals, learning-app logs) allow population-level analysis and learning analytics, but need permission, de-identification and care under India's Digital Personal Data Protection Act, 2023. Many education questions — nutrition and learning, migration and dropout, technology and equity — are best studied with colleagues from public health, economics, data science and sociology."]}],"karnataka":[{"title":"A results paragraph for the self-efficacy CFA","text":["\"A three-factor CFA (maximum likelihood, AMOS; N = 240) showed good fit, χ²(51) = 85.2, p = .002, CFI = .97, TLI = .96, RMSEA = .053 [90% CI .031, .073], SRMR = .045. All standardised loadings were significant (.68–.86). Composite reliability ranged from .82 to .88 and AVE from .55 to .64; the square root of each AVE exceeded the inter-factor correlations (.41–.58), supporting discriminant validity.\" (Illustrative values.)"]},{"title":"Big data with care: SATS aggregates","text":["A DIET wants to study whether attendance patterns predict Grade 7 LBA scores across 1,200 schools. It requests school-level aggregates rather than child-level records, works on a departmental computer, documents its code, and uses an AI assistant only to help write and debug the analysis script on dummy data — never on the real file. The policy brief reports patterns by block, not by individual school, to avoid naming small schools."]}],"activity":{"title":"Write it up and plan responsible AI use","prompt":"Using your fit checker or CFA calculator output, write a results paragraph in APA style. Then complete the responsible AI checklist in the AI prompt planner and download your AI-use disclosure statement for your next paper.","tool":"aiprompt"},"tools":["aiprompt","fit","literature","proposal"],"quiz":[{"q":"Which belongs in the Method section of a SEM paper?","options":["Only the hypotheses","Estimator, software, missing-data handling and fit criteria","Implications for policy","The cover letter"],"answer":1,"why":"Method reports how the analysis was done so others can repeat it."},{"q":"A journal promises acceptance within 72 hours for a fee. You should…","options":["Submit quickly","Treat it as a likely predatory journal and verify it through indexing databases","Pay first and ask later","Cite it in your review"],"answer":1,"why":"Guaranteed fast acceptance is a common sign of predatory practice."},{"q":"What distinguishes agentic AI from a basic chat assistant?","options":["It cannot use tools","It plans and carries out multi-step tasks such as searching and running code","It never makes errors","It can be listed as an author"],"answer":1,"why":"Agents act over several steps, so they need limits and human oversight."},{"q":"Under responsible AI use, the researcher should…","options":["Upload SATS data for faster analysis","Verify every AI-supplied fact and disclose AI use","Let the AI write the conclusions","Hide AI use"],"answer":1,"why":"Verification and disclosure protect integrity."}]}],"ADVANCED_KN":{"m13":{"objectives":["ಸಂಶೋಧನಾ ಅಂತರವನ್ನು (research gap) ನಿಖರವಾಗಿ ಗುರುತಿಸಿ ಹೇಳುವುದು.","ಸಮಸ್ಯೆ, ಪ್ರಶ್ನೆಗಳು, ಉದ್ದೇಶಗಳು, ಊಹೆಗಳು, ವಿನ್ಯಾಸ ಮತ್ತು ವಿಶ್ಲೇಷಣೆಯನ್ನು ಒಂದೇ ಕೋಷ್ಟಕದಲ್ಲಿ ಹೊಂದಿಸುವುದು.","ಪರಿಕಲ್ಪನಾ ಚೌಕಟ್ಟಿನೊಂದಿಗೆ (conceptual framework) ಪರಿಶೀಲನೆಗೆ ಯೋಗ್ಯವಾದ ಸಂಶೋಧನಾ ಪ್ರಸ್ತಾವನೆ ರಚಿಸುವುದು.","ಪ್ರಾಮಾಣಿಕತೆ ಮತ್ತು ದತ್ತಾಂಶ ಸುರಕ್ಷತೆ ಕಾಪಾಡುತ್ತಾ ಪ್ರಸ್ತಾವನೆ ರಚನೆಗೆ ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ (AI) ಸಾಧನಗಳನ್ನು ಬಳಸುವುದು."],"lessons":[{"title":"ಸಂಶೋಧನಾ ಅಂತರದಿಂದ ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆಗಳವರೆಗೆ","body":["ಅಂತರ ಎಂದರೆ ಲಭ್ಯ ಪುರಾವೆ ಇನ್ನೂ ತಿಳಿಸದಿರುವ ವಿಷಯ. ಆರು ಸಾಮಾನ್ಯ ಪ್ರಕಾರಗಳು: ಪುರಾವೆ ಅಂತರ (ಫಲಿತಾಂಶಗಳು ಒಂದಕ್ಕೊಂದು ಹೊಂದುವುದಿಲ್ಲ), ಜ್ಞಾನ ಅಂತರ (ವಿಷಯ ಅಧ್ಯಯನವಾಗಿಲ್ಲ), ವ್ಯಾವಹಾರಿಕ ಅಂತರ (ಅಭ್ಯಾಸದಲ್ಲಿ ಯಶಸ್ವಿಯಾದುದು ದಾಖಲಾಗಿಲ್ಲ), ವಿಧಾನ ಅಂತರ (ಹಿಂದಿನ ಅಧ್ಯಯನಗಳ ವಿನ್ಯಾಸ ಅಥವಾ ಸಾಧನಗಳು ದುರ್ಬಲ), ಜನಸಂಖ್ಯಾ ಅಂತರ (ಒಂದು ಗುಂಪು ಅಥವಾ ಸ್ಥಳಕ್ಕೆ ಅಧ್ಯಯನವಾಗಿಲ್ಲ), ಮತ್ತು ಸೈದ್ಧಾಂತಿಕ ಅಂತರ (ಮಾದರಿಯನ್ನು ವಿವರಿಸುವ ಚೌಕಟ್ಟು ಇಲ್ಲ).","ಅಂತರವನ್ನು ಒಂದೇ ವಾಕ್ಯದಲ್ಲಿ ಬರೆಯಿರಿ: \"[ತಿಳಿದಿರುವುದು] ಇದ್ದರೂ, [ಜನಸಂಖ್ಯೆ, ಸ್ಥಳ]ಕ್ಕೆ [ತಿಳಿಯದಿರುವುದು] ಇನ್ನೂ ತಿಳಿದಿಲ್ಲ, ಏಕೆಂದರೆ [ಹಿಂದಿನ ಅಧ್ಯಯನಗಳ ಕೊರತೆ].\" ಪ್ರಶ್ನೆಯನ್ನು FINER ಮೂಲಕ ಪರೀಕ್ಷಿಸಿ: ಕಾರ್ಯಸಾಧ್ಯ, ಆಸಕ್ತಿದಾಯಕ, ನವೀನ, ನೈತಿಕ, ಪ್ರಸ್ತುತ.","ಹೊಂದಾಣಿಕೆ (alignment) ಉತ್ತಮ ಪ್ರಸ್ತಾವನೆಯ ಬೆನ್ನೆಲುಬು. ಪ್ರತಿ ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆಗೆ ಹೊಂದುವ ಉದ್ದೇಶ, ಅಗತ್ಯವಿದ್ದಲ್ಲಿ ಊಹೆ, ದತ್ತಾಂಶ ಮೂಲ ಅಥವಾ ಸಾಧನ, ಮತ್ತು ವಿಶ್ಲೇಷಣೆ ಇರಬೇಕು. ವಿಶ್ಲೇಷಣೆಯಿಲ್ಲದ ಪ್ರಶ್ನೆ ಅಥವಾ ಯಾವ ಪ್ರಶ್ನೆಗೂ ಉತ್ತರಿಸದ ವಿಶ್ಲೇಷಣೆ ಇದ್ದರೆ ಪ್ರಸ್ತಾವನೆ ಹೊಂದಾಣಿಕೆಯಲ್ಲಿಲ್ಲ."]},{"title":"ವಿನ್ಯಾಸ ಆಯ್ಕೆ ಮತ್ತು ಪ್ರಸ್ತಾವನೆಯ ರಚನೆ","body":["ವಿನ್ಯಾಸವನ್ನು ಅಭ್ಯಾಸದಿಂದಲ್ಲ, ಪ್ರಶ್ನೆಯಿಂದ ಆರಿಸಿ: ವರ್ಣನೆ → ಸಮೀಕ್ಷೆ; ಸಂಬಂಧ → ಸಹಸಂಬಂಧ ಅಥವಾ SEM; ಈಗಿರುವ ಗುಂಪುಗಳ ಹೋಲಿಕೆ → ಕಾರಣ-ತುಲನಾತ್ಮಕ; ಮಧ್ಯಪ್ರವೇಶದ ಪರೀಕ್ಷೆ → ಪ್ರಾಯೋಗಿಕ ಅಥವಾ ಅರೆ-ಪ್ರಾಯೋಗಿಕ; ಅರ್ಥಗಳ ಗ್ರಹಿಕೆ → ಗುಣಾತ್ಮಕ; ಅಂಕಿಗಳ ವಿವರಣೆ → ವಿವರಣಾತ್ಮಕ ಅನುಕ್ರಮ ಮಿಶ್ರ ವಿಧಾನ.","ಪರಿಕಲ್ಪನಾ ಚೌಕಟ್ಟು ಎಂದರೆ ಅಧ್ಯಯನ ಪರೀಕ್ಷಿಸುವ ರಚನೆಗಳು (constructs) ಮತ್ತು ಸಂಬಂಧಗಳ ರೇಖಾಚಿತ್ರ; ಪ್ರತಿ ಬಾಣಕ್ಕೆ ಸಿದ್ಧಾಂತ ಅಥವಾ ಹಿಂದಿನ ಪುರಾವೆಯ ಬೆಂಬಲವಿರಬೇಕು. ಇದೇ ಅಧ್ಯಾಯ 15 ಮತ್ತು 16ರಲ್ಲಿ ಮಾಪನ ಮಾದರಿ (ರಚನೆಗಳು ಮತ್ತು ಅಂಶಗಳು) ಹಾಗೂ ರಚನಾತ್ಮಕ ಮಾದರಿ (ಮಾರ್ಗಗಳು) ಆಗುತ್ತದೆ.","ಪರಿಶೀಲಕರು ಹೆಚ್ಚಾಗಿ ತಿರಸ್ಕರಿಸುವ ಕಾರಣಗಳು: ಅಸ್ಪಷ್ಟ ಸಮಸ್ಯೆ, ಸಮರ್ಥನೆಯಿಲ್ಲದ ಮಾದರಿ ಗಾತ್ರ, ವಿಶ್ವಸನೀಯತೆ ಅಥವಾ ಸಿಂಧುತ್ವದ ಪುರಾವೆಯಿಲ್ಲದ ಸಾಧನಗಳು, ಪ್ರಶ್ನೆಗಳಿಗೆ ಹೊಂದದ ವಿಶ್ಲೇಷಣೆ, ನೈತಿಕ ಅಂಶಗಳ ಕೊರತೆ ಮತ್ತು ಅವಾಸ್ತವಿಕ ಕಾಲಮಿತಿ."]},{"title":"ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆಯ ನೆರವಿನೊಂದಿಗೆ ಪ್ರಸ್ತಾವನೆ ರಚನೆ","body":["AI ಸಾಧನಗಳು ಹಲವು ಹಂತಗಳಲ್ಲಿ ನೆರವಾಗಬಹುದು: ಸಾಹಿತ್ಯ ಶೋಧ (Semantic Scholar, Elicit, Consensus, Research Rabbit, Connected Papers), ಉಲ್ಲೇಖ ನಿರ್ವಹಣೆ (Zotero), ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆಗಳ ಚಿಂತನ ಮಂಥನ, ಅವಲೋಕನದ ರೂಪರೇಖೆ, ಭಾಷೆಯ ಸ್ಪಷ್ಟತೆ ಸುಧಾರಣೆ ಮತ್ತು ಸಾಂಖ್ಯಿಕ ಕ್ರಮಗಳು ಅಥವಾ ಕೋಡ್‌ನ ವಿವರಣೆ.","AI ಸಾಧನಗಳು ಉಲ್ಲೇಖಗಳನ್ನು ಕಲ್ಪಿಸಬಹುದು, ಫಲಿತಾಂಶಗಳನ್ನು ತಪ್ಪಾಗಿ ಹೇಳಬಹುದು ಮತ್ತು ತಪ್ಪುಗಳನ್ನು ಆತ್ಮವಿಶ್ವಾಸದಿಂದ ಹೇಳಬಹುದು. AI ಸೂಚಿಸುವ ಪ್ರತಿ ಉಲ್ಲೇಖವನ್ನು ಮೂಲದಲ್ಲಿ ತೆರೆದು ಪರಿಶೀಲಿಸಲೇಬೇಕು. ಗುರುತಿಸಬಹುದಾದ ದತ್ತಾಂಶವನ್ನು — SATS ದಾಖಲೆಗಳು, ಹೆಸರುಗಳು, ದೂರವಾಣಿ ಸಂಖ್ಯೆಗಳು, ಪ್ರಕಟವಾಗದ ಸಂದರ್ಶನ ಪ್ರತಿಲಿಪಿಗಳು — ಸಾರ್ವಜನಿಕ AI ಸಾಧನಕ್ಕೆ ಎಂದಿಗೂ ಹಾಕಬೇಡಿ.","ಪ್ರಾಮಾಣಿಕತೆಯ ನಿಯಮಗಳು: AI ಸಾಧನ ಲೇಖಕನಾಗಲಾರದು, ಏಕೆಂದರೆ ಅದು ಕೆಲಸದ ಹೊಣೆ ಹೊರಲಾರದು (COPE ನಿಲುವು ಹೇಳಿಕೆ, 2023). ಬಹುತೇಕ ನಿಯತಕಾಲಿಕಗಳು ಈಗ ಕೇಳುವಂತೆ, ಸಾಧನ, ಆವೃತ್ತಿ ಮತ್ತು ಉದ್ದೇಶವನ್ನು ವಿಧಾನ ಅಥವಾ ಕೃತಜ್ಞತೆ ವಿಭಾಗದಲ್ಲಿ ಘೋಷಿಸಿ. ಪ್ರತಿ ವಾಕ್ಯ ಮತ್ತು ಅಂಕಿಗೆ ಸಂಶೋಧಕರೇ ಹೊಣೆಗಾರರು."]}],"karnataka":[{"title":"ಸೇತುಬಂಧ ಅಧ್ಯಯನಕ್ಕೆ ಹೊಂದಾಣಿಕೆ ಕೋಷ್ಟಕ","text":["ಅಂತರ: \"ಸೇತುಬಂಧ ಪ್ರತಿವರ್ಷದ ಆರಂಭದಲ್ಲಿ ನಡೆದರೂ, ಕಲ್ಯಾಣ ಕರ್ನಾಟಕದಲ್ಲಿ 4ನೇ ತರಗತಿಯ ಲಾಭಗಳು 5ನೇ ತರಗತಿಯ ಕೊನೆಯವರೆಗೆ ಉಳಿಯುತ್ತವೆಯೇ ಎಂದು ಯಾವ ಜಿಲ್ಲಾ ಅಧ್ಯಯನವೂ ಅನುಸರಿಸಿಲ್ಲ.\" ಸಂ.ಪ್ರ.1: ಜೂನ್ (4ನೇ ತರಗತಿ) ಯಿಂದ ಮಾರ್ಚ್ (5ನೇ ತರಗತಿ) ವರೆಗೆ ಕನ್ನಡ ಓದಿನ ಅಂಕಗಳಲ್ಲಿ ಬದಲಾವಣೆ ಏನು? → ಉದ್ದೇಶ: ಲಾಭಗಳ ಉಳಿಕೆಯನ್ನು ಅಂದಾಜಿಸುವುದು → ಊಹೆ 1: 5ನೇ ತರಗತಿಯ ಕೊನೆಯ ಅಂಕಗಳು ಜೂನ್ ಮೂಲರೇಖೆಗಿಂತ ಮೇಲಿರುತ್ತವೆ → ದತ್ತಾಂಶ: LBA ಓದಿನ ಅಂಕಗಳು ಮತ್ತು ಶ್ರೇಣೀಕೃತ ಓದಿನ ಪರೀಕ್ಷೆ → ವಿಶ್ಲೇಷಣೆ: ಜೋಡಿ t-ಪರೀಕ್ಷೆ ಮತ್ತು ಪರಿಣಾಮ ಗಾತ್ರ.","ಸಂ.ಪ್ರ.2: ಉಳಿಕೆಗೆ ಯಾವ ಶಾಲಾ ಅಂಶಗಳು ಸಂಬಂಧಿಸಿವೆ? → ದತ್ತಾಂಶ: ಗ್ರಂಥಾಲಯ ಅವಧಿ, ಶಿಕ್ಷಕರ ಖಾಲಿ ಹುದ್ದೆಗಳು ಮತ್ತು ಹಾಜರಾತಿ ಕುರಿತು ಮುಖ್ಯ ಶಿಕ್ಷಕರ ಸಮೀಕ್ಷೆ → ವಿಶ್ಲೇಷಣೆ: ಬಹು ಹಿಂಚಲನೆ (multiple regression) ಅಥವಾ ಅಧ್ಯಾಯ 16ರ SEM."]},{"title":"ಅವಲೋಕನದ ರೂಪರೇಖೆಗೆ AI ಸಹಾಯಕನ ಸುರಕ್ಷಿತ ಬಳಕೆ","text":["ಒಬ್ಬ ಡಯಟ್ ಉಪನ್ಯಾಸಕಿ AI ಸಹಾಯಕನನ್ನು ಕೇಳುತ್ತಾರೆ: \"ಭಾರತದ ಸರ್ಕಾರಿ ಪ್ರಾಥಮಿಕ ಶಾಲೆಗಳಲ್ಲಿ ಬಹುವರ್ಗ ಬೋಧನೆ ಕುರಿತ ಸಾಹಿತ್ಯ ಅವಲೋಕನಕ್ಕೆ ಶೀರ್ಷಿಕೆಗಳು ಮತ್ತು ಹುಡುಕಬೇಕಾದ ಅಧ್ಯಯನಗಳ ಬಗೆಯೊಂದಿಗೆ ರೂಪರೇಖೆ ಸೂಚಿಸಿ. ಉಲ್ಲೇಖಗಳನ್ನು ಕಲ್ಪಿಸಬೇಡಿ.\" ನಂತರ ಅವರು ಪ್ರತಿ ಶೀರ್ಷಿಕೆಗೆ ಶೋಧಗಂಗಾ, ERIC ಮತ್ತು ಡಿಎಸ್‌ಇಆರ್‌ಟಿ ಸಂಗ್ರಹಗಳಲ್ಲಿ ತಾವೇ ಹುಡುಕುತ್ತಾರೆ, ತಾವು ತೆರೆದು ಓದಿದ ಅಧ್ಯಯನಗಳನ್ನು ಮಾತ್ರ ಉಳಿಸುತ್ತಾರೆ, ಮತ್ತು ಯಾವ ಸಾಧನವನ್ನು ಯಾವುದಕ್ಕೆ ಬಳಸಿದರು ಎಂದು ವಿಧಾನ ಟಿಪ್ಪಣಿಯಲ್ಲಿ ದಾಖಲಿಸುತ್ತಾರೆ."]}],"activity":{"title":"ನಿಮ್ಮ ಹೊಂದಾಣಿಕೆ ಕೋಷ್ಟಕ ರಚಿಸಿ","prompt":"ಹೊಂದಾಣಿಕೆ ಕೋಷ್ಟಕ ಬಳಸಿ ಪ್ರತಿ ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆಯನ್ನು ಉದ್ದೇಶ, ಊಹೆ, ದತ್ತಾಂಶ ಮೂಲ ಮತ್ತು ವಿಶ್ಲೇಷಣೆಗೆ ಜೋಡಿಸಿ. ನಂತರ AI ಪ್ರಾಂಪ್ಟ್ ಯೋಜಕ ಬಳಸಿ ಸಾಹಿತ್ಯ ಶೋಧಕ್ಕೆ ಒಂದು ಸುರಕ್ಷಿತ ಪ್ರಾಂಪ್ಟ್ ರಚಿಸಿ ಮತ್ತು ನಿಮ್ಮ AI ಬಳಕೆ ಘೋಷಣೆ ಬರೆಯಿರಿ."},"quiz":[{"q":"\"LBA ಕುರಿತ ಹಿಂದಿನ ಅಧ್ಯಯನಗಳು ಮೂಲರೇಖೆ ಇಲ್ಲದೆ ಉತ್ತರ-ಪರೀಕ್ಷೆಗಳನ್ನು ಮಾತ್ರ ಬಳಸಿದವು.\" ಇದು ಮುಖ್ಯವಾಗಿ…","options":["ಜನಸಂಖ್ಯಾ ಅಂತರ","ವಿಧಾನ ಅಂತರ","ಸೈದ್ಧಾಂತಿಕ ಅಂತರ","ವ್ಯಾವಹಾರಿಕ ಅಂತರ"],"why":"ದೌರ್ಬಲ್ಯ ಹಿಂದಿನ ಅಧ್ಯಯನಗಳ ವಿನ್ಯಾಸದಲ್ಲಿದೆ."},{"q":"AI ಸಹಾಯಕ ನಿಮಗೆ ಐದು ಉಲ್ಲೇಖಗಳನ್ನು ನೀಡುತ್ತದೆ. ನೀವು ಏನು ಮಾಡಬೇಕು?","options":["ಹಾಗೆಯೇ ಉಲ್ಲೇಖಿಸಿ","ಉಲ್ಲೇಖಿಸುವ ಮೊದಲು ಪ್ರತಿಯೊಂದನ್ನೂ ಮೂಲದಲ್ಲಿ ತೆರೆದು ಪರಿಶೀಲಿಸಿ","AI ಅನ್ನು ಸಹ-ಲೇಖಕರನ್ನಾಗಿ ಸೇರಿಸಿ","ಮೊದಲನೆಯದನ್ನು ಮಾತ್ರ ಉಲ್ಲೇಖಿಸಿ"],"why":"AI ಸಾಧನಗಳು ಉಲ್ಲೇಖಗಳನ್ನು ಕಲ್ಪಿಸಬಹುದು ಅಥವಾ ತಪ್ಪಾಗಿ ಹೇಳಬಹುದು."},{"q":"ಸಾರ್ವಜನಿಕ AI ಸಾಧನಕ್ಕೆ ಯಾವುದನ್ನು ಹಾಕಬಹುದು?","options":["SATS ಸಂಖ್ಯೆ ಮತ್ತು ಅಂಕಗಳ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್","ಹೆಸರುಗಳಿರುವ ಪ್ರಕಟವಾಗದ ಸಂದರ್ಶನ ಪ್ರತಿಲಿಪಿಗಳು","ವೈಯಕ್ತಿಕ ದತ್ತಾಂಶವಿಲ್ಲದ ನಿಮ್ಮದೇ ಕರಡು ಪರಿಚ್ಛೇದ","ಪೋಷಕರ ದೂರವಾಣಿ ಸಂಖ್ಯೆಗಳು"],"why":"ಗುರುತಿಸಬಹುದಾದ ಅಥವಾ ಗೌಪ್ಯ ದತ್ತಾಂಶವನ್ನು ಎಂದಿಗೂ ಹಂಚಬಾರದು."},{"q":"ಹೊಂದಾಣಿಕೆ ಕೋಷ್ಟಕದಲ್ಲಿ ಯಾವ ಪ್ರಶ್ನೆಗೂ ಉತ್ತರಿಸದ ವಿಶ್ಲೇಷಣೆ ತೋರಿಸುವುದು…","options":["ಸಂಪೂರ್ಣತೆ","ತೆಗೆಯಬೇಕಾದ ಅಥವಾ ಸಮರ್ಥಿಸಬೇಕಾದ ಹೊಂದಾಣಿಕೆಯ ಕೊರತೆ","ಬಲವಾದ ವಿನ್ಯಾಸ","ಮಿಶ್ರ ವಿಧಾನ"],"why":"ಪ್ರತಿ ವಿಶ್ಲೇಷಣೆ ಒಂದು ನಿರ್ದಿಷ್ಟ ಪ್ರಶ್ನೆಗೆ ಉತ್ತರಿಸಬೇಕು."}]},"m14":{"objectives":["ಮಾಪನ ಮಟ್ಟಗಳನ್ನು ಮತ್ತು ಪ್ರತಿಫಲಿತ (reflective) ಹಾಗೂ ರೂಪಾತ್ಮಕ (formative) ರಚನೆಗಳನ್ನು ಪ್ರತ್ಯೇಕಿಸುವುದು.","ಸಮರ್ಪಕ ಮನೋಮಾಪನ ಹಂತಗಳೊಂದಿಗೆ ಲಿಕರ್ಟ್ ಮಾಪಕವನ್ನು ರಚಿಸಿ ಅನುವಾದಿಸುವುದು.","ಪ್ರಶ್ನೆ ಮತ್ತು ದತ್ತಾಂಶದ ಬಗೆಗೆ ಸರಿಯಾದ ಸಾಂಖ್ಯಿಕ ತಂತ್ರವನ್ನು ಆರಿಸುವುದು.","R ಅಥವಾ Pythonನಲ್ಲಿ ದತ್ತಾಂಶವನ್ನು ಪರಿಶೀಲಿಸಿ, ಶುದ್ಧೀಕರಿಸಿ, ಸಿದ್ಧಪಡಿಸುವುದು."],"lessons":[{"title":"ರಚನೆಗಳು, ಮಾಪಕಗಳು ಮತ್ತು ಸಾಧನ ರಚನೆ","body":["ಮಾಪನ ಮಟ್ಟಗಳು ಯಾವ ಅಂಕಿಅಂಶಗಳು ಸಾಧ್ಯ ಎಂದು ನಿರ್ಧರಿಸುತ್ತವೆ: ನಾಮಸೂಚಕ (ಬೋಧನಾ ಮಾಧ್ಯಮ), ಕ್ರಮಸೂಚಕ (ಶ್ರೇಣಿಗಳು, ಒಂದೊಂದು ಲಿಕರ್ಟ್ ಅಂಶ), ಅಂತರ (ಮಾಪಕದ ಒಟ್ಟು ಅಂಕಗಳು, ವ್ಯವಹಾರದಲ್ಲಿ ಅಂತರವೆಂದು ಪರಿಗಣನೆ) ಮತ್ತು ಅನುಪಾತ (ನಿಮಿಷಕ್ಕೆ ಸರಿಯಾಗಿ ಓದಿದ ಪದಗಳು, ಹಾಜರಾತಿ ದಿನಗಳು).","ರಚನೆ ಎಂದರೆ \"ಸಂಶೋಧನಾ ಸ್ವ-ಸಾಮರ್ಥ್ಯ\" ದಂತಹ ನೇರವಾಗಿ ಕಾಣದ ಗುಣ. ಪ್ರತಿಫಲಿತ ರಚನೆಗಳು ತಮ್ಮ ಅಂಶಗಳಿಗೆ ಕಾರಣವಾಗುತ್ತವೆ; ಆದ್ದರಿಂದ ಅಂಶಗಳು ಹೆಚ್ಚು ಸಹಸಂಬಂಧಿಸಿರಬೇಕು ಮತ್ತು ಪರಸ್ಪರ ಬದಲಿಸಬಹುದಾದವು (ಬಹುತೇಕ ಮನೋಭಾವ ಮಾಪಕಗಳು). ರೂಪಾತ್ಮಕ ರಚನೆಗಳು ಸೂಚಕಗಳಿಂದ ರೂಪುಗೊಳ್ಳುತ್ತವೆ — ಗ್ರಂಥಾಲಯ, ಪ್ರಯೋಗಾಲಯ ಮತ್ತು ಶೌಚಾಲಯಗಳಿಂದ ರೂಪಿಸಿದ ಶಾಲಾ ಸೌಲಭ್ಯ ಸೂಚ್ಯಂಕದಂತೆ; ಅವುಗಳ ಸೂಚಕಗಳು ಸಹಸಂಬಂಧಿಸಬೇಕಿಲ್ಲ.","ಮಾಪಕ ರಚನೆಯ ಹಂತಗಳು: ರಚನೆ ಮತ್ತು ಆಯಾಮಗಳ ವ್ಯಾಖ್ಯಾನ → ಅಂಶಗಳ ಸಂಗ್ರಹ (ಅಂತಿಮ ಸಂಖ್ಯೆಯ 3–4 ಪಟ್ಟು) → ವಿಷಯ ಸಿಂಧುತ್ವಕ್ಕೆ ತಜ್ಞರ ಪರಿಶೀಲನೆ (ಅಂಶ ಮಟ್ಟದ CVI ≥ .78) → ಕೆಲವು ಶಿಕ್ಷಕರೊಂದಿಗೆ ಅರಿವಿನ ಸಂದರ್ಶನಗಳು → ಪ್ರಾಯೋಗಿಕ ಪರೀಕ್ಷೆ (n ≥ 100) → ಅಂಶ ವಿಶ್ಲೇಷಣೆ (ತಿದ್ದಿದ ಅಂಶ–ಒಟ್ಟು r ≥ .30) → ಅಂಶ ವಿಶ್ಲೇಷಣೆ (ಅಧ್ಯಾಯ 15). ಚಿಕ್ಕ, ಒಂದೇ ವಿಚಾರದ ಅಂಶಗಳನ್ನು ಬರೆಯಿರಿ; ಎರಡು ವಿಚಾರಗಳ ಮತ್ತು ಪ್ರೇರೇಪಿಸುವ ಅಂಶಗಳನ್ನು ತಪ್ಪಿಸಿ; ಕೆಲವು ವಿರುದ್ಧ ಪದರಚನೆಯ ಅಂಶಗಳನ್ನು ಸೇರಿಸಿ ವಿಶ್ಲೇಷಣೆಗೆ ಮುನ್ನ ಮರುಸಂಕೇತಿಸಿ.","ಕನ್ನಡ ಆವೃತ್ತಿಗಳಿಗೆ ಇಬ್ಬರು ಅನುವಾದಕರಿಂದ ಮುಂದುವರಿದ ಅನುವಾದ, ಹೊಂದಾಣಿಕೆ, ಸ್ವತಂತ್ರ ಅನುವಾದಕರಿಂದ ಹಿಮ್ಮುಖ ಅನುವಾದ (back-translation) ಮತ್ತು ಸಮಿತಿಯ ಪರಿಶೀಲನೆ ಬಳಸಿ; ನಂತರ ಎರಡೂ ಭಾಷಾ ಆವೃತ್ತಿಗಳನ್ನು ಪ್ರಾಯೋಗಿಕವಾಗಿ ಪರೀಕ್ಷಿಸಿ."]},{"title":"ಸಾಂಖ್ಯಿಕ ತಂತ್ರದ ಆಯ್ಕೆ","body":["ನಾಲ್ಕು ಪ್ರಶ್ನೆಗಳಿಂದ ನಿರ್ಧರಿಸಿ: ಗುರಿ ಏನು (ಹೋಲಿಕೆ, ಸಂಬಂಧ, ಮುನ್ಸೂಚನೆ, ರಚನೆಯ ಅನ್ವೇಷಣೆ, ರಚನೆಯ ದೃಢೀಕರಣ, ಮಾದರಿ ಪರೀಕ್ಷೆ)? ಫಲಿತಾಂಶ ಚರಾಂಶದ ಮಟ್ಟ ಯಾವುದು? ಎಷ್ಟು ಗುಂಪುಗಳು, ಅವು ಸ್ವತಂತ್ರವೇ ಜೋಡಿಯೇ? ಪ್ರಾಚಲ (parametric) ಊಹೆಗಳು ಸಮಂಜಸವೇ?","ಸಾಮಾನ್ಯ ಜೋಡಿಗಳು (ಪ್ರಾಚಲ → ಅಪ್ರಾಚಲ): ಸ್ವತಂತ್ರ t-ಪರೀಕ್ಷೆ → Mann–Whitney U; ಜೋಡಿ t-ಪರೀಕ್ಷೆ → Wilcoxon signed-rank; ಏಕಮುಖ ANOVA → Kruskal–Wallis; Pearson r → Spearman ρ. ಮುನ್ಸೂಚನೆಗೆ ಬಹು ಹಿಂಚಲನೆ (ಹೌದು/ಇಲ್ಲ ಫಲಿತಾಂಶಕ್ಕೆ logistic regression). ಮಾಪಕದ ರಚನೆಗೆ EFA, ನಂತರ CFA; ರಚನೆಗಳ ನಡುವಿನ ಸಂಬಂಧಗಳಿಗೆ SEM."]},{"title":"ದತ್ತಾಂಶ ಪರಿಶೀಲನೆ, ಶುದ್ಧೀಕರಣ ಮತ್ತು ಸಿದ್ಧತೆ","body":["ಈ ಕ್ರಮದಲ್ಲಿ ಪರಿಶೀಲಿಸಿ: (1) ವ್ಯಾಪ್ತಿಯ ಹೊರಗಿನ ಮೌಲ್ಯಗಳು ಮತ್ತು ನಮೂದು ದೋಷಗಳು; (2) ಕಾಣೆಯಾದ ದತ್ತಾಂಶ — ಪ್ರಮಾಣ ಮತ್ತು ಮಾದರಿಯನ್ನು ವರ್ಣಿಸಿ; ಶೇ. 5ಕ್ಕಿಂತ ಕಡಿಮೆ ಚದುರಿದ ಕೊರತೆ ಸಾಮಾನ್ಯವಾಗಿ ಹಾನಿಕರವಲ್ಲ, ಇಲ್ಲದಿದ್ದರೆ ಪ್ರಕರಣಗಳನ್ನು ಅಳಿಸುವ ಬದಲು ಬಹು ಆರೋಪಣೆ (multiple imputation) ಅಥವಾ FIML ಬಳಸಿ; (3) ಎಲ್ಲಾ ಅಂಶಗಳಿಗೆ ಒಂದೇ ಉತ್ತರ (straight-lining) ನಂತಹ ನಿರ್ಲಕ್ಷ್ಯದ ಉತ್ತರ; (4) ಹೊರಗಿನ ಮೌಲ್ಯಗಳು (outliers) — ಏಕಚರ |z| > 3.29, ಬಹುಚರ Mahalanobis ಅಂತರದಿಂದ (p < .001); (5) ಸಾಮಾನ್ಯತೆ — ವಕ್ರತೆ ±2 ಮತ್ತು ಹೆಚ್ಚುವರಿ ಕಕುದತೆ ±7 ಒಳಗಿದ್ದರೆ ML ಆಧಾರಿತ SEMಗೆ ಸಾಮಾನ್ಯವಾಗಿ ಸ್ವೀಕಾರಾರ್ಹ; (6) ಬಹುಸಹರೇಖೀಯತೆ — VIF 5ಕ್ಕಿಂತ ಕಡಿಮೆ.","ಒಂದೇ ಸ್ವ-ವರದಿ ಪ್ರಶ್ನಾವಳಿಯಿದ್ದರೆ ಸಾಮಾನ್ಯ ವಿಧಾನ ಪಕ್ಷಪಾತ (common method bias) ಪರಿಶೀಲಿಸಿ: ಒಂದೇ ತಿರುಗಿಸದ ಅಂಶ ಶೇ. 50ಕ್ಕಿಂತ ಹೆಚ್ಚು ವ್ಯತ್ಯಾಸವನ್ನು ವಿವರಿಸಿದರೆ (Harman ಏಕ-ಅಂಶ ಪರೀಕ್ಷೆ) ಸಂಬಂಧಗಳನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ ವ್ಯಾಖ್ಯಾನಿಸಿ. ಇನ್ನೂ ಉತ್ತಮ — ವಿನ್ಯಾಸದಲ್ಲೇ ತಡೆಯಿರಿ: ಪ್ರತ್ಯೇಕ ವಿಭಾಗಗಳು, ಅನಾಮಧೇಯತೆಯ ಭರವಸೆ, ಅಂಶಗಳ ಕ್ರಮದ ಬದಲಾವಣೆ.","ಶುದ್ಧೀಕರಣ ದಾಖಲೆ ಇಡಿ: ಏನು ಬದಲಿಸಲಾಯಿತು, ಏಕೆ, ಎಷ್ಟು ಪ್ರಕರಣಗಳು ಪ್ರಭಾವಿತವಾದವು. ಕಚ್ಚಾ ಕಡತವನ್ನು ಎಂದಿಗೂ ಮೇಲ್ಬರಹ ಮಾಡಬೇಡಿ; ಶುದ್ಧೀಕರಿಸಿದ ಪ್ರತಿಯನ್ನು ಹೊಸ ಹೆಸರಿನಲ್ಲಿ ಉಳಿಸಿ."]}],"karnataka":[{"title":"ಡಯಟ್ ಉಪನ್ಯಾಸಕರಿಗೆ ದ್ವಿಭಾಷಾ ಸಂಶೋಧನಾ ಸ್ವ-ಸಾಮರ್ಥ್ಯ ಮಾಪಕ","text":["ಡಿಎಸ್‌ಇಆರ್‌ಟಿ ಕಾರ್ಯತಂಡವೊಂದು ಡಯಟ್ ಉಪನ್ಯಾಸಕರು ಮತ್ತು ಸಿಆರ್‌ಪಿಗಳಿಗಾಗಿ ಮೂರು ಆಯಾಮಗಳ — ಸಮಸ್ಯೆ ರೂಪಿಸುವಿಕೆ, ದತ್ತಾಂಶ ವಿಶ್ಲೇಷಣೆ ಮತ್ತು ಸಂಶೋಧನಾ ಸಂವಹನ — 36 ಅಂಶಗಳನ್ನು ರಚಿಸುತ್ತದೆ. ಆರು ತಜ್ಞರು ಪ್ರಸ್ತುತತೆಯನ್ನು ಅಳೆಯುತ್ತಾರೆ; I-CVI .78ಕ್ಕಿಂತ ಕಡಿಮೆ ಇರುವ ಅಂಶಗಳನ್ನು ಕೈಬಿಡಲಾಗುತ್ತದೆ. ಉಳಿದ 18 ಅಂಶಗಳನ್ನು ಕನ್ನಡಕ್ಕೆ ಅನುವಾದಿಸಿ ಹಿಮ್ಮುಖ ಅನುವಾದ ಮಾಡಲಾಗುತ್ತದೆ; \"hypothesis\" ಪದಕ್ಕೆ ಕನ್ನಡ ಪದ ಊಹೆ ಜೊತೆಗೆ ಆವರಣದಲ್ಲಿ ಇಂಗ್ಲಿಷ್ ಪದ ಬೇಕು ಎಂದು ಅರಿವಿನ ಸಂದರ್ಶನ ತೋರಿಸುತ್ತದೆ. 120 ಉಪನ್ಯಾಸಕರೊಂದಿಗೆ ಪ್ರಾಯೋಗಿಕ ಪರೀಕ್ಷೆಯ ನಂತರ ಅಂಶ ವಿಶ್ಲೇಷಣೆಗೆ 12 ಅಂಶಗಳನ್ನು ಉಳಿಸಲಾಗುತ್ತದೆ."]},{"title":"ಎಸ್‌ಡಿಎಂಸಿ ಸಮೀಕ್ಷೆಯ ಶುದ್ಧೀಕರಣ","text":["ಬೀದರ್ ಜಿಲ್ಲೆಯ 400 ಎಸ್‌ಡಿಎಂಸಿ ಸದಸ್ಯರ ಉದಾಹರಣಾ ಸಮೀಕ್ಷೆಯಲ್ಲಿ ಆದಾಯ ಪ್ರಶ್ನೆಗೆ ಶೇ. 6 ಉತ್ತರಗಳು ಕಾಣೆಯಾಗಿವೆ; ಇತರ ಅಂಶಗಳಲ್ಲಿ ಶೇ. 2ಕ್ಕಿಂತ ಕಡಿಮೆ. ಸಂಶೋಧಕರು ಮಾದರಿಯನ್ನು ವರದಿ ಮಾಡಿ, ಎಲ್ಲಾ ಪ್ರಕರಣಗಳನ್ನು ಉಳಿಸಿ, 24 ಉತ್ತರದಾತರನ್ನು ಅಳಿಸುವ ಬದಲು ಬಹು ಆರೋಪಣೆ ಬಳಸುತ್ತಾರೆ — ಅವರಲ್ಲಿ ಬಹುತೇಕರು ಮಹಿಳಾ ಸದಸ್ಯರು; ಇಲ್ಲದಿದ್ದರೆ ಅವರ ಅಭಿಪ್ರಾಯಗಳು ಕಡಿಮೆ ಪ್ರತಿನಿಧಿಸಲ್ಪಡುತ್ತಿದ್ದವು."]}],"activity":{"title":"ದತ್ತಾಂಶ ಪರಿಶೀಲಿಸಿ ಮತ್ತು ತಂತ್ರ ಆರಿಸಿ","prompt":"ಪರಿಶೀಲನಾ ಸಾಧನದಲ್ಲಿ ಮಾದರಿ ದತ್ತಾಂಶವನ್ನು ತೆರೆಯಿರಿ. ಕಾಣೆಯಾದ ಮೌಲ್ಯಗಳು, ವ್ಯಾಪ್ತಿ ಮೀರಿದ ನಮೂದು, ಒಂದೇ ಉತ್ತರ ನೀಡಿದವರು ಮತ್ತು ಹೊರಗಿನ ಮೌಲ್ಯಗಳನ್ನು ಗುರುತಿಸಿ, ಪ್ರತಿಯೊಂದಕ್ಕೂ ಏನು ಮಾಡುತ್ತೀರಿ ಎಂದು ಬರೆಯಿರಿ. ನಂತರ ನಿಮ್ಮದೇ ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆಗೆ ತಂತ್ರ ಆಯ್ಕೆಗಾರ ಬಳಸಿ."},"quiz":[{"q":"ಗ್ರಂಥಾಲಯ, ಪ್ರಯೋಗಾಲಯ ಮತ್ತು ಶೌಚಾಲಯಗಳಿಂದ ರೂಪಿಸಿದ ಶಾಲಾ ಸೌಲಭ್ಯ ಸೂಚ್ಯಂಕವನ್ನು ಹೀಗೆ ಪರಿಗಣಿಸುವುದು ಸೂಕ್ತ…","options":["ಪ್ರತಿಫಲಿತ ರಚನೆ","ರೂಪಾತ್ಮಕ ರಚನೆ","ನಾಮಸೂಚಕ ಚರಾಂಶ","ಹೊರಗಿನ ಮೌಲ್ಯ"],"why":"ಸೂಚಕಗಳು ಸೂಚ್ಯಂಕವನ್ನು ರೂಪಿಸುತ್ತವೆ; ಅವು ಸಹಸಂಬಂಧಿಸಬೇಕಿಲ್ಲ."},{"q":"ಜೋಡಿ t-ಪರೀಕ್ಷೆಗೆ ಅಪ್ರಾಚಲ ಪರ್ಯಾಯ…","options":["Mann–Whitney U","Wilcoxon signed-rank","Kruskal–Wallis","ಕೈ-ವರ್ಗ"],"why":"Wilcoxon signed-rank ಜೋಡಿ ವೀಕ್ಷಣೆಗಳನ್ನು ಹೋಲಿಸುತ್ತದೆ."},{"q":"ಒಬ್ಬ ಉತ್ತರದಾತ ಎಲ್ಲಾ 40 ಅಂಶಗಳಿಗೂ \"5\" ಉತ್ತರಿಸುತ್ತಾರೆ. ಇದು…","options":["ಅತ್ಯುತ್ತಮ ದತ್ತಾಂಶ","ಸಂಭಾವ್ಯ ಒಂದೇ ಉತ್ತರ (ನಿರ್ಲಕ್ಷ್ಯದ ಉತ್ತರ)","ರೂಪಾತ್ಮಕ ಸೂಚಕ","ಕಾಣೆಯಾದ ಮೌಲ್ಯ"],"why":"ಎಲ್ಲೆಡೆ ಒಂದೇ ಉತ್ತರ ನಿರ್ಲಕ್ಷ್ಯವನ್ನು ಸೂಚಿಸುತ್ತದೆ."},{"q":"ಹಿಮ್ಮುಖ ಅನುವಾದವನ್ನು ಬಳಸುವುದು…","options":["ಮಾದರಿ ಗಾತ್ರ ಹೆಚ್ಚಿಸಲು","ಅನುವಾದಿತ ಸಾಧನ ಮೂಲ ಅರ್ಥ ಉಳಿಸಿಕೊಂಡಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಲು","ಹೊರಗಿನ ಮೌಲ್ಯಗಳನ್ನು ತೆಗೆಯಲು","ಊಹೆಗಳನ್ನು ಪರೀಕ್ಷಿಸಲು"],"why":"ಸ್ವತಂತ್ರ ಅನುವಾದಕರು ಹಿಮ್ಮುಖವಾಗಿ ಅನುವಾದಿಸಿ ಅರ್ಥದ ವ್ಯತ್ಯಾಸವನ್ನು ಬಯಲುಮಾಡುತ್ತಾರೆ."}]},"m15":{"objectives":["ದತ್ತಾಂಶ ಅಂಶ ವಿಶ್ಲೇಷಣೆಗೆ ಸೂಕ್ತವೇ ಎಂದು ಪರಿಶೀಲಿಸುವುದು (KMO, Bartlett).","SPSS, R ಅಥವಾ Pythonನಲ್ಲಿ ಅನ್ವೇಷಣಾತ್ಮಕ ಅಂಶ ವಿಶ್ಲೇಷಣೆ (EFA) ನಡೆಸಿ ವ್ಯಾಖ್ಯಾನಿಸುವುದು.","AMOS ಅಥವಾ lavaanನಲ್ಲಿ ದೃಢೀಕರಣ ಅಂಶ ವಿಶ್ಲೇಷಣೆ (CFA) ಮೂಲಕ ಮಾಪನ ಮಾದರಿಯನ್ನು ರೂಪಿಸಿ ಮೌಲ್ಯಮಾಪನ ಮಾಡುವುದು.","ವಿಶ್ವಸನೀಯತೆ, ಒಮ್ಮುಖ ಸಿಂಧುತ್ವ ಮತ್ತು ಭೇದಾತ್ಮಕ ಸಿಂಧುತ್ವವನ್ನು ಸ್ಥಾಪಿಸುವುದು."],"lessons":[{"title":"ಅನ್ವೇಷಣಾತ್ಮಕ ಅಂಶ ವಿಶ್ಲೇಷಣೆ (EFA)","body":["EFA ಕೇಳುವುದು: ಅಂಶಗಳ ನಡುವಿನ ಸಹಸಂಬಂಧಗಳನ್ನು ಎಷ್ಟು ಆಧಾರ ಅಂಶಗಳು (factors) ವಿವರಿಸುತ್ತವೆ, ಮತ್ತು ಯಾವ ಅಂಶ ಯಾವ ಅಂಶಕ್ಕೆ ಸೇರುತ್ತದೆ? ಮಾಪಕ ಹೊಸದಾಗಿದ್ದಾಗ ಅಥವಾ ಹೊಸ ಜನಸಂಖ್ಯೆಯಲ್ಲಿ ಬಳಸುವಾಗ ಇದನ್ನು ಬಳಸಿ.","ಸೂಕ್ತತೆ: ಪ್ರತಿ ಅಂಶಕ್ಕೆ ಕನಿಷ್ಠ 5–10 ಉತ್ತರದಾತರು, ಸಾಧ್ಯವಾದರೆ 200 ಅಥವಾ ಹೆಚ್ಚು; KMO ≥ .60 (≥ .80 ಉತ್ತಮ) ಮತ್ತು ಪ್ರತಿ ಅಂಶದ KMO ≥ .50; Bartlett ಗೋಳೀಯತಾ ಪರೀಕ್ಷೆ ಮಹತ್ವದ್ದು (p < .05).","ಹೊರತೆಗೆಯುವಿಕೆ: principal axis factoring ಅಥವಾ maximum likelihood ಸಾಮಾನ್ಯ ಅಂಶಗಳನ್ನು ಅಂದಾಜಿಸುತ್ತವೆ; principal components analysis ಒಟ್ಟು ವ್ಯತ್ಯಾಸವನ್ನು ಸಂಕ್ಷೇಪಿಸುತ್ತದೆ, ಕಟ್ಟುನಿಟ್ಟಾಗಿ ಅಂಶ ವಿಶ್ಲೇಷಣೆಯಲ್ಲ. ಎಷ್ಟು ಅಂಶಗಳು: eigenvalue > 1 (Kaiser), scree ಚಿತ್ರದ ಮೊಣಕೈ, ಮತ್ತು — ಹೆಚ್ಚು ವಿಶ್ವಸನೀಯ — parallel analysis; ಪರಿಹಾರ ಸೈದ್ಧಾಂತಿಕವಾಗಿಯೂ ಅರ್ಥಪೂರ್ಣವಾಗಿರಬೇಕು.","ತಿರುಗಿಸುವಿಕೆ (rotation): ಅಂಶಗಳು ಸಂಬಂಧರಹಿತವೆಂದು ನಿರೀಕ್ಷಿಸಿದಾಗ varimax (ಲಂಬಕೋನೀಯ); ಸಂಬಂಧಿಸುತ್ತವೆಂದು ನಿರೀಕ್ಷಿಸಿದಾಗ promax ಅಥವಾ oblimin (ಓರೆ) — ಶಿಕ್ಷಣದಲ್ಲಿ ಇದು ಸಾಮಾನ್ಯ. ತಮ್ಮ ಅಂಶದ ಮೇಲೆ ಭಾರ (loading) ≥ .50 ಮತ್ತು ಅಡ್ಡ-ಭಾರ .30ಕ್ಕಿಂತ ಕಡಿಮೆ (ಅಥವಾ ಕನಿಷ್ಠ .20 ಕಡಿಮೆ) ಇರುವ ಅಂಶಗಳನ್ನು ಉಳಿಸಿ; ಸಾಮಾನ್ಯತೆ (communality) ≥ .40 ಆದರ್ಶ. ದುರ್ಬಲ ಅಂಶಗಳನ್ನು ಒಂದೊಂದಾಗಿ ತೆಗೆದು ಮರುನಡೆಸಿ.","SPSS: Analyze → Dimension Reduction → Factor → Descriptives: KMO and Bartlett's test; Extraction: Principal axis factoring, Scree plot; Rotation: Promax (ಅಥವಾ Varimax); Options: Sorted by size, .30ಕ್ಕಿಂತ ಕಡಿಮೆ ಗುಣಾಂಕಗಳನ್ನು ಮರೆಮಾಡಿ."]},{"title":"ದೃಢೀಕರಣ ಅಂಶ ವಿಶ್ಲೇಷಣೆ (CFA)","body":["CFA ಮೊದಲೇ ನಿರ್ದಿಷ್ಟಪಡಿಸಿದ ಮಾಪನ ಮಾದರಿಯನ್ನು ಪರೀಕ್ಷಿಸುತ್ತದೆ: ಯಾವ ಅಂಶ ಯಾವ ಅಂಶದ ಮೇಲೆ ಭಾರ ಹೊಂದಿದೆ, ಅಡ್ಡ-ಭಾರಗಳಿಲ್ಲದೆ. EFAಗಿಂತ ಬೇರೆ ಮಾದರಿಯನ್ನು ಬಳಸಿ (ದತ್ತಾಂಶವನ್ನು ಯಾದೃಚ್ಛಿಕವಾಗಿ ವಿಭಜಿಸಿ ಅಥವಾ ಎರಡನೇ ಮಾದರಿ ಸಂಗ್ರಹಿಸಿ).","AMOSನಲ್ಲಿ: ಪ್ರತಿ ಗುಪ್ತ ಅಂಶವನ್ನು ದೀರ್ಘವೃತ್ತವಾಗಿ, ಅದರ ಅಂಶಗಳನ್ನು ಆಯತಗಳಾಗಿ ಬರೆಯಿರಿ, ಪ್ರತಿ ಅಂಶಕ್ಕೆ ದೋಷ ಪದ ಸೇರಿಸಿ, ಪ್ರತಿ ಅಂಶದ ಮೊದಲ ಭಾರವನ್ನು 1ಕ್ಕೆ ನಿಗದಿಪಡಿಸಿ (ಅಥವಾ ಅಂಶ ವ್ಯತ್ಯಾಸವನ್ನು 1ಕ್ಕೆ), ಅಂಶಗಳನ್ನು ಎರಡು ತಲೆಯ ಬಾಣಗಳಿಂದ (ಸಹವ್ಯತ್ಯಾಸ) ಜೋಡಿಸಿ, Maximum likelihood ಆರಿಸಿ, Analysis Propertiesನಲ್ಲಿ Standardized estimates ಮತ್ತು Modification indices ಗುರುತಿಸಿ. ಭಾರಗಳನ್ನು ವ್ಯಾಖ್ಯಾನಿಸುವ ಮೊದಲು ಮಾದರಿ ಹೊಂದಾಣಿಕೆ (ಅಧ್ಯಾಯ 16) ವರದಿ ಮಾಡಿ.","ಮೌಲ್ಯಮಾಪನ: ಪ್ರಮಾಣೀಕೃತ ಭಾರಗಳು ≥ .70 ಆದರ್ಶ (ವಿಶ್ವಸನೀಯತೆ ಇದ್ದರೆ ≥ .50 ಸ್ವೀಕಾರಾರ್ಹ); ಸಂಯೋಜಿತ ವಿಶ್ವಸನೀಯತೆ (CR) ≥ .70; ಒಮ್ಮುಖ ಸಿಂಧುತ್ವಕ್ಕೆ ಸರಾಸರಿ ಹೊರತೆಗೆದ ವ್ಯತ್ಯಾಸ (AVE) ≥ .50. ಭೇದಾತ್ಮಕ ಸಿಂಧುತ್ವ: ಪ್ರತಿ ಅಂಶದ AVEಯ ವರ್ಗಮೂಲ ಇತರ ಅಂಶಗಳೊಂದಿಗಿನ ಸಹಸಂಬಂಧಕ್ಕಿಂತ ಹೆಚ್ಚಿರಬೇಕು (Fornell & Larcker, 1981), ಮತ್ತು HTMT ಅನುಪಾತ .85ಕ್ಕಿಂತ ಕಡಿಮೆ (ಸಮಾನ ಪರಿಕಲ್ಪನೆಗಳಿಗೆ .90; Henseler ಮತ್ತು ಇತರರು, 2015)."]},{"title":"ವಿಶ್ವಸನೀಯತೆ ಮತ್ತು ಸಿಂಧುತ್ವ: ಒಟ್ಟುಗೂಡಿಸಿ","body":["ಪ್ರತಿ ಅಂಶಕ್ಕೆ Cronbach ಆಲ್ಫಾ ಮತ್ತು ಸಂಯೋಜಿತ ವಿಶ್ವಸನೀಯತೆ, ಮಹತ್ವದೊಂದಿಗೆ ಭಾರಗಳು, CR ಮತ್ತು AVE ಒಂದೇ ಕೋಷ್ಟಕದಲ್ಲಿ, ಮತ್ತು ಭೇದಾತ್ಮಕ ಸಿಂಧುತ್ವಕ್ಕೆ Fornell–Larcker ಅಥವಾ HTMT ಕೋಷ್ಟಕ ವರದಿ ಮಾಡಿ.","AVE .50ಕ್ಕಿಂತ ಕಡಿಮೆಯಿದ್ದು CR .60ಕ್ಕಿಂತ ಹೆಚ್ಚಿದ್ದರೆ ಒಮ್ಮುಖ ಸಿಂಧುತ್ವವನ್ನು ಸಮರ್ಪಕವೆಂದು ಪರಿಗಣಿಸಬಹುದು (Fornell & Larcker, 1981) — ಇದನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ಹೇಳಿ. ಅಂಶ ಏನನ್ನು ಅಳೆಯುತ್ತದೆ ಎಂದು ಯೋಚಿಸದೆ ಕೇವಲ ಹೊಂದಾಣಿಕೆ ಸುಧಾರಿಸಲು ಅಂಶಗಳನ್ನು ಅಳಿಸಬೇಡಿ; ಅಂಕಿಗಳಷ್ಟೇ ವಿಷಯ ಸಿಂಧುತ್ವವೂ ಮುಖ್ಯ."]}],"karnataka":[{"title":"ಸಂಶೋಧನಾ ಸ್ವ-ಸಾಮರ್ಥ್ಯ ಮಾಪಕದ EFA","text":["12-ಅಂಶಗಳ ಮಾಪಕದಲ್ಲಿ 220 ಡಯಟ್ ಉಪನ್ಯಾಸಕರು ಮತ್ತು ಸಿಆರ್‌ಪಿಗಳ ಉದಾಹರಣಾ ಫಲಿತಾಂಶಗಳು: KMO = .85, Bartlett χ²(66) = 1121, p < .001. ಮೂರು ಅಂಶಗಳ eigenvalue 1ಕ್ಕಿಂತ ಹೆಚ್ಚು (4.47, 1.99, 1.72) ಮತ್ತು ಒಟ್ಟಾಗಿ ಸುಮಾರು ಶೇ. 68 ಒಟ್ಟು ವ್ಯತ್ಯಾಸವನ್ನು ವಿವರಿಸುತ್ತವೆ (ಆರಂಭಿಕ eigenvalueಗಳು; principal axis ಹೊರತೆಗೆಯುವಿಕೆಯ ನಂತರ ಸುಮಾರು ಶೇ. 58). ತಿರುಗಿಸಿದ ನಂತರ ಸಮಸ್ಯೆ ರೂಪಿಸುವಿಕೆ, ದತ್ತಾಂಶ ವಿಶ್ಲೇಷಣೆ ಮತ್ತು ಸಂವಹನದ ತಲಾ ನಾಲ್ಕು ಅಂಶಗಳು ತಮ್ಮದೇ ಅಂಶದ ಮೇಲೆ ಭಾರ ಹೊಂದುತ್ತವೆ. EFA ಸಾಧನದಲ್ಲಿ ಇದನ್ನು ನೀವೇ ನಡೆಸಿ."]},{"title":"ಎರಡನೇ ಮಾದರಿಯಲ್ಲಿ CFA","text":["ಕಲಬುರಗಿ ಮತ್ತು ರಾಯಚೂರಿನ 240 ಶಿಕ್ಷಕರ ಎರಡನೇ ಸ್ವತಂತ್ರ ಮಾದರಿಯನ್ನು CFAಗೆ ಬಳಸಲಾಗುತ್ತದೆ. ಉದಾಹರಣಾ ಪ್ರಮಾಣೀಕೃತ ಭಾರಗಳು .68 ರಿಂದ .86. ಮೂರೂ ಅಂಶಗಳಿಗೆ CR .80ಕ್ಕಿಂತ ಮತ್ತು AVE .55ಕ್ಕಿಂತ ಹೆಚ್ಚು; ಪ್ರತಿ √AVE ಅಂಶಗಳ ನಡುವಿನ ಸಹಸಂಬಂಧಗಳನ್ನು ಮೀರುತ್ತದೆ — ಭೇದಾತ್ಮಕ ಸಿಂಧುತ್ವಕ್ಕೆ ಬೆಂಬಲ. ಈಗ ಮಾಪಕವನ್ನು ಅಧ್ಯಾಯ 16ರ SEMನಲ್ಲಿ ಬಳಸಬಹುದು."]}],"activity":{"title":"EFA ನಡೆಸಿ ಮಾಪನ ಮಾದರಿಯನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ","prompt":"ಮೂರು ಅಂಶಗಳೊಂದಿಗೆ ಮಾದರಿ ದತ್ತಾಂಶದ ಮೇಲೆ EFA ಸಾಧನ ನಡೆಸಿ. ಪ್ರತಿ ಅಂಶಕ್ಕೆ ಹೆಸರಿಡಿ ಮತ್ತು ಯಾವುದಾದರೂ ಅಂಶ ಕೈಬಿಡಬೇಕೇ ಎಂದು ನಿರ್ಧರಿಸಿ. ನಂತರ CFA ಗಣಕದಲ್ಲಿ ಭಾರಗಳು ಮತ್ತು ಅಂಶ ಸಹಸಂಬಂಧಗಳನ್ನು ನಮೂದಿಸಿ ವಿಶ್ವಸನೀಯತೆ ಮತ್ತು ಸಿಂಧುತ್ವವನ್ನು ನಿರ್ಣಯಿಸಿ."},"quiz":[{"q":"ನಿಮ್ಮ ದತ್ತಾಂಶಕ್ಕೆ KMO = .52 ಎಂದರೆ…","options":["ಅತ್ಯುತ್ತಮ ಸೂಕ್ತತೆ","ಕೇವಲ ಸೂಕ್ತ; ಹೆಚ್ಚು ದತ್ತಾಂಶ ಅಥವಾ ದುರ್ಬಲ ಅಂಶಗಳ ತೆಗೆಯುವಿಕೆ ಪರಿಗಣಿಸಿ","ಮಾದರಿ ಹೊಂದುತ್ತದೆ","ವಿಶ್ವಸನೀಯತೆ ಹೆಚ್ಚು"],"why":".60ಕ್ಕಿಂತ ಕಡಿಮೆ ಮೌಲ್ಯಗಳು ದುರ್ಬಲ ಮಾದರಿ ಸಮರ್ಪಕತೆ ಸೂಚಿಸುತ್ತವೆ."},{"q":"ಅಂಶಗಳು ಸಹಸಂಬಂಧಿಸುತ್ತವೆಂದು ನಿರೀಕ್ಷಿಸಿದಾಗ ಬಳಸಬೇಕಾದದ್ದು…","options":["Varimax","promax ಅಥವಾ oblimin ನಂತಹ ಓರೆ ತಿರುಗಿಸುವಿಕೆ","ತಿರುಗಿಸುವಿಕೆ ಬೇಡ","Bartlett ಪರೀಕ್ಷೆ"],"why":"ಓರೆ ತಿರುಗಿಸುವಿಕೆ ಅಂಶಗಳ ಸಹಸಂಬಂಧಕ್ಕೆ ಅವಕಾಶ ನೀಡುತ್ತದೆ."},{"q":"AVE = .58 ಮತ್ತು CR = .84 ಸೂಚಿಸುವುದು…","options":["ದುರ್ಬಲ ವಿಶ್ವಸನೀಯತೆ","ಸಮರ್ಪಕ ಒಮ್ಮುಖ ಸಿಂಧುತ್ವ ಮತ್ತು ವಿಶ್ವಸನೀಯತೆ","ಭೇದಾತ್ಮಕ ಸಿಂಧುತ್ವದ ವೈಫಲ್ಯ","ಅತಿ ಹೊಂದಾಣಿಕೆ"],"why":"AVE ≥ .50 ಮತ್ತು CR ≥ .70 ಸಾಮಾನ್ಯ ಮಿತಿಗಳು."},{"q":"EFAಗಿಂತ ಬೇರೆ ಮಾದರಿಯಲ್ಲಿ CFA ಏಕೆ?","options":["ಸಮಯ ಉಳಿಸಲು","ಅದೇ ದತ್ತಾಂಶವನ್ನು ಮರುವರ್ಣಿಸುವ ಬದಲು ರಚನೆಯನ್ನು ದೃಢೀಕರಿಸಲು","AMOSಗೆ ಬೇಕಾದ್ದರಿಂದ","ಆಲ್ಫಾ ಹೆಚ್ಚಿಸಲು"],"why":"ಅದೇ ದತ್ತಾಂಶ ಬಳಸಿದರೆ ಆಕಸ್ಮಿಕತೆಯ ಲಾಭ ಪಡೆದಂತಾಗುತ್ತದೆ."}]},"m16":{"objectives":["ಗುಪ್ತ ಮತ್ತು ವೀಕ್ಷಿತ ಚರಾಂಶಗಳು, ಮಾಪನ ಮತ್ತು ರಚನಾತ್ಮಕ ಮಾದರಿಗಳನ್ನು ವಿವರಿಸುವುದು.","AMOS ಅಥವಾ lavaanನಲ್ಲಿ ರಚನಾತ್ಮಕ ಮಾರ್ಗ ಮಾದರಿಯನ್ನು ರಚಿಸಿ ಅಂದಾಜಿಸುವುದು.","ಮಾದರಿ ಹೊಂದಾಣಿಕೆಯನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ ಮಾದರಿಯನ್ನು ಜವಾಬ್ದಾರಿಯಿಂದ ದೃಢೀಕರಿಸುವುದು.","ಮಧ್ಯಸ್ಥಿಕೆ, ನಿಯಂತ್ರಣ ಮತ್ತು ಗುಂಪು ವ್ಯತ್ಯಾಸಗಳನ್ನು (ಬಹು-ಗುಂಪು SEM) ಪರೀಕ್ಷಿಸುವುದು."],"lessons":[{"title":"SEM ಅರಿವು ಮತ್ತು ಮಾರ್ಗ ಮಾದರಿಗಳ ರಚನೆ","body":["SEM ಮಾಪನ ದೋಷವನ್ನು ಲೆಕ್ಕಿಸುತ್ತಾ ರಚನೆಗಳ ನಡುವಿನ ಸಂಬಂಧಗಳ ಜಾಲವನ್ನು ಪರೀಕ್ಷಿಸುತ್ತದೆ. ಇದು ಮಾಪನ ಮಾದರಿ (CFA: ರಚನೆಗಳು ಮತ್ತು ಅವುಗಳ ಅಂಶಗಳು) ಮತ್ತು ರಚನಾತ್ಮಕ ಮಾದರಿ (ರಚನೆಗಳ ನಡುವಿನ ಮಾರ್ಗಗಳು) ಸೇರಿದ್ದು. ಬಾಹ್ಯ (exogenous) ರಚನೆಗಳತ್ತ ಯಾವ ಬಾಣವೂ ಬರುವುದಿಲ್ಲ; ಆಂತರಿಕ (endogenous) ರಚನೆಗಳನ್ನು ಇತರರು ಮುನ್ಸೂಚಿಸುತ್ತಾರೆ.","ಎರಡು-ಹಂತದ ವಿಧಾನ ಬಳಸಿ (Anderson & Gerbing, 1988): ಮೊದಲು ಉತ್ತಮ ಮಾಪನ ಮಾದರಿ ಸ್ಥಾಪಿಸಿ (ಅಧ್ಯಾಯ 15), ನಂತರ ರಚನಾತ್ಮಕ ಮಾರ್ಗಗಳನ್ನು ಸೇರಿಸಿ. ಪ್ರತಿ ಮಾರ್ಗಕ್ಕೆ ಸೈದ್ಧಾಂತಿಕ ಕಾರಣ ಬೇಕು. ಮಾದರಿ ಗಾತ್ರ: 200 ಅಥವಾ ಹೆಚ್ಚು ಸಾಮಾನ್ಯ ಕನಿಷ್ಠ, ಸಂಕೀರ್ಣ ಮಾದರಿಗಳಿಗೆ ಹೆಚ್ಚು; ಸಾಧ್ಯವಾದಲ್ಲಿ ಪ್ರತಿ ಅಂದಾಜಿತ ಪ್ರಾಚಲಕ್ಕೆ ಕನಿಷ್ಠ 10 ಪ್ರಕರಣಗಳು.","ಸಹವ್ಯತ್ಯಾಸ-ಆಧಾರಿತ SEM (AMOS, lavaan) ಸಿದ್ಧಾಂತವನ್ನು ಪರೀಕ್ಷಿಸಿ ಹೊಂದಾಣಿಕೆ ಸೂಚ್ಯಂಕಗಳನ್ನು ನೀಡುತ್ತದೆ. ಆಂಶಿಕ ಕನಿಷ್ಠ ವರ್ಗ SEM (ಉದಾ: SmartPLS) ಮುನ್ಸೂಚನೆ, ಸಣ್ಣ ಮಾದರಿಗಳು ಮತ್ತು ರೂಪಾತ್ಮಕ ರಚನೆಗಳಿಗೆ ಸೂಕ್ತ, ಆದರೆ ಒಟ್ಟು ಮಾದರಿ ಹೊಂದಾಣಿಕೆಯನ್ನು ಅದೇ ರೀತಿ ಪರೀಕ್ಷಿಸುವುದಿಲ್ಲ. ಅನುಕೂಲದಿಂದಲ್ಲ, ಗುರಿಯಿಂದ ಆರಿಸಿ.","AMOSನಲ್ಲಿ: ದೃಢೀಕೃತ CFA ಚಿತ್ರದಿಂದ ಆರಂಭಿಸಿ, ಸಿದ್ಧಾಂತ ಪರಿಣಾಮವನ್ನು ಮುನ್ಸೂಚಿಸುವಲ್ಲಿ ರಚನೆಗಳ ನಡುವಿನ ಸಹವ್ಯತ್ಯಾಸಗಳನ್ನು ಒಂದೇ ತಲೆಯ ಬಾಣಗಳಿಂದ ಬದಲಿಸಿ, ಪ್ರತಿ ಆಂತರಿಕ ರಚನೆಗೆ ಉಳಿಕೆ ಪದ ಸೇರಿಸಿ, maximum likelihoodನಿಂದ ಅಂದಾಜಿಸಿ. ಪ್ರಮಾಣೀಕೃತ ಮಾರ್ಗ ಗುಣಾಂಕಗಳು (β), ಅವುಗಳ ಮಹತ್ವ ಮತ್ತು ಪ್ರತಿ ಆಂತರಿಕ ರಚನೆಯ R² ವರದಿ ಮಾಡಿ."]},{"title":"ಮಾದರಿ ಹೊಂದಾಣಿಕೆ, ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ದೃಢೀಕರಣ","body":["ಹಲವು ಹೊಂದಾಣಿಕೆ ಸೂಚ್ಯಂಕಗಳನ್ನು ಒಟ್ಟಿಗೆ ವರದಿ ಮಾಡಿ: df ಮತ್ತು p ಸಹಿತ χ² (ದೊಡ್ಡ ಮಾದರಿಗಳಿಗೆ ಸೂಕ್ಷ್ಮ, ಆದ್ದರಿಂದ ಏಕಾಂಗಿಯಾಗಿ ಬಳಸಬೇಡಿ), χ²/df (≤ 3 ಉತ್ತಮ), CFI ಮತ್ತು TLI (≥ .95 ಉತ್ತಮ, ≥ .90 ಸ್ವೀಕಾರಾರ್ಹ), 90% ವಿಶ್ವಾಸ ಅಂತರದೊಂದಿಗೆ RMSEA (≤ .06 ಉತ್ತಮ, ≤ .08 ಸ್ವೀಕಾರಾರ್ಹ) ಮತ್ತು SRMR (≤ .08). ಇವು ಮಾರ್ಗಸೂಚಿಗಳು (Hu & Bentler, 1999), ಕಾನೂನುಗಳಲ್ಲ.","ಮಾರ್ಪಾಡು ಸೂಚ್ಯಂಕಗಳು (modification indices) ಹೊಂದಾಣಿಕೆ ಸುಧಾರಿಸುವ ಬದಲಾವಣೆಗಳನ್ನು ಸೂಚಿಸುತ್ತವೆ. ಸ್ಪಷ್ಟ ಸೈದ್ಧಾಂತಿಕ ಕಾರಣವಿರುವ ಬದಲಾವಣೆಗಳನ್ನು ಮಾತ್ರ ಒಪ್ಪಿ (ಉದಾ: ಬಹುತೇಕ ಒಂದೇ ಪದರಚನೆಯ ಎರಡು ಅಂಶಗಳ ದೋಷಗಳ ಸಹಸಂಬಂಧ), ಒಂದೊಂದಾಗಿ ಮಾಡಿ, ಪ್ರತಿ ಬದಲಾವಣೆಯನ್ನು ವರದಿ ಮಾಡಿ. ಒಂದು ಮಾದರಿಗೆ ಹೊಂದಿಸಲು ಮಾರ್ಪಡಿಸಿದ ಮಾದರಿಯನ್ನು ಇನ್ನೊಂದರಲ್ಲಿ ಅಡ್ಡ-ದೃಢೀಕರಿಸಬೇಕು.","ಸಂಭಾವ್ಯ ಪರ್ಯಾಯಗಳೊಂದಿಗೆ ಹೋಲಿಸಿ (ಉದಾ: ನೇರ ಮಾರ್ಗ ಸಹಿತ ಮತ್ತು ರಹಿತ), ಅಂದಾಜುಗಳು ಸಮಂಜಸವೇ ಎಂದು ಪರಿಶೀಲಿಸಿ (ಋಣಾತ್ಮಕ ದೋಷ ವ್ಯತ್ಯಾಸಗಳಿಲ್ಲ, ಪ್ರಮಾಣೀಕೃತ ಮೌಲ್ಯಗಳು ±1 ಒಳಗೆ), ಮತ್ತು ಪ್ರತ್ಯೇಕ ಮಾದರಿಯಲ್ಲಿ ಪರೀಕ್ಷಿಸಿ ದೃಢೀಕರಿಸಿ."]},{"title":"ಮುಂದುವರಿದ ಅನ್ವಯಗಳು","body":["ಮಧ್ಯಸ್ಥಿಕೆ (mediation): ಪರೋಕ್ಷ ಪರಿಣಾಮ (a × b) X, M ಮೂಲಕ Y ಮೇಲೆ ಪ್ರಭಾವ ಬೀರುತ್ತದೆ ಎಂದು ತೋರಿಸುತ್ತದೆ. ಬೂಟ್‌ಸ್ಟ್ರ್ಯಾಪ್ ವಿಶ್ವಾಸ ಅಂತರಗಳಿಂದ (5,000 ಮರುಮಾದರಿಗಳು) ಪರೀಕ್ಷಿಸಿ; 95% ಅಂತರ ಶೂನ್ಯವನ್ನು ಒಳಗೊಳ್ಳದಿದ್ದರೆ ಪರೋಕ್ಷ ಪರಿಣಾಮ ಮಹತ್ವದ್ದು. ನೇರ, ಪರೋಕ್ಷ ಮತ್ತು ಒಟ್ಟು ಪರಿಣಾಮಗಳನ್ನು ವರದಿ ಮಾಡಿ. AMOSನಲ್ಲಿ: Analysis Properties → Bootstrap → Perform bootstrap (5000), Bias-corrected confidence intervals; Indirect, direct and total effects ಕೇಳಿ.","ನಿಯಂತ್ರಣ (moderation): X ಮೇಲೆ Y ಪರಿಣಾಮ W ಮೇಲೆ ಅವಲಂಬಿತ. ವೀಕ್ಷಿತ ಚರಾಂಶಗಳಿಗೆ X × W ಪರಸ್ಪರ ಕ್ರಿಯೆ (ಸರಾಸರಿ-ಕೇಂದ್ರಿತ) ಸೇರಿಸಿ; ಗುಪ್ತ ಚರಾಂಶಗಳಿಗೆ ಗುಪ್ತ ಪರಸ್ಪರ ಕ್ರಿಯೆ ವಿಧಾನಗಳು ಅಥವಾ ಬಹು-ಗುಂಪು ವಿಶ್ಲೇಷಣೆ ಬಳಸಿ.","ಬಹು-ಗುಂಪು SEM: ಕಲ್ಯಾಣ ಕರ್ನಾಟಕ ಮತ್ತು ಇತರ ಜಿಲ್ಲೆಗಳು, ಅಥವಾ ಪುರುಷ ಮತ್ತು ಮಹಿಳಾ ಶಿಕ್ಷಕರಂತಹ ಗುಂಪುಗಳನ್ನು ಹೋಲಿಸಿ. ಮೊದಲು ಮಾಪನ ಅಚರತೆ (measurement invariance) ಹಂತಗಳಲ್ಲಿ ಪರೀಕ್ಷಿಸಿ — ರೂಪ (configural), ಮಾಪಕ (metric: ಸಮ ಭಾರಗಳು), ಅಳತೆ (scalar: ಸಮ ಛೇದಕಗಳು) — CFI .01ಕ್ಕಿಂತ ಹೆಚ್ಚು ಇಳಿಯದಿದ್ದರೆ ಪ್ರತಿ ಹಂತವನ್ನು ಒಪ್ಪಿ. ನಂತರವೇ ಗುಂಪುಗಳ ನಡುವೆ ಮಾರ್ಗಗಳು ಅಥವಾ ಸರಾಸರಿಗಳನ್ನು ಹೋಲಿಸಿ.","ಉನ್ನತ-ಕ್ರಮದ ಮಾದರಿಗಳು ಮೊದಲ-ಕ್ರಮದ ಅಂಶಗಳ ಮೇಲೆ ಸಾಮಾನ್ಯ ಅಂಶವನ್ನು ಪ್ರತಿನಿಧಿಸುತ್ತವೆ (ಉದಾ: ಮೂರು ಆಯಾಮಗಳ ಮೇಲಿನ ಒಟ್ಟು ಸಂಶೋಧನಾ ಸ್ವ-ಸಾಮರ್ಥ್ಯ)."]}],"karnataka":[{"title":"ಡಯಟ್ ಬೆಂಬಲ ಸಂಶೋಧನಾ ತೊಡಗಿಸಿಕೊಳ್ಳುವಿಕೆಯನ್ನು ಬೆಳೆಸುತ್ತದೆಯೇ?","text":["260 ಶಿಕ್ಷಕರ ಉದಾಹರಣಾ ಮಾದರಿ: ಡಯಟ್ ಬೆಂಬಲ (ಮಾರ್ಗದರ್ಶನ, ಕಾರ್ಯಾಗಾರಗಳು, ಪ್ರತಿಕ್ರಿಯೆ) → ಸಂಶೋಧನಾ ಸ್ವ-ಸಾಮರ್ಥ್ಯ → ಸಂಶೋಧನಾ ತೊಡಗಿಸಿಕೊಳ್ಳುವಿಕೆ (ಕ್ರಿಯಾ ಸಂಶೋಧನಾ ಯೋಜನೆಗಳು, ಕ್ಲಸ್ಟರ್ ಸಭೆಗಳಲ್ಲಿ ಪ್ರಸ್ತುತಿಗಳು). ಹೊಂದಾಣಿಕೆ: χ²(87) = 141.6, χ²/df = 1.63, CFI = .97, TLI = .96, RMSEA = .049, SRMR = .046. ಬೆಂಬಲ → ಸ್ವ-ಸಾಮರ್ಥ್ಯ β = .48; ಸ್ವ-ಸಾಮರ್ಥ್ಯ → ತೊಡಗಿಸಿಕೊಳ್ಳುವಿಕೆ β = .44; ಬೆಂಬಲದಿಂದ ತೊಡಗಿಸಿಕೊಳ್ಳುವಿಕೆಗೆ ನೇರ ಮಾರ್ಗ ಚಿಕ್ಕದು (β = .12). ಬೂಟ್‌ಸ್ಟ್ರ್ಯಾಪ್ ಪರೋಕ್ಷ ಪರಿಣಾಮ ಮಹತ್ವದ್ದು — ಡಯಟ್ ಬೆಂಬಲ ಮುಖ್ಯವಾಗಿ ಶಿಕ್ಷಕರ ಆತ್ಮವಿಶ್ವಾಸ ಬೆಳೆಸುವ ಮೂಲಕ ಕೆಲಸ ಮಾಡುತ್ತದೆ ಎಂದು ಸೂಚಿಸುತ್ತದೆ."]},{"title":"ಬಹು-ಗುಂಪು SEM ಮೂಲಕ ಪ್ರದೇಶಗಳ ಹೋಲಿಕೆ","text":["ಅದೇ ಮಾದರಿಯನ್ನು ಕಲ್ಯಾಣ ಕರ್ನಾಟಕ ಜಿಲ್ಲೆಗಳು ಮತ್ತು ಇತರ ಜಿಲ್ಲೆಗಳಿಗೆ ಪ್ರತ್ಯೇಕವಾಗಿ ಪರೀಕ್ಷಿಸಲಾಗುತ್ತದೆ. ರೂಪ ಮತ್ತು ಮಾಪಕ ಅಚರತೆ ಉಳಿಯುತ್ತದೆ (ΔCFI < .01), ಆದ್ದರಿಂದ ಮಾರ್ಗಗಳನ್ನು ಹೋಲಿಸಬಹುದು. ಕಲ್ಯಾಣ ಕರ್ನಾಟಕದಲ್ಲಿ ಬೆಂಬಲ → ಸ್ವ-ಸಾಮರ್ಥ್ಯ ಮಾರ್ಗ ಹೆಚ್ಚು ಬಲವಾಗಿದ್ದರೆ, ಅಲ್ಲಿ ಮಾರ್ಗದರ್ಶನಕ್ಕೆ ಆದ್ಯತೆ ನೀಡಬೇಕೆಂದು ಡಯಟ್ ವಾದಿಸಬಹುದು."]}],"activity":{"title":"ಹೊಂದಾಣಿಕೆ ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ಮಧ್ಯಸ್ಥಿಕೆ ಪರೀಕ್ಷೆ","prompt":"ಉದಾಹರಣೆಯ (ಅಥವಾ ನಿಮ್ಮದೇ ಫಲಿತಾಂಶದ) ಹೊಂದಾಣಿಕೆ ಸೂಚ್ಯಂಕಗಳನ್ನು ಹೊಂದಾಣಿಕೆ ಪರಿಶೀಲಕದಲ್ಲಿ ನಮೂದಿಸಿ, ರಚಿತ ವಾಕ್ಯವನ್ನು ನಕಲಿಸಿ. ನಂತರ ಮಾದರಿ ದತ್ತಾಂಶದ ಮೇಲೆ ಮಧ್ಯಸ್ಥಿಕೆ ಸಾಧನ ನಡೆಸಿ, ವಿಶ್ವಾಸ ಅಂತರದೊಂದಿಗೆ ಪರೋಕ್ಷ ಪರಿಣಾಮವನ್ನು ವರದಿ ಮಾಡಿ."},"quiz":[{"q":"ಎರಡು-ಹಂತದ ವಿಧಾನದಲ್ಲಿ ನೀವು ಮೊದಲು…","options":["ಎಲ್ಲಾ ರಚನಾತ್ಮಕ ಮಾರ್ಗಗಳನ್ನು ಸೇರಿಸುತ್ತೀರಿ","ಮಾಪನ ಮಾದರಿಯನ್ನು ದೃಢೀಕರಿಸುತ್ತೀರಿ","ಬಹು-ಗುಂಪು ವಿಶ್ಲೇಷಣೆ ನಡೆಸುತ್ತೀರಿ","ಕಡಿಮೆ ಭಾರದ ಅಂಶಗಳನ್ನು ಅಳಿಸುತ್ತೀರಿ"],"why":"ರಚನಾತ್ಮಕ ಮಾರ್ಗಗಳಿಗೆ ಮುನ್ನ ಸಮರ್ಪಕ ಮಾಪನ ಮಾದರಿ ಬೇಕು."},{"q":"CFI = .96, RMSEA = .05, SRMR = .04 ಸೂಚಿಸುವುದು…","options":["ದುರ್ಬಲ ಹೊಂದಾಣಿಕೆ","ಉತ್ತಮ ಹೊಂದಾಣಿಕೆ","ಕೇವಲ ಅತಿ ಹೊಂದಾಣಿಕೆ","χ² ಇಲ್ಲದೆ ಏನೂ ಇಲ್ಲ"],"why":"ಮೂರೂ ಸಾಮಾನ್ಯ ಉತ್ತಮ-ಹೊಂದಾಣಿಕೆ ಮಾರ್ಗಸೂಚಿಗಳನ್ನು ಪೂರೈಸುತ್ತವೆ."},{"q":"ಮಧ್ಯಸ್ಥಿಕೆ ಪರಿಣಾಮಕ್ಕೆ ಬೆಂಬಲ ಸಿಗುವುದು…","options":["ನೇರ ಮಾರ್ಗ ಶೂನ್ಯವಾದಾಗ","a × b ಯ ಬೂಟ್‌ಸ್ಟ್ರ್ಯಾಪ್ 95% ವಿಶ್ವಾಸ ಅಂತರ ಶೂನ್ಯವನ್ನು ಒಳಗೊಳ್ಳದಿದ್ದಾಗ","R² .50ಕ್ಕಿಂತ ಹೆಚ್ಚಿದ್ದಾಗ","χ² ಮಹತ್ವದ್ದಲ್ಲದಿದ್ದಾಗ"],"why":"ಪರೋಕ್ಷ ಪರಿಣಾಮವನ್ನು ಬೂಟ್‌ಸ್ಟ್ರ್ಯಾಪ್ ಅಂತರಗಳಿಂದ ಪರೀಕ್ಷಿಸಲಾಗುತ್ತದೆ."},{"q":"ಎರಡು ಗುಂಪುಗಳ ನಡುವೆ ಮಾರ್ಗಗಳನ್ನು ಹೋಲಿಸುವ ಮೊದಲು ಸ್ಥಾಪಿಸಬೇಕಾದದ್ದು…","options":["ಸಮಾನ ಮಾದರಿ ಗಾತ್ರ","ಮಾಪನ ಅಚರತೆ (ಕನಿಷ್ಠ metric)","ಒಂದೇ ಸರಾಸರಿಗಳು","ಉನ್ನತ-ಕ್ರಮದ ಅಂಶ"],"why":"ಎರಡೂ ಗುಂಪುಗಳಲ್ಲಿ ರಚನೆಗಳನ್ನು ಒಂದೇ ರೀತಿ ಅಳೆಯಬೇಕು."}]},"m17":{"objectives":["EFA, CFA ಮತ್ತು SEM ಫಲಿತಾಂಶಗಳನ್ನು ನಿಯತಕಾಲಿಕ ಮಟ್ಟದಲ್ಲಿ ವರದಿ ಮಾಡುವುದು.","ಸೂಕ್ತ ನಿಯತಕಾಲಿಕ ಆರಿಸುವುದು, ಪರಿಶೀಲಕರಿಗೆ ಉತ್ತರಿಸುವುದು ಮತ್ತು ಶೋಷಕ ಪ್ರಕಟಣೆಗಳನ್ನು ತಪ್ಪಿಸುವುದು.","ಸಂಶೋಧನಾ ಪ್ರಕ್ರಿಯೆಯುದ್ದಕ್ಕೂ ಉತ್ಪಾದಕ ಮತ್ತು ಏಜೆಂಟಿಕ್ AI ಸಾಧನಗಳನ್ನು ಜವಾಬ್ದಾರಿಯಿಂದ ಬಳಸುವುದು.","ಶಿಕ್ಷಣದಲ್ಲಿ ಬೃಹತ್ ದತ್ತಾಂಶ (big data) ಮತ್ತು ಅಂತರಶಿಸ್ತೀಯ ಸಂಶೋಧನೆಯ ಅವಕಾಶಗಳು ಹಾಗೂ ಅಪಾಯಗಳನ್ನು ಗುರುತಿಸುವುದು."],"lessons":[{"title":"ಫಲಿತಾಂಶಗಳಿಂದ ಪ್ರಕಟಣೆಯೋಗ್ಯ ಹಸ್ತಪ್ರತಿಯವರೆಗೆ","body":["ಬಹುತೇಕ ಅನುಭವಜನ್ಯ ಲೇಖನಗಳು IMRaD ಅನುಸರಿಸುತ್ತವೆ: ಪೀಠಿಕೆ (ಸಮಸ್ಯೆ, ಅಂತರ, ಗುರಿ), ವಿಧಾನ (ಭಾಗವಹಿಸಿದವರು, ಸಾಧನಗಳು, ಕಾರ್ಯವಿಧಾನ, ನೈತಿಕತೆ, ವಿಶ್ಲೇಷಣೆ), ಫಲಿತಾಂಶಗಳು, ಮತ್ತು ಚರ್ಚೆ (ಅರ್ಥ, ಹಿಂದಿನ ಅಧ್ಯಯನಗಳೊಂದಿಗೆ ಹೋಲಿಕೆ, ಪರಿಣಾಮಗಳು, ಮಿತಿಗಳು, ಮುಂದಿನ ಸಂಶೋಧನೆ). ಮತ್ತೊಬ್ಬ ಸಂಶೋಧಕ ಅಧ್ಯಯನವನ್ನು ಪುನರಾವರ್ತಿಸುವಂತೆ ವಿಧಾನ ಬರೆಯಿರಿ.","ಬಹುಚರ ವಿಶ್ಲೇಷಣೆಗೆ ವರದಿ ಮಾಡಬೇಕಾದವು: ತಂತ್ರಾಂಶ ಮತ್ತು ಆವೃತ್ತಿ; ಅಂದಾಜುಗಾರ; ಕಾಣೆಯಾದ ದತ್ತಾಂಶ ನಿರ್ವಹಣೆ; EFAಗೆ KMO, Bartlett, ಹೊರತೆಗೆಯುವಿಕೆ, ತಿರುಗಿಸುವಿಕೆ ಮತ್ತು ಭಾರಗಳು; ಭಾರಗಳು, CR, AVE ಮತ್ತು ಭೇದಾತ್ಮಕ ಸಿಂಧುತ್ವದೊಂದಿಗೆ CFA ಕೋಷ್ಟಕ; RMSEA ವಿಶ್ವಾಸ ಅಂತರ ಸಹಿತ ಹೊಂದಾಣಿಕೆ ಸೂಚ್ಯಂಕಗಳು; ಪ್ರಮಾಣಿತ ದೋಷ, p-ಮೌಲ್ಯ ಮತ್ತು ವಿಶ್ವಾಸ ಅಂತರಗಳೊಂದಿಗೆ ಪ್ರಮಾಣೀಕೃತ ಮಾರ್ಗ ಗುಣಾಂಕಗಳು; R²; ಮತ್ತು ಬೂಟ್‌ಸ್ಟ್ರ್ಯಾಪ್ ಅಂತರಗಳೊಂದಿಗೆ ಪರೋಕ್ಷ ಪರಿಣಾಮಗಳು. ಪ್ರಮಾಣೀಕೃತ ಅಂದಾಜುಗಳಿರುವ ಸ್ಪಷ್ಟ ಮಾರ್ಗ ಚಿತ್ರ ಓದುಗರಿಗೆ ನೆರವಾಗುತ್ತದೆ.","ಚರ್ಚೆಯಲ್ಲಿ ಪರಿಣಾಮ ಗಾತ್ರಗಳನ್ನು ವ್ಯಾವಹಾರಿಕವಾಗಿ ವ್ಯಾಖ್ಯಾನಿಸಿ (\"ಡಯಟ್ ಬೆಂಬಲದಲ್ಲಿ ಒಂದು ಪ್ರಮಾಣಿತ ವಿಚಲನೆ ಹೆಚ್ಚಳ…ಕ್ಕೆ ಸಂಬಂಧಿಸಿದೆ\"), ಅಡ್ಡ-ವಿಭಾಗೀಯ ದತ್ತಾಂಶದಲ್ಲಿ ಸಂಬಂಧ ಮತ್ತು ಕಾರಣವನ್ನು ಪ್ರತ್ಯೇಕಿಸಿ, ಶಿಫಾರಸುಗಳನ್ನು ನಿರ್ದಿಷ್ಟ ಫಲಿತಾಂಶಗಳಿಗೆ ಜೋಡಿಸಿ."]},{"title":"ಪ್ರಕಟಣೆ: ನಿಯತಕಾಲಿಕ ಆಯ್ಕೆ ಮತ್ತು ಪರಿಶೀಲಕರೊಂದಿಗೆ ಕೆಲಸ","body":["ವ್ಯಾಪ್ತಿ, ಓದುಗರು, ಸೂಚೀಕರಣ (Scopus, Web of Science, UGC-CARE ಪಟ್ಟಿ), ಪರಿಶೀಲನಾ ಅವಧಿ ಮತ್ತು ವೆಚ್ಚದ ಹೊಂದಾಣಿಕೆಯಿಂದ ನಿಯತಕಾಲಿಕ ಆರಿಸಿ. ಇತ್ತೀಚಿನ ಸಂಚಿಕೆಗಳು ಮತ್ತು ಲೇಖಕರ ಮಾರ್ಗಸೂಚಿಗಳನ್ನು ಓದಿ. ನಕಲಿ ಅಥವಾ ಶೋಷಕ ನಿಯತಕಾಲಿಕಗಳನ್ನು ಪರಿಶೀಲಿಸಿ: ಸೂಚೀಕರಣ ದತ್ತಸಂಚಯದಿಂದಲೇ ನಿಯತಕಾಲಿಕದ ಜಾಲತಾಣವನ್ನು ದೃಢಪಡಿಸಿ, ಖಚಿತ ಸ್ವೀಕಾರ ಅಥವಾ ಅತಿ ವೇಗದ ಪರಿಶೀಲನೆಯ ಬಗ್ಗೆ ಎಚ್ಚರವಿರಲಿ, ನಿಜವಾದ ಪರಿಶೀಲನೆಗೆ ಮುನ್ನ ಶುಲ್ಕ ಕಟ್ಟಬೇಡಿ.","ಕೊಡುಗೆ ಮತ್ತು ನಿಯತಕಾಲಿಕಕ್ಕೆ ಏಕೆ ಸೂಕ್ತ ಎಂದು ತಿಳಿಸುವ ಚಿಕ್ಕ ಮುಖಪತ್ರ ಬರೆಯಿರಿ. ಪರಿಶೀಲಕರ ಟಿಪ್ಪಣಿಗಳನ್ನು ಉಚಿತ ತಜ್ಞ ಸಲಹೆಯೆಂದು ಪರಿಗಣಿಸಿ: ಕೋಷ್ಟಕದಲ್ಲಿ ಅಂಶವಾರು ಉತ್ತರಿಸಿ, ಏನು ಬದಲಿಸಿದಿರಿ ಮತ್ತು ಎಲ್ಲಿ ಎಂದು ಹೇಳಿ, ಒಪ್ಪದಿದ್ದಾಗ ಪುರಾವೆಯೊಂದಿಗೆ ವಿನಯದಿಂದ ವಿವರಿಸಿ.","ORCID ಗುರುತು, ನೈತಿಕತೆ ಅನುಮತಿಸುವಲ್ಲಿ ದತ್ತಾಂಶ ಮತ್ತು ಕೋಡ್ ಹಂಚಿಕೆ, ನಿಯತಕಾಲಿಕ ಅನುಮತಿಸುವಲ್ಲಿ ಪೂರ್ವಮುದ್ರಣಗಳು, ಮತ್ತು ಸಾಂಸ್ಥಿಕ ಭಂಡಾರಗಳಂತಹ ಮುಕ್ತ-ಪ್ರವೇಶ ಆಯ್ಕೆಗಳಿಂದ ಗೋಚರತೆ ಮತ್ತು ಪ್ರಾಮಾಣಿಕತೆ ಬಲಪಡಿಸಿ."]},{"title":"AI ಆಧಾರಿತ ಸಂಶೋಧನೆ: ಉತ್ಪಾದಕದಿಂದ ಏಜೆಂಟಿಕ್ AIವರೆಗೆ","body":["ಉತ್ಪಾದಕ AI (ChatGPT, Claude ಅಥವಾ Gemini ನಂತಹ ಸಂವಾದ ಸಹಾಯಕರು) ಪಠ್ಯ ಕರಡು, ನೀವು ನೀಡುವ ಲೇಖನಗಳ ಸಾರಾಂಶ, R ಅಥವಾ Pythonಗೆ ಕೋಡ್ ಸಲಹೆ, ಸಾಂಖ್ಯಿಕ ಫಲಿತಾಂಶಗಳ ವಿವರಣೆ ಮತ್ತು ಗುಣಾತ್ಮಕ ದತ್ತಾಂಶದ ಮೊದಲ ಹಂತದ ಸಂಕೇತೀಕರಣಕ್ಕೆ ನೆರವಾಗಬಹುದು. ಏಜೆಂಟಿಕ್ AI ಇನ್ನೂ ಮುಂದೆ ಹೋಗುತ್ತದೆ: ಏಜೆಂಟ್‌ಗಳು ಬಹು-ಹಂತದ ಕಾರ್ಯಗಳನ್ನು ಯೋಜಿಸಿ, ಮೂಲಗಳನ್ನು ಹುಡುಕಿ, ಕೋಡ್ ನಡೆಸಿ, ತಮ್ಮದೇ ಕೆಲಸವನ್ನು ಪರಿಷ್ಕರಿಸುತ್ತವೆ — ಸಂಶೋಧಕರ ಮೇಲ್ವಿಚಾರಣೆಯಲ್ಲಿ.","ಅವಕಾಶಗಳು: ವೇಗದ ಸಾಹಿತ್ಯ ನಕ್ಷೆ, ಪುನರುತ್ಪಾದಿಸಬಹುದಾದ ವಿಶ್ಲೇಷಣಾ ಸ್ಕ್ರಿಪ್ಟ್‌ಗಳು, ದ್ವಿಭಾಷಾ ಸಾಧನಗಳಿಗೆ ಅನುವಾದ ನೆರವು, ಪ್ರವೇಶಸಾಧ್ಯತೆ. ಅಪಾಯಗಳು: ಕಲ್ಪಿತ ಸತ್ಯಗಳು ಮತ್ತು ಉಲ್ಲೇಖಗಳು, ಗುಪ್ತ ಪಕ್ಷಪಾತ, ಸಂಶೋಧಕರ ಸ್ವಂತ ವಿವೇಚನೆಯ ನಷ್ಟ, ಗೌಪ್ಯತಾ ಉಲ್ಲಂಘನೆ, ಮತ್ತು ಯಾರೂ ಪರಿಶೀಲಿಸದ ಫಲಿತಾಂಶಗಳ ಮೇಲಿನ ಅತಿ ಅವಲಂಬನೆ. ತಾವಾಗಿ ಕ್ರಿಯೆ ನಡೆಸುವ ಏಜೆಂಟ್‌ಗಳಿಗೆ ಸ್ಪಷ್ಟ ಮಿತಿಗಳು, ದಾಖಲೆಗಳು ಮತ್ತು ಪ್ರತಿ ಮುಖ್ಯ ಹಂತಕ್ಕೆ ಮಾನವ ಅನುಮೋದನೆ ಬೇಕು.","ಜವಾಬ್ದಾರಿಯುತ ಬಳಕೆಯ ಕ್ರಮ: ಸಾಧನ ಏನು ಮಾಡಬಹುದು ಮತ್ತು ಮಾಡಬಾರದು ಎಂದು ನಿರ್ಧರಿಸಿ; ವೈಯಕ್ತಿಕ ದತ್ತಾಂಶವನ್ನು ಎಂದಿಗೂ ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಡಿ; ಪ್ರತಿ ಸತ್ಯ, ಉಲ್ಲೇಖ ಮತ್ತು ಅಂಕಿಯನ್ನು ಮೂಲದಲ್ಲಿ ಪರಿಶೀಲಿಸಿ; ಪ್ರಾಂಪ್ಟ್‌ಗಳು ಮತ್ತು ಫಲಿತಾಂಶಗಳನ್ನು ಲೆಕ್ಕಪರಿಶೋಧನಾ ಜಾಡಿನ ಭಾಗವಾಗಿ ಉಳಿಸಿ; ಲೇಖನದಲ್ಲಿ ಬಳಕೆಯನ್ನು ಘೋಷಿಸಿ; ವ್ಯಾಖ್ಯಾನ ಮತ್ತು ತೀರ್ಮಾನಗಳು ನಿಮ್ಮದೇ ಆಗಿರಲಿ.","ಬೃಹತ್ ದತ್ತಾಂಶ ಮತ್ತು ಅಂತರಶಿಸ್ತೀಯ ಸಂಶೋಧನೆ: ದೊಡ್ಡ ಆಡಳಿತಾತ್ಮಕ ದತ್ತಾಂಶಗಳು (UDISE+, SATS ಒಟ್ಟು ಅಂಕಿಗಳು, ಮೌಲ್ಯಮಾಪನ ಪೋರ್ಟಲ್‌ಗಳು, ಕಲಿಕಾ-ಆ್ಯಪ್ ದಾಖಲೆಗಳು) ಜನಸಂಖ್ಯಾ ಮಟ್ಟದ ವಿಶ್ಲೇಷಣೆ ಮತ್ತು ಕಲಿಕಾ ವಿಶ್ಲೇಷಣೆಗೆ ಅವಕಾಶ ನೀಡುತ್ತವೆ, ಆದರೆ ಅನುಮತಿ, ಗುರುತು ತೆಗೆಯುವಿಕೆ ಮತ್ತು ಭಾರತದ ಡಿಜಿಟಲ್ ವೈಯಕ್ತಿಕ ದತ್ತಾಂಶ ಸಂರಕ್ಷಣಾ ಕಾಯ್ದೆ, 2023ರ ಅಡಿಯಲ್ಲಿ ಎಚ್ಚರಿಕೆ ಬೇಕು. ಪೋಷಣೆ ಮತ್ತು ಕಲಿಕೆ, ವಲಸೆ ಮತ್ತು ಶಾಲೆ ಬಿಡುವಿಕೆ, ತಂತ್ರಜ್ಞಾನ ಮತ್ತು ಸಮಾನತೆಯಂತಹ ಅನೇಕ ಶೈಕ್ಷಣಿಕ ಪ್ರಶ್ನೆಗಳನ್ನು ಸಾರ್ವಜನಿಕ ಆರೋಗ್ಯ, ಅರ್ಥಶಾಸ್ತ್ರ, ದತ್ತಾಂಶ ವಿಜ್ಞಾನ ಮತ್ತು ಸಮಾಜಶಾಸ್ತ್ರದ ಸಹೋದ್ಯೋಗಿಗಳೊಂದಿಗೆ ಅಧ್ಯಯನ ಮಾಡುವುದು ಉತ್ತಮ."]}],"karnataka":[{"title":"ಸ್ವ-ಸಾಮರ್ಥ್ಯ CFAಗೆ ಫಲಿತಾಂಶ ಪರಿಚ್ಛೇದ","text":["\"ಮೂರು-ಅಂಶಗಳ CFA (maximum likelihood, AMOS; N = 240) ಉತ್ತಮ ಹೊಂದಾಣಿಕೆ ತೋರಿಸಿತು, χ²(51) = 85.2, p = .002, CFI = .97, TLI = .96, RMSEA = .053 [90% CI .031, .073], SRMR = .045. ಎಲ್ಲಾ ಪ್ರಮಾಣೀಕೃತ ಭಾರಗಳು ಮಹತ್ವದ್ದಾಗಿದ್ದವು (.68–.86). ಸಂಯೋಜಿತ ವಿಶ್ವಸನೀಯತೆ .82 ರಿಂದ .88 ಮತ್ತು AVE .55 ರಿಂದ .64; ಪ್ರತಿ AVEಯ ವರ್ಗಮೂಲ ಅಂಶಗಳ ನಡುವಿನ ಸಹಸಂಬಂಧಗಳನ್ನು (.41–.58) ಮೀರಿತು — ಭೇದಾತ್ಮಕ ಸಿಂಧುತ್ವಕ್ಕೆ ಬೆಂಬಲ.\" (ಉದಾಹರಣಾ ಮೌಲ್ಯಗಳು.)"]},{"title":"ಎಚ್ಚರಿಕೆಯೊಂದಿಗೆ ಬೃಹತ್ ದತ್ತಾಂಶ: SATS ಒಟ್ಟು ಅಂಕಿಗಳು","text":["1,200 ಶಾಲೆಗಳಲ್ಲಿ ಹಾಜರಾತಿ ಮಾದರಿಗಳು 7ನೇ ತರಗತಿ LBA ಅಂಕಗಳನ್ನು ಮುನ್ಸೂಚಿಸುತ್ತವೆಯೇ ಎಂದು ಡಯಟ್ ಅಧ್ಯಯನ ಮಾಡಲು ಬಯಸುತ್ತದೆ. ಅದು ಮಗು-ಮಟ್ಟದ ದಾಖಲೆಗಳ ಬದಲು ಶಾಲಾ-ಮಟ್ಟದ ಒಟ್ಟು ಅಂಕಿಗಳನ್ನು ಕೇಳುತ್ತದೆ, ಇಲಾಖೆಯ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ, ತನ್ನ ಕೋಡ್ ದಾಖಲಿಸುತ್ತದೆ, ಮತ್ತು AI ಸಹಾಯಕವನ್ನು ಕೇವಲ ನಕಲಿ ದತ್ತಾಂಶದ ಮೇಲೆ ವಿಶ್ಲೇಷಣಾ ಸ್ಕ್ರಿಪ್ಟ್ ಬರೆಯಲು ಮತ್ತು ದೋಷ ಸರಿಪಡಿಸಲು ಬಳಸುತ್ತದೆ — ನಿಜವಾದ ಕಡತದ ಮೇಲೆ ಎಂದಿಗೂ ಅಲ್ಲ. ಸಣ್ಣ ಶಾಲೆಗಳನ್ನು ಹೆಸರಿಸದಂತೆ ನೀತಿ ಸಂಕ್ಷೇಪ ಮಾದರಿಗಳನ್ನು ಬ್ಲಾಕ್‌ವಾರು ವರದಿ ಮಾಡುತ್ತದೆ, ಶಾಲಾವಾರು ಅಲ್ಲ."]}],"activity":{"title":"ಬರೆಯಿರಿ ಮತ್ತು ಜವಾಬ್ದಾರಿಯುತ AI ಬಳಕೆ ಯೋಜಿಸಿ","prompt":"ಹೊಂದಾಣಿಕೆ ಪರಿಶೀಲಕ ಅಥವಾ CFA ಗಣಕದ ಫಲಿತಾಂಶ ಬಳಸಿ APA ಶೈಲಿಯಲ್ಲಿ ಫಲಿತಾಂಶ ಪರಿಚ್ಛೇದ ಬರೆಯಿರಿ. ನಂತರ AI ಪ್ರಾಂಪ್ಟ್ ಯೋಜಕದಲ್ಲಿ ಜವಾಬ್ದಾರಿಯುತ AI ಪರಿಶೀಲನಾ ಪಟ್ಟಿ ಪೂರ್ಣಗೊಳಿಸಿ, ನಿಮ್ಮ ಮುಂದಿನ ಲೇಖನಕ್ಕೆ AI ಬಳಕೆ ಘೋಷಣೆಯನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ."},"quiz":[{"q":"SEM ಲೇಖನದ ವಿಧಾನ ವಿಭಾಗದಲ್ಲಿ ಇರಬೇಕಾದದ್ದು ಯಾವುದು?","options":["ಊಹೆಗಳು ಮಾತ್ರ","ಅಂದಾಜುಗಾರ, ತಂತ್ರಾಂಶ, ಕಾಣೆಯಾದ ದತ್ತಾಂಶ ನಿರ್ವಹಣೆ ಮತ್ತು ಹೊಂದಾಣಿಕೆ ಮಾನದಂಡಗಳು","ನೀತಿ ಪರಿಣಾಮಗಳು","ಮುಖಪತ್ರ"],"why":"ಇತರರು ಪುನರಾವರ್ತಿಸುವಂತೆ ವಿಶ್ಲೇಷಣೆ ಹೇಗೆ ನಡೆಯಿತು ಎಂದು ವಿಧಾನ ತಿಳಿಸುತ್ತದೆ."},{"q":"ಶುಲ್ಕಕ್ಕೆ 72 ಗಂಟೆಗಳಲ್ಲಿ ಸ್ವೀಕಾರ ಭರವಸೆ ನೀಡುವ ನಿಯತಕಾಲಿಕ. ನೀವು…","options":["ಬೇಗ ಸಲ್ಲಿಸಿ","ಶೋಷಕ ನಿಯತಕಾಲಿಕವೆಂದು ಪರಿಗಣಿಸಿ ಸೂಚೀಕರಣ ದತ್ತಸಂಚಯಗಳಲ್ಲಿ ಪರಿಶೀಲಿಸಿ","ಮೊದಲು ಹಣ ಕಟ್ಟಿ ನಂತರ ಕೇಳಿ","ನಿಮ್ಮ ಅವಲೋಕನದಲ್ಲಿ ಉಲ್ಲೇಖಿಸಿ"],"why":"ಖಚಿತ ವೇಗದ ಸ್ವೀಕಾರ ಶೋಷಕ ಅಭ್ಯಾಸದ ಸಾಮಾನ್ಯ ಲಕ್ಷಣ."},{"q":"ಸಾಮಾನ್ಯ ಸಂವಾದ ಸಹಾಯಕನಿಂದ ಏಜೆಂಟಿಕ್ AI ಹೇಗೆ ಭಿನ್ನ?","options":["ಅದು ಸಾಧನಗಳನ್ನು ಬಳಸಲಾರದು","ಅದು ಹುಡುಕಾಟ ಮತ್ತು ಕೋಡ್ ನಡೆಸುವಂತಹ ಬಹು-ಹಂತದ ಕಾರ್ಯಗಳನ್ನು ಯೋಜಿಸಿ ನಡೆಸುತ್ತದೆ","ಅದು ಎಂದಿಗೂ ತಪ್ಪು ಮಾಡುವುದಿಲ್ಲ","ಅದನ್ನು ಲೇಖಕರನ್ನಾಗಿ ಸೇರಿಸಬಹುದು"],"why":"ಏಜೆಂಟ್‌ಗಳು ಹಲವು ಹಂತಗಳಲ್ಲಿ ಕ್ರಿಯೆ ನಡೆಸುವುದರಿಂದ ಮಿತಿಗಳು ಮತ್ತು ಮಾನವ ಮೇಲ್ವಿಚಾರಣೆ ಬೇಕು."},{"q":"ಜವಾಬ್ದಾರಿಯುತ AI ಬಳಕೆಯಲ್ಲಿ ಸಂಶೋಧಕರು…","options":["ವೇಗದ ವಿಶ್ಲೇಷಣೆಗೆ SATS ದತ್ತಾಂಶ ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು","AI ನೀಡಿದ ಪ್ರತಿ ಸತ್ಯವನ್ನು ಪರಿಶೀಲಿಸಿ AI ಬಳಕೆಯನ್ನು ಘೋಷಿಸಬೇಕು","ತೀರ್ಮಾನಗಳನ್ನು AI ಬರೆಯಲು ಬಿಡಬೇಕು","AI ಬಳಕೆಯನ್ನು ಮರೆಮಾಚಬೇಕು"],"why":"ಪರಿಶೀಲನೆ ಮತ್ತು ಘೋಷಣೆ ಪ್ರಾಮಾಣಿಕತೆಯನ್ನು ಕಾಪಾಡುತ್ತವೆ."}]}}}$book$::jsonb, now())
on conflict (id) do update set data = excluded.data, updated_at = now();
